window.JASTROW_CHUNKS[2]={"800":{"h":"אוֹפְיָא","r":"A00800","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אוֹף I\">אוף</a>; v. <a href=\"#\" data-headword=\"*אָנַף\">אנף</a>; b. h. <i>what is blown off, foam, froth</i>. Ab. Zara 26ᵃ כי א׳ דימא Ms. M. (ed. <span dir=\"rtl\">דנהרא</span>, v. Rabb. D. S. a. l., a. Ar. ed. Koh. s. v. <a href=\"#\" data-headword=\"אפי\">אפי</a>) as the foam of the Sea [river]; (Ar. <i>as logs on the river</i>, v. <a href=\"#\" data-headword=\"אוּפְתָּא\">אוּפְתָּא</a>, <a href=\"#\" data-headword=\"אוּפֵי\">אוּפֵי</a>). Ib. 70ᵇ <span dir=\"rtl\">הוות נקיטא א׳</span> (Var. <a href=\"#\" data-headword=\"חוּפְיָא\">חופיא</a>, <a href=\"#\" data-headword=\"ה׳\">ה׳</a>, v. Rabb. D. S. a. l. note 20) she took the froth off. <span class=\"citation\">Ḥull. 105ᵇ</span> <a href=\"#\" data-headword=\"א׳\">א׳</a> (Ar. <a href=\"#\" data-headword=\"ה׳\">ה׳</a>).</div>","alt":["(הוֹפְיָא)"]},"801":{"h":"*אוֹפְיוֹן","r":"A00801","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ὄπιον) <i>poppy-juice, opium</i>. <span class=\"citation\">Y. Ab. Zar. II, 40ᵈ</span> top <span dir=\"rtl\">אהן א׳ סכנה</span> an opium drink (prepared by a gentile) is dangerous.</div>","alt":[]},"802":{"h":"אופיטא","r":"A00802","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַנְטִיפִּיטָא\">אַנְטִיפִּיטָא</a></div>","alt":[]},"803":{"h":"אוּפְיֵי","r":"A00803","html":"<div class=\"sense\"><i>twigs</i>, v. <a href=\"#\" data-headword=\"אוּפֵי\">אוּפֵי</a>.</div>","alt":[]},"804":{"h":"אוֹפִיכָא","r":"A00804","html":"<div class=\"sense\"> (<span dir=\"rtl\">אוֹפְכָיָיא</span> f.) (<span dir=\"rtl\">אפך</span>) <i>destruction, ruin</i>. <span class=\"citation\">Lam. R. to III, 13</span> (expl. <span dir=\"rtl\">בני אשפתו</span> ibid., v. <a href=\"#\" data-headword=\"אַשְׁפָּה\">אַשְׁפָּה</a>) <span dir=\"rtl\">בני אוֹפִיכֵיה</span> (Var. <span dir=\"rtl\">אוֹפְכָיֵיה</span>) the children of those he laid in ruins; v. <a href=\"#\" data-headword=\"*אִימְרָיָיא\">אִימְרָיָיא</a>. [Differ. in <span class=\"citation\">Esth. R. to I, 1</span>ᵇ, v. <a href=\"#\" data-headword=\"*אוּכַּיְיפָא\">אוּכַּיְיפָא</a> a. <a href=\"#\" data-headword=\"*אֲמוּרְיָא\">אֲמוּרְיָא</a>.]</div>","alt":[]},"805":{"h":"אופילין","r":"A00805","html":"<div class=\"sense\"> <span class=\"citation\">Tosef. Ter. II, 4</span>, v. <a href=\"#\" data-headword=\"אֲפוֹלִים\">אֲפוֹלִים</a></div>","alt":[]},"806":{"h":"*אופימטטאטא","r":"A00806","html":"<div class=\"sense\">, read <span dir=\"rtl\">אוּפֹּומְנֵימָאטָא</span> m. pl. (ὑπομνήματα) <i>public records, acts</i>. <span class=\"citation\">Ex. R. s. 28</span> a king wanted <span dir=\"rtl\">לעשות א׳ חוץ וכ׳</span> to pass acts without consulting the lieutenant-governor (hyparch).</div>","alt":["אופימשט׳"]},"807":{"h":"אוֹפִיקְיָלִין","r":"A00807","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (officialis, ὀφφικιάλιος) <i>subordinate officials, constables</i>. Y’lamd. Balak (quot. in Ar. s. v. <span dir=\"rtl\">בלש</span>) <a href=\"#\" data-headword=\"*אימיקנטרון\">או׳</a> ed. Koh. Ib. <span dir=\"rtl\">שלח אפיקלין</span> (corr. acc.) he sent constables (for her son).</div>","alt":[]},"808":{"h":"אוֹפִיתָא","r":"A00808","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(= h. <a href=\"#\" data-headword=\"אוֹפִי\">אוֹפִי</a>) <i>nature, disposition</i>. <span class=\"citation\">Gen. R. s. 14</span>, end, v. <a href=\"#\" data-headword=\"אוֹפִי\">אוֹפִי</a>.</div>","alt":[]},"809":{"h":"אופכי","r":"A00809","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַפּוּכִי\">אַפּוּכִי</a></div>","alt":["אופכין"]},"810":{"h":"אוֹפֶל","r":"A00810","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>darkness</i>. <span class=\"citation\">Gen. R. s. 89</span>, beg. v. <a href=\"#\" data-headword=\"אֲפֵילָה\">אֲפֵילָה</a>.</div>","alt":[]},"811":{"h":"אוֹפָן","r":"A00811","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , v. <span dir=\"rtl\">פנה</span>) </div><div class=\"sense\"><b>1)</b> <i>wheel</i>.</div><div class=\"sense\"><b>—2)</b>  (with ref. to <span class=\"citation\">Ezek. I, 15</span>) pr. n. <i>Ofan</i>, name of an angel. <span class=\"citation\">Ḥag. 13ᵇ</span>.—Pl. <span dir=\"rtl\">אוֹפַנִּים</span>. <span class=\"citation\">Ib. 12ᵇ</span>. <span class=\"citation\">R. Hash. 24ᵇ</span>.—[In liturgic literature <span dir=\"rtl\">אופנים</span> and <span dir=\"rtl\">אופן</span> are used as the names of a section of the morning prayers; v. <a href=\"#\" data-headword=\"אוֹפַנָּא\">אוֹפַנָּא</a>.]</div>","alt":[]},"812":{"h":"אוֹפֶן","r":"A00812","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>turn, method, plan</i>. [In later Hebr.: <i>method of interpretation</i> = <a href=\"#\" data-headword=\"פָּנִים\">פָּנִים</a>.]—Pl. <span dir=\"rtl\">אוֹפָנִים</span>; <i>Du.</i> <span dir=\"rtl\">אוֹפְנַיִים</span>. Ruth. R. s. 2, beg. You will soon find out <span dir=\"rtl\">איפניים שלהם וכ׳</span> (<span class=\"citation\">Yalk. Josh. 7</span> <span dir=\"rtl\">אופנים</span>) their plans (strategic movements). Ab. d’R. Nath. (ed. Taussig, N’veh Shal. p. 12) <span dir=\"rtl\">על אופניו</span> in its proper way.</div>","alt":[]},"813":{"h":"אוֹפַנָּא","r":"A00813","html":"<div class=\"sense\">—Pl. <span dir=\"rtl\">אוֹפַנַּיָּא</span>. <span class=\"citation\">Targ. Ezek. X, 13</span>.—אוֹפַנַּיָּיה <i>that section of the morning prayers beginning with v’haofannim</i> and describing the angelic praises. <span class=\"citation\">Y. Ber. V, 9ᶜ</span> bot.</div>","alt":[]},"814":{"h":"אוֹפְנָא","r":"A00814","html":"<div class=\"sense\"><i>turn, interpretation, qualification</i>. <span class=\"citation\">Y. Dem. VI, 25ᵇ</span> bot. <span dir=\"rtl\">א׳ לית לון א׳ לית לסתמא</span> we do not recognize an interpretation (of an agreement, so as to say, <span dir=\"rtl\">נעשה כאומר וכ׳</span> ‘it means as though they had said—’); no qualification is admissible for an unqualified agreement.</div>","alt":[]},"815":{"h":"אוּפְסַיִם","r":"A00815","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> du. (cmp. <a href=\"#\" data-headword=\"אֶפֶס\">אֶפֶס</a>—, a. <a href=\"#\" data-headword=\"פַּס I\">פֵּס</a>, <span dir=\"rtl\">פִּסָּה</span>) <i>palms of the hand</i>. Mekh. B’shall. Vayissa, s. 3, to <span class=\"citation\">Ex. XVI, 12</span> the Mannah came down <span dir=\"rtl\">על האו׳ וכ׳</span> on the hands of the Lord, as if it were to say, the Lord held forth &amp;c. [In some ed. <a href=\"#\" data-headword=\"אוּפְסִין\">אוּפְסִין</a>.]</div>","alt":[]},"816":{"h":"אוּפְסִין","r":"A00816","html":"<div class=\"sense\"> m. pl., v. <a href=\"#\" data-headword=\"אוּפְסַיִם\">foreg.</a></div>","alt":[]},"817":{"h":"אופסנון","r":"A00817","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אָפְסוֹנִין\">אָפְסוֹנִין</a></div>","alt":[]},"818":{"h":"אוּפְתָּא","r":"A00818","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אוּפֵי\">אוּפֵי</a>) prop. <i>the large central branch</i>, hence <i>trunk, stalk</i>. <span class=\"citation\">Succ. 32ᵃ</span> <span dir=\"rtl\">ואימא א׳</span> may I not say (as you insist on the palm-branch being <i>kafuth</i>, tied, joined) that I must use the stalk?—<span class=\"citation\">Ḥull. 47ᵇ</span> lungs resembling <span dir=\"rtl\">לא׳</span> a trunk (in color, touch &amp;c.). <span class=\"citation\">Ib. 16ᵃ</span> <span dir=\"rtl\">וי&quot;ו דכתיב אא׳</span> a Vav. written on a trunk (being broken on account of the rough surface = <i>idle-talk</i>).</div>","alt":[]},"819":{"h":"אוּפְתֵּיק","r":"A00819","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"הֶפְתֵּק\">הֶפְתֵּק</a>.</div>","alt":["אוּפְתֵּק"]},"820":{"h":"אוּץ","r":"A00820","html":"<div class=\"sense\"> , v. <span dir=\"rtl\">אוי I</span>; cmp. <a href=\"#\" data-headword=\"אָפַץ\">אָפַץ</a>; v. <a href=\"#\" data-headword=\"חוּץ\">חוּץ</a> a. <a href=\"#\" data-headword=\"חָצָה\">חָצָה</a>) <i>to be pressed</i> (<i>to press, hurry</i>).—Part. <span dir=\"rtl\">אוֹצֶה</span>, pl. <span dir=\"rtl\">אוֹצִין</span> (as from <span dir=\"rtl\">אצה</span>, v. <a href=\"#\" data-headword=\"חוּץ\">חוּץ</a>, <a href=\"#\" data-headword=\"חוּל\">חוּל</a>) <i>squeezed in</i>. <span class=\"citation\">Tosef. Kel. B. Mets. IX, 5</span> <span dir=\"rtl\">א׳ חבור</span> (Var. <a href=\"#\" data-headword=\"הוּץ II\">הוצין</a>) when they are squeezed in (tight), they are considered as connected for levitical purposes.</div>","alt":[]},"821":{"h":"אוּצְבָּתָא","r":"A00821","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֶצְבְּעָא\">אֶצְבְּעָא</a> a. <a href=\"#\" data-headword=\"אֶצְבָּעִי\"><a href=\"#\" data-headword=\"אֶצְבָּעִי\">אֶצְבָּעִי</a>.</a></div>","alt":[]},"822":{"h":"אוּצְיָא","r":"A00822","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אָצְיָא</span></div>","alt":[]},"823":{"h":"אוציטילין","r":"A00823","html":"<div class=\"sense\"> read <span dir=\"rtl\">אִיצְטוֹלִין</span>, v. <a href=\"#\" data-headword=\"אִסְטְלָא\">אִסְטְלָא</a></div>","alt":[]},"824":{"h":"אוֹצֶן","r":"A00824","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"הוֹצֶן\">הוֹצֶן</a></div>","alt":[]},"825":{"h":"אוֹצָר","r":"A00825","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>store-house, magazine; provision; hoarded up treasure</i>. <span class=\"citation\">B. Bath. 58ᵃ</span>; <span class=\"citation\">Git. 67ᵃ</span>, v. <a href=\"#\" data-headword=\"בָּלַם I\">בָּלַם</a> a. <a href=\"#\" data-headword=\"בָּלַס\">בָּלַס</a>. <span class=\"citation\">Ab. Zar. 40ᵇ</span>; v. <a href=\"#\" data-headword=\"הֶפְתֵּק\">הֶפְתֵּק</a>; a. fr.—Esp. <i>treasury, the</i> (<i>Roman</i>) <i>government’s treasury department</i> where taxes in kind and money had to be paid. <span class=\"citation\">Y. Dem. VI, end, 26ᵃ</span> <span dir=\"rtl\">ושקול על ידי לא׳</span> and pay for me in the treasury-department. <span class=\"citation\">Tosef. Dem. VI, 4</span> <span dir=\"rtl\">ושקול תחתיי מן הא׳</span> (read <span dir=\"rtl\">אל הא׳</span>). <span class=\"citation\">Ib. 3</span> <span dir=\"rtl\">ושוקל לא׳</span> ed. Zuck. (ed. incorr. <span dir=\"rtl\">ואוצר</span>). <span class=\"citation\">Ib. 4</span> <span dir=\"rtl\">פוטריני מן הא׳</span> get me a release from the treasury-dep.—Y. Dem. l. c. <span dir=\"rtl\">פרשיני מן הא׳</span> (read <span dir=\"rtl\">פוטריני</span>). <span class=\"citation\">Ab. Zar. 71ᵃ</span> <span dir=\"rtl\">לא׳</span>, <span dir=\"rtl\">מן הא׳</span>, Ms. M. (ed. <a href=\"#\" data-headword=\"עוֹצָר\">עוצר</a>); cmp. <a href=\"#\" data-headword=\"אָצַר\">אָצַר</a>.—Pl. <span dir=\"rtl\">אוֹצָרוֹת</span>. <span class=\"citation\">B. Bath. 11ᵃ</span> גנזו א׳ Ms. (ed. <a href=\"#\" data-headword=\"א׳\">א׳</a> omitted); v. <a href=\"#\" data-headword=\"גָּנַז\">גָּנַז</a>.—<span class=\"citation\">Ḥag. 12ᵇ</span> <span dir=\"rtl\">אוֹצְרוֹת שלג וכ׳</span> the stores of snow &amp;c. (in the heavens); a. fr. V. <a href=\"#\" data-headword=\"אֹצְרוֹת\">אֹצְרוֹת</a>, <a href=\"#\" data-headword=\"אֹצְרוֹת\">א׳ רוח</a>.</div>","alt":[]},"826":{"h":"אוֹצָרָא","r":"A00826","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Jer. XXXVIII, 11</span>; a. fr.—Pl. <span dir=\"rtl\">אוֹצְרִין</span>, <span dir=\"rtl\">אוֹצְרַיָּא</span>. <span class=\"citation\">Targ. Gen. XLI, 56</span>; a. e.</div>","alt":[]},"827":{"h":"אוקומיני","r":"A00827","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיקוּמֵינֵי\">אִיקוּמֵינֵי</a></div>","alt":[]},"828":{"h":"אוקונים","r":"A00828","html":"<div class=\"sense\">, read <a href=\"#\" data-headword=\"אִיקוֹנִין\">אִיקוֹנִין</a>, v. <a href=\"#\" data-headword=\"אִיקוֹן\">אִיקוֹן</a></div>","alt":[]},"829":{"h":"אוקטוריא","r":"A00829","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אקט׳</span></div>","alt":["אוקטר׳"]},"830":{"h":"אוֹקִי","r":"A00830","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"אוֹקִים\">אוֹקִים</a>, v. <a href=\"#\" data-headword=\"קוּם\">קוּם</a></div>","alt":[]},"831":{"h":"אוקי","r":"A00831","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אוקיי\">אוקיי</a></div>","alt":[]},"832":{"h":"*אוּקְיָא","r":"A00832","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"אוּנְקְיָא\">אוּנְקְיָא</a> [?] <span class=\"citation\">Ex. R. s. 43</span>, beg.—[Pl. <a href=\"#\" data-headword=\"*אוקיי\">אוּקְיֵי</a>. <span class=\"citation\">Ber. 44ᵇ</span> <span dir=\"rtl\">משיתא א׳ סולתא</span>, Ar. s. v. <span dir=\"rtl\">גלגל I</span>, ‘than six ouncess of fine flour’.—Ed. <span dir=\"rtl\">קייסי</span>; Ms. M. omits the entire sentence.]</div>","alt":[]},"833":{"h":"אוֹקְיָאנוֹס","r":"A00833","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹקְיָינוֹס\">אוֹקְיָינוֹס</a></div>","alt":[]},"834":{"h":"*אוקיי","r":"A00834","html":"<div class=\"sense\"> (Muss. <a href=\"#\" data-headword=\"אווקי\">אווקי</a>) <span class=\"citation\">Cant. R. to VII, 8</span>, read <a href=\"#\" data-headword=\"אוֹקְיָינוֹס\">אוֹקְיָינוֹס</a>. <span dir=\"rtl\">כמין א׳</span> inundating like an Ocean tide; v. <a href=\"#\" data-headword=\"*טלנס\">טלנס</a></div>","alt":[]},"835":{"h":"אוֹקְיָינוֹס","r":"A00835","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Ὠκέανος) <i>Ocean</i>, mostly <i>Mediterranean Sea</i>. <span class=\"citation\">Targ. Y. Gen. I, 7</span>; a. e.—Y. Ḥall. IV, 60ᵃ bot.; a. fr.—Tanḥ. Ḥaye 3, and so is <span dir=\"rtl\">א׳ ים המת</span> the Okeanos called the Sea of (covering) the dead. [Var. <a href=\"#\" data-headword=\"אֶנְקְלִיטוֹן\">אונק׳</a>, <span dir=\"rtl\">אנק׳</span>.]</div>","alt":["אוֹקְיָנוֹס","אוֹקְיָאנוֹס"]},"836":{"h":"אוֹקִים","r":"A00836","html":"<div class=\"sense\"> Af. of <a href=\"#\" data-headword=\"קוּם\">קוּם</a> ch.</div>","alt":[]},"837":{"h":"אוֹקִימוּתָא","r":"A00837","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">קום</span>) <i>raising</i>, [<i>rising</i>]. <span class=\"citation\">Targ. Ps. CXXXIX, 2</span> [prob. <a href=\"#\" data-headword=\"אוֹקִימוּתָא\">אוֹקָמוּתָא</a>].</div>","alt":[]},"838":{"h":"אוקינין","r":"A00838","html":"<div class=\"sense\">, read <a href=\"#\" data-headword=\"אִיקוֹנִין\">אִיקוֹנִין</a>.</div>","alt":[]},"839":{"h":"אוּקְצָא","r":"A00839","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"עוּקְצָא\">עוּקְצָא</a></div>","alt":[]},"840":{"h":"אוֹר I","r":"A00840","html":"<div class=\"sense\"><i>to perforate, break through, shine</i>.—Denom. <a href=\"#\" data-headword=\"אָוִיר\">אַוִּיר</a>, <span dir=\"rtl\">מְאוּרָה</span></div><div class=\"sense\"><b>Nif. נֵאוֹר</b> <div class=\"sense\"><i>to be broken through, grow light</i>. Y. Ber. I, 2ᶜ <span dir=\"rtl\">משיֵאוֹר המזרח</span> from the time the Eastern horizon is broken through, grows light.</div></div><div class=\"sense\"><b>Hif. הֵאִיר</b> <div class=\"sense\"><b>1)</b>  (neut. v.) (neut. v.) <i>to break through, shine</i>. Y. ib. III, 6ᶜ bot. open thy lips <span dir=\"rtl\">ויָאִירוּ דבריך</span> and let thy words come forth, speak out boldly. <span class=\"citation\">Yoma III, 1</span> <span dir=\"rtl\">ה׳ פני כל וכ׳</span> it has grown light all over the Eastern horizon.—פנים מֵאִירוֹת <i>bright countenance</i>. <span class=\"citation\">Num. R. s. 11</span>; a. e.</div><div class=\"sense\"><b>—2)</b>  (act. v.) <i>to enlighten, brighten, make shine</i>. Y. M. Kat. III, 83ᵇ <span dir=\"rtl\">ה׳ עיניו וכ׳</span> (the teacher had opened his (Samuel’s) eyes &amp;c. <span class=\"citation\">B. Mets. 33ᵃ</span>. Num. R. l. c. Ib. <span dir=\"rtl\">המזבח מֵאִירִים את</span> (fr. <span class=\"citation\">Mal. I, 10</span>) making the altar bright (with fire), feeding the fire on the altar. <span class=\"citation\">Yoma 73ᵇ</span>, v. <a href=\"#\" data-headword=\"אוּר I\">אוּר</a>.</div></div>","alt":[]},"841":{"h":"אוֹר","r":"A00841","html":"<div class=\"sense\"> Part. pass. <a href=\"#\" data-headword=\"אוֹר I\">נָאוֹר</a> <i>clear</i>. <span class=\"citation\">Targ. Prov. IV, 25</span> <span dir=\"rtl\">נְאוֹרָן</span>, <span dir=\"rtl\">נְאֹרָן</span>, v. <a href=\"#\" data-headword=\"חֲוַר\">חֲוַר</a>.</div>","alt":[]},"842":{"h":"אוֹר II","r":"A00842","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"אוֹר\">foreg.</a>) <i>breaking forth</i> (cmp. <span class=\"citation\">Is. LVIII, 8</span>) whence </div><div class=\"sense\"><b>1)</b> <i>break of day, light, day; fire;</i> trnsf. <i>rise, glory, power, happiness</i>. <span class=\"citation\">Ber. 2ᵇ</span> <span dir=\"rtl\">ביאת אוֹרוֹ</span> the entrance of his day-break (dawn of his eighth day; Tosaf. a. l. <i>the sunset</i> of his seventh day). <span class=\"citation\">Y. Pes. I, beg. 27ᵃ</span> <span dir=\"rtl\">א׳ החמה</span> sun-light. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">א׳ הנר</span> candle light. <span class=\"citation\">Keth. 111ᵇ</span> <span dir=\"rtl\">א׳ תורה</span> light of the Law. <span class=\"citation\">B. Bath. 4ᵃ</span> <span dir=\"rtl\">אוֹרוֹ של עולם</span> intellectual light of the wold (a great man; the Law). <span class=\"citation\">Num. R. s. 15</span> <span dir=\"rtl\">אור של מעלן</span> the celestial fire (believed to be the source of all light and fire); a. v. fr. </div><div class=\"sense\"><b>2)</b>  (breaking in of night) <i>twilight, evening</i>. <span class=\"citation\">Pes. I, 1</span> <span dir=\"rtl\">לארבעה וכ׳ א׳</span> on the evening (eve) of the fourteenth day of Nissan; v. discussion <span class=\"citation\">ibid. 2ᵃ</span> sq., about the meaning of our w. <span class=\"citation\">R. Hash. 22ᵇ</span>; <span class=\"citation\">Snh. 70ᵇ</span> <span dir=\"rtl\">לא׳ עיבורו</span> the evening following the eventual intercalation, i.e. the evening from the thirtieth of the past to the first of the beginning month.</div><div class=\"sense\"><b>—3)</b>  (homil. = <a href=\"#\" data-headword=\"אוֹרָה II\"><span dir=\"rtl\">אוֹרָה</span> II</a>) <i>rue</i>. <span class=\"citation\">Gen. R. s. 20</span> in the Pentat. of R. M. it read <span dir=\"rtl\">כתנות אור וכ׳</span> (in place of <span dir=\"rtl\">עור</span> <span class=\"citation\">Gen. III, 21</span>) this alludes to the garments of Adam resembling the rue, wide below and narrow above; Ar. (Rashi diff.).</div>","alt":[]},"843":{"h":"אוּר I","r":"A00843","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"אוֹר II\">foreg.</a>) prop. <i>light, flame;</i> esp. Pl. <span dir=\"rtl\">אוּרִים ותומים</span> <i>the Urim and Tummim</i> in the High-priest’s breast-plate. <span class=\"citation\">Yoma 73ᵇ</span> <span dir=\"rtl\">א׳ שמאירים את דבריהם</span> they are called <i>Urim</i> because they give their decisions in a clear way (not ambiguous as the oracles); cmp. Y. ib. VII, end, 44ᶜ. <span class=\"citation\">Sot. IX, 12</span>. Y. Kidd. IV, beg. 65ᵇ</div>","alt":[]},"844":{"h":"*אוּר II","r":"A00844","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"עוּר\">עוּר</a> q. v.) <i>chaff</i>. <span class=\"citation\">Y. Ab. Zar. II, 40ᵈ</span> <span dir=\"rtl\">א׳ דשערין</span> chaff of barley; (Y. Sabb. XIV, 14ᵈ <span dir=\"rtl\">עור דסערין</span>).</div>","alt":[]},"845":{"h":"אוּרָא I","r":"A00845","html":"<div class=\"sense\">, Pl. <span dir=\"rtl\">אוּרַיָּא</span> <i>the Urim</i>. <span class=\"citation\">Targ. Num. XXVII, 21</span>; a. e.</div>","alt":[]},"846":{"h":"*אוּרָא II","r":"A00846","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>skin</i>. <span class=\"citation\">Y. Ned. III beg. 37ᵈ</span> <a href=\"#\" data-headword=\"אוּרְיָא\">אוּרֵיה</a> (read <span dir=\"rtl\">אוּדְרֵיה</span>?, v. <a href=\"#\" data-headword=\"אֵדֶר I\"><span dir=\"rtl\">אֵדֶר</span> I</a>); v. however <span class=\"citation\">Y. Shebu. III, 34ᵈ</span></div>","alt":[]},"847":{"h":"אוֹרָאָה","r":"A00847","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>teaching, decision</i>. <span class=\"citation\">Targ. Ez. VII, 26</span>; a. e.</div>","alt":[]},"848":{"h":"אוּרְבָּא","r":"A00848","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">ארב</span>, <span dir=\"rtl\">ערב</span> <i>to braid, interlace</i> &amp;c.); pl. <span dir=\"rtl\">אוּרְבֵּי</span>, <a href=\"#\" data-headword=\"רְבֵי\">אָרְבֵּי</a> <i>meshes, void spaces, intervals</i>. <span class=\"citation\">Sabb. 50ᵇ</span> <span dir=\"rtl\">ביני או׳</span> ed. (Ar. <a href=\"#\" data-headword=\"רְבֵי\">ארבי</a>, Var. <a href=\"#\" data-headword=\"אַרְכִי I\">אַרְכֵי</a>, v. <a href=\"#\" data-headword=\"אַרְכָא I\"><span dir=\"rtl\">אַרְכָא</span> I</a>; <a href=\"#\" data-headword=\"אדכי\">אדכי</a>, v. Ar. ed. Koh. S. V. <a href=\"#\" data-headword=\"אַרְכִי I\">ארכי</a>, note) between the meshes or void spaces between the bricks. <span class=\"citation\">Git. 69ᵇ</span>. <span class=\"citation\">B. Bath. 3ᵃ</span> (Ms. <span dir=\"rtl\">ירכי</span>, oth. Var. v. Rabb. D. S. a. l. note).</div>","alt":["אָרְבָּא"]},"849":{"h":"אוּרְבִּינָא","r":"A00849","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">ארב</span>, v. <a href=\"#\" data-headword=\"אוּרְבָּא\">foreg.</a>, cmp. <span dir=\"rtl\">סבך</span>, <a href=\"#\" data-headword=\"סָכַךְ I\">סכך</a>) <i>brier, nettle</i> or a similar plant (corresp. to h. <span dir=\"rtl\">סרפד</span>). Targ. II, <span class=\"citation\">Esth. II, 7</span> (Ar. <span dir=\"rtl\">ארבניא</span>).</div>","alt":[]},"850":{"h":"אוּרְבָּנָא","r":"A00850","html":"<div class=\"sense\"><i>, </i> pl. <a href=\"#\" data-headword=\"אוּרְבָּנָא\">אוּרְבָּנֵי</a> m. (v. <a href=\"#\" data-headword=\"אוּרְבִּינָא\">foreg.</a>; cmp. <a href=\"#\" data-headword=\"עֲרָבָה I\">עֲרָבָה</a>) <i>bulrushes</i>. <span class=\"citation\">Sabb. 101ᵃ</span> <span dir=\"rtl\">קני ואו׳</span> (some ed. <span dir=\"rtl\">ואר׳</span>) reeds and bulrushes. <span class=\"citation\">Snh. 82ᵇ</span> <span dir=\"rtl\">בין קני לא׳ וכ׳</span> what has Sh’vilnai (a woman) to do between the reeds and the bulrushes? (prov. for suspicious movements of women). <span class=\"citation\">B. Bath. 6ᵃ</span>, v. <a href=\"#\" data-headword=\"צְרִיפָא\">צְרִיפָא</a>.</div>","alt":[]},"851":{"h":"*אוּרְבָּנִין","r":"A00851","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אוּרְבָּנָא\">foreg.</a>) name of a <i>seasoning reed</i>. <span class=\"citation\">Erub. 34ᵇ</span></div>","alt":[]},"852":{"h":"אורדי","r":"A00852","html":"<div class=\"sense\"> <span class=\"citation\">Kidd. 12ᵃ</span>, <span dir=\"rtl\">זוודא דא׳</span>, read <span dir=\"rtl\">דאוּדְרֵי</span> or <span dir=\"rtl\">דאוּדְדֵי</span>, v. <a href=\"#\" data-headword=\"אוּדְדָא\">אוּדְדָא</a></div>","alt":[]},"853":{"h":"*אוּרְדַּיָּא","r":"A00853","html":"<div class=\"sense\">, <span class=\"citation\">Keth. 67ᵃ</span> <span dir=\"rtl\">שקי דא׳</span> (Ms. <span dir=\"rtl\">אדוריא</span>, ed. <span dir=\"rtl\">רוֹדַיָּא</span>) prob. pr. n. pl. <i>Urdaya, Rodaya</i>, [or identical with <a href=\"#\" data-headword=\"אורדי\">foreg.</a> w.?].</div>","alt":[]},"854":{"h":"אוּרְדִּילָאֵי","r":"A00854","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אַרְדִּילַיָּא</span></div>","alt":[]},"855":{"h":"*אוּרְדָּךְ","r":"A00855","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">אוּדָּךְ</span>, <a href=\"#\" data-headword=\"דּוּךְ\">דוך</a>) <i>crushing tool, pestle</i>. <span class=\"citation\">Targ. Prov. XXVII, 22</span> some ed. (oth. <a href=\"#\" data-headword=\"*אוּדְרָךְ\">אוּדְרָךְ</a> q. v.). [The entire verse is corrupted, combining the traditional vers. with one from which LXX is translated.]</div>","alt":[]},"856":{"h":"אוּרְדְּעָה","r":"A00856","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"עוּרְדְּעָן\">עוּרְדְּעָן</a>, and its hebr. phonet. equival. <a href=\"#\" data-headword=\"צְפַרְדֵּעַ\">צְפַרְרֵּעַ</a>) <i>frog</i>. <span class=\"citation\">Koh. R. to V, 8</span>. <span class=\"citation\">Lev. R. s. 22</span> (<a href=\"#\" data-headword=\"אורדען\">אוּרְדְּעָן</a> fem.).</div>","alt":[]},"857":{"h":"אורדען","r":"A00857","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּרְדְּעָה\">foreg.</a></div>","alt":[]},"858":{"h":"אוּרְדַּעְנָה","r":"A00858","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אורדען\">foreg.</a>) <i>a disease of the tongue, rana</i> (<i>frog</i>). <span class=\"citation\">Y. Sabb. XIV, 14ᵈ</span> top.</div>","alt":[]},"859":{"h":"אוֹרָה I","r":"A00859","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h. = <a href=\"#\" data-headword=\"אוֹר\">אוֹר</a>) <i>light, sun</i>. <span class=\"citation\">Y. Pes. II, 29ᵃ</span> <span dir=\"rtl\">מאיר כא׳</span> clear as the sun. <span class=\"citation\">Zeb. 19ᵇ</span>, a. e. <span dir=\"rtl\">לא׳</span> <i>at daybreak</i>. <span class=\"citation\">Gen. R. s. 3</span> beg.; a. fr.—Chald. Adv. <a href=\"#\" data-headword=\"לִכְאוֹרָה\">לִכְאוֹרָה</a> <i>at first sight, apparently</i>. <span class=\"citation\">Keth. 54ᵃ</span> <span dir=\"rtl\">לכא׳ כשמואל רהיטא</span> apparently it would run (agree) with Samuel, <span dir=\"rtl\">כי מעיינת וכ׳</span></div>","alt":[]},"860":{"h":"אוֹרָה II","r":"A00860","html":"<p class=\"morphology\">f.</p><div class=\"sense\">; pl. <span dir=\"rtl\">אוֹרוֹת</span> (b. h. <i>herbs</i>, esp. <i>rocket</i>. <span class=\"citation\">Yoma 18ᵇ</span>, expl. <a href=\"#\" data-headword=\"גַּרְגִּיר\">גַּרְגִּיר</a> (etymol. <span dir=\"rtl\">שמאירות וכ׳</span>; cmp. Plin. XX, 13 quot. in Löw Aram. Pfl. p. 93). [<span class=\"citation\">Gen. R. s. 20</span> אוֹר <i>rue;</i> v. <a href=\"#\" data-headword=\"אוֹר II\"><span dir=\"rtl\">אוֹר</span> II</a>, 3.]</div>","alt":[]},"861":{"h":"אוֹרֶה","r":"A00861","html":"<div class=\"sense\"> part. of <a href=\"#\" data-headword=\"אָרָה\">אָרָה</a>, v. <a href=\"#\" data-headword=\"ארי\">ארי</a></div>","alt":[]},"862":{"h":"אורוורין","r":"A00862","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹרְיָיר\">אוֹרְיָיר</a></div>","alt":[]},"863":{"h":"אוּרְווֹת","r":"A00863","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹרְיָא ²\"><span dir=\"rtl\">אוּרְיָא</span> II</a> a. <a href=\"#\" data-headword=\"אֻרְיָה\"><a href=\"#\" data-headword=\"אֻרְיָה\">אֻרְוָה</a>.</a></div>","alt":[]},"864":{"h":"אוּרְוָותָא","r":"A00864","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹרְיָא ²\"><span dir=\"rtl\">אוּרְיָא</span> II</a> ch., a. <a href=\"#\" data-headword=\"אֵדֶר I\"><span dir=\"rtl\">אֵדֶר</span> I</a>.</div>","alt":[]},"865":{"h":"אוֹרוֹלוֹגִין","r":"A00865","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹרְלוֹגִין\">אוֹרְלוֹגִין</a></div>","alt":[]},"866":{"h":"*אורוסטי","r":"A00866","html":"<div class=\"sense\">, a corrupt., prob. <span dir=\"rtl\">רוֹסָאטוֹן</span>, m. (ῥοσᾶτον, rosatum) <i>vin-aux-roses, rose-wine</i>. <span class=\"citation\">Y. Shebi. VII, beg. 37ᵇ</span> <span dir=\"rtl\">א׳ שרי</span> (Mas. <span dir=\"rtl\">איריוסטו</span>) rose-wine is permitted in the Sabbath year.</div>","alt":[]},"867":{"h":"אורורין","r":"A00867","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹרְיָיר\">אוֹרְיָיר</a></div>","alt":[]},"868":{"h":"אוֹרֶז","r":"A00868","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. ὄρυζα, b. h. r. <a href=\"#\" data-headword=\"*ארז\">ארז</a> <i>to be hard</i>) <i>rice</i>. <span class=\"citation\">Ber. 37ᵃ</span>; a. fr.—<span class=\"citation\">Pes. 35ᵃ</span> (opinions as to its classification with ref. to Passover laws). Cmp. <a href=\"#\" data-headword=\"אֶרֶז\">אֶרֶז</a>.</div>","alt":[]},"869":{"h":"אוּרְזָא","r":"A00869","html":"<div class=\"sense\"><span class=\"citation\">Targ. Y. Num. XV, 19</span> <span dir=\"rtl\">אורי׳</span>.—Y. Sabb. III, 6ᵇ top <span dir=\"rtl\">אורז׳</span>. <span class=\"citation\">Pes. 50ᵇ</span> <span dir=\"rtl\">ארו׳</span> (Ms. M. <a href=\"#\" data-headword=\"אוֹרֶז\">אורז</a>; <span class=\"citation\">ib. 51ᵃ</span> top <a href=\"#\" data-headword=\"אַרְזָא\">ארזא</a>, corr. acc.). Ib. 114ᵇ <span dir=\"rtl\">ארוזא</span>.</div>","alt":["אֲרוּזָא","אוֹרִיזָא"]},"870":{"h":"אוּרְזִילָא","r":"A00870","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲזַל I\">אזל</a> with anorg. <a href=\"#\" data-headword=\"ר\">ר</a>; Syr. <span dir=\"rtl\">עוזילא</span>)</div><div class=\"sense\"><b>1)</b> <i>a slender young animal</i>, esp. <i>the young of the gazelle</i> or any similar animal (Reëm). <span class=\"citation\">Targ. Cant. II, 9</span> <span dir=\"rtl\">א׳ דאיילא</span> (h. text <a href=\"#\" data-headword=\"עֹפֶר\">עֹפֶר</a>). <span class=\"citation\">Zeb. 113ᵇ</span> <span dir=\"rtl\">א׳ דרימא בת יומא</span> (read <span dir=\"rtl\">בר</span>); <span class=\"citation\">B. Bath. 73ᵇ</span> (corr. as Zeb. l. c.; v. Rabb. D. S. a. l. note) a young antilope one day old. <span class=\"citation\">Num. R. s. 11</span>; <span class=\"citation\">Cant. R. to II, 9</span>; <span class=\"citation\">Pesik. R. s. 15</span> <span dir=\"rtl\">א׳ דאיילתא</span> (<span dir=\"rtl\">עוּרְזִילֵיהוֹן וכ׳</span> pl.) young deer.—Pl. <span dir=\"rtl\">אוּרְזִילִין</span>, <span dir=\"rtl\">אוֹרְ׳</span>; <span dir=\"rtl\">אַרְזִילֵי</span>. <span class=\"citation\">Targ. Cant. IV, 5</span>; <span class=\"citation\">VII, 4</span>. <span class=\"citation\">B. Bath. 74ᵇ</span> <span dir=\"rtl\">ארזילי דימא</span> (Ms. M. <span dir=\"rtl\">אוזילי</span>) sea-gazelles.—[</div><div class=\"sense\"><b>2)</b> <i>hammock</i>, v. <a href=\"#\" data-headword=\"אַרְזְלָא\">אַרְזְלָא</a>.]</div>","alt":["אוּרְזְלָא"]},"871":{"h":"אוּרְזָנַיָּיא","r":"A00871","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אוּרְזָא\">אורזא</a>) <i>a rice dish</i> (prepared with wine). [Oth. opin. <i>cedar-fruits; millet</i>.] Y. Maas. Sh. II, beg. 53ᵇ. <span class=\"citation\">Y. Yoma VIII, 45ᵃ</span> top; Y. Shebu. III, 34ᵇ bot. <span dir=\"rtl\">אורזרייה</span> (corr. acc.).</div>","alt":["אוּרְזָנַיָּיה"]},"872":{"h":"אוֹרֵחַ","r":"A00872","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>wayfarer</i>, esp. <i>guest</i>. <span class=\"citation\">Ber. 58ᵃ</span>; a. fr.—Euphem. <i>menstruation</i>. <span class=\"citation\">Nidd. 16ᵃ</span> (cmp. <span class=\"citation\">Gen. XVIII, 11</span> <i>oraḥ</i>). <span class=\"citation\">Lev. R. s. 4</span>.—Pl. <span dir=\"rtl\">אוֹרְחִים</span>, <span dir=\"rtl\">אוֹרְחִין</span>.—<span dir=\"rtl\">הכנסת א׳</span> the invitation of guests, <i>hospitality</i>. <span class=\"citation\">Sabb. 127ᵃ</span>; a. fr.</div>","alt":["אוֹרַח"]},"873":{"h":"אוֹרַח","r":"A00873","html":"<div class=\"sense\"> c. = h. <a href=\"#\" data-headword=\"אוֹרַח\">אֹרַח</a>, <i>road, path, way</i>. <span class=\"citation\">Targ. Jud. V, 6</span>; a. fr.—<span dir=\"rtl\">א׳ ארעא</span> (h. <span dir=\"rtl\">דרך ארץ</span>) <i>custom</i>. <span class=\"citation\">Ab. Zar. 2ᵇ</span>; a. fr.—<span dir=\"rtl\">א׳ דמילתא</span> a usual incident. <span class=\"citation\">Git. 29ᵃ</span>; a. fr.—<span dir=\"rtl\">אגב אורחך</span>, <span dir=\"rtl\">אגב אורחיה</span> &amp;c. on thy road (his road &amp;c.), i.e. <i>by the way, occasionally, incidentally</i>. <span class=\"citation\">Ber. 2ᵃ</span>. <span class=\"citation\">Snh. 95ᵇ</span>; a. fr.—<span class=\"citation\">Gen. R. s. 100</span> <span dir=\"rtl\">על א׳</span> for the journey (death). <span class=\"citation\">Targ. Y. II, Gen. XXXV, 9</span> <span dir=\"rtl\">ארחא דעלמא</span> the way of the world (death).—<i>Pl.</i> <a href=\"#\" data-headword=\"אוֹרַח\">אוֹרְחָן</a>, <span dir=\"rtl\">אָרְחָן</span>; <span dir=\"rtl\">אָרְחָתָא</span>. Targ. Jud. l. c. <span class=\"citation\">Targ. Y. II, Gen. XLIX, 17</span>; a. e.—<span class=\"citation\">Snh. 109ᵃ</span> <span dir=\"rtl\">יהבית אוֹרְחַיָּה לגנבַיָּה</span> (missing in Ms. M., v. Rabb. D. S. a. l. note) thou hast shown the thieves the ways (of stealing).—[אוֹרְחָא <i>guest</i>, v. <a href=\"#\" data-headword=\"אָרְחָא\">אָרְחָא</a>.]</div>","alt":["אוֹרְחָא","אָרְחָא"]},"874":{"h":"אוּרִי","r":"A00874","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (b. h.) <i>Uri</i>, an Amora. <span class=\"citation\">Y. Ber. II, beg. 4ᵃ</span> ר׳ חונה ר׳ א׳ R. Ḥuna in the name of R. U.</div>","alt":[]},"875":{"h":"אוֹרִי","r":"A00875","html":"<div class=\"sense\"> Af. of <a href=\"#\" data-headword=\"ירי\">ירי</a>.</div>","alt":[]},"876":{"h":"אוֹרְיָא","r":"A00876","html":"<div class=\"sense\"><i>teaching</i>, v. <a href=\"#\" data-headword=\"אוֹרָיָיא\">אוֹרָיָיא</a>.</div>","alt":[]},"877":{"h":"אוּרְיָא","r":"A00877","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אוֹר\">אוֹר</a> a. <a href=\"#\" data-headword=\"אוּרְתָּא\"><a href=\"#\" data-headword=\"אוּרְתָּא\">אוּרְתָּא</a>)</a><i>evening horizon, Sun-set, West</i>, v. <a href=\"#\" data-headword=\"מַעֲרָבָא\">מערבא</a>. <span class=\"citation\">B. Bath. 25ᵃ</span> <span dir=\"rtl\">אוריה מאי</span> ed. (Ar. <span dir=\"rtl\">אוריא</span>) why is it called <i>Urya</i>? <span dir=\"rtl\">אויר יה</span> (Var. <a href=\"#\" data-headword=\"אוֹר\">אור</a>) divine air (divine light = Palestine). <span class=\"citation\">Kidd. 12ᵇ</span> איכא סהדי באוריא הא Ar. (ed. <span dir=\"rtl\">אידית</span>, emend. in Tossaf. <span dir=\"rtl\">אורית</span>), [read with <span dir=\"rtl\">ב&quot;ח</span>: <span dir=\"rtl\">הא אמרי איכא וכ׳</span>] but people say, there are witnesses in the West &amp;c. Cmp. <a href=\"#\" data-headword=\"אִסְתָּן\">אֶסְתָּן</a>.</div>","alt":["אוּרְיָה I","אוּרִית"]},"878":{"h":"אוּרְיָא ²","r":"A00878","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>pile of plucked plants, stalk, shed containing feed</i> (dist. fr. <a href=\"#\" data-headword=\"אוֹצָר\">אוֹצָר</a> granary).—Pl. <span dir=\"rtl\">אוּרְיָאוֹת</span>, <span dir=\"rtl\"><a href=\"#\" data-headword=\"אוּרְיָיא\">אוּרְיָי׳</a> (אוּרְיוֹת</span>). <span class=\"citation\">Tosef. Maasr. II, 20</span> ed. Zuck. (Var. <span dir=\"rtl\">אוריות</span>); ib. <span class=\"citation\">Erub. V</span>I (V), 4; <span class=\"citation\">Erub. 55ᵇ</span> Ar. (ed. <span dir=\"rtl\">אוריות</span>, <a href=\"#\" data-headword=\"אוּרְווֹת\">אורוות</a>, v. Rabb. D. S. a. l. note). [In bibl. h. <a href=\"#\" data-headword=\"אֻרְיָה\">אֻרְוָה</a> <i>crib, stable</i> q. v.]</div>","alt":["אוּרְיָה II","אוּרְיָיא"]},"879":{"h":"אוּרְיָא ³","r":"A00879","html":"<div class=\"sense\">(= b. h. <a href=\"#\" data-headword=\"אֻרְיָה\">אֻרְוָה</a>) <i>crib</i>;<i> stable</i>. <span class=\"citation\">Targ. Is. I, 3</span> (h. text <a href=\"#\" data-headword=\"אֵבוּס\">אֵבוּס</a> q. v.).—<span class=\"citation\">Snh. 98ᵇ</span> <span dir=\"rtl\">סוסיא באוּרְיֵיה …</span> a horse is placed at his (the ox’s) crib., i.e. Israel is displaced and other nations feed on his soil.—<span class=\"citation\">M. Kat. 10ᵇ</span> <span dir=\"rtl\">למבני א׳</span> to build a stable (during the festive week). [Targ. II Esth. VI, 10; 11 <span dir=\"rtl\">אוּרַיָּא</span>, read <a href=\"#\" data-headword=\"אוּרְיָא\">אוּרְיָא</a> <i>stable</i>.]—Pl. <a href=\"#\" data-headword=\"אוֹרְיָין\">אוּרְיָין</a>, <a href=\"#\" data-headword=\"אוּרְוָותָא\">אוּרְוָותָא</a>, <span dir=\"rtl\">(<a href=\"#\" data-headword=\"אוּרְיָירָא\">אוּרְיָיתָא</a>) <a href=\"#\" data-headword=\"אוּרְוָותָא\">אֻרְוָותָא</a></span>. <span class=\"citation\">Targ. II Chr. IX, 25</span>; <span class=\"citation\">I Kings V, 6</span>. Targ. II Esth. l. c. (<a href=\"#\" data-headword=\"אוּרְיָירָא\">אוּרְיָיתָא</a> prob. sing.); a. e.</div>","alt":["אוּרְוָוא"]},"880":{"h":"אוֹרְיָא ²","r":"A00880","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (horreum, pl. horrea, ὡρεῖον, ὥριον; v. Sm. Ant. s. v.) <i>store-house, store</i> (of all kinds). Tanḥ. <span class=\"citation\">B’resh. 7</span> <span dir=\"rtl\">וכל א׳ שלי בתוכה</span> all my stores are in that ship.—Pl. <span dir=\"rtl\">אוּרְיָאַיָּא</span> (ch. form). <span class=\"citation\">Targ. I Chr. XXI, 13</span>.—<span dir=\"rtl\">אוּרְיָיאוֹת</span> (h. form). <span class=\"citation\">Targ. II Chr. XXXII, 28</span> (h. text <span dir=\"rtl\">מסכנות</span>). V. <a href=\"#\" data-headword=\"אוֹרְיָיר\">אוֹרְיָיר</a>, <a href=\"#\" data-headword=\"אֲהוּרְיָיר\">אֲהוֹרְיָיר</a>.</div>","alt":["אוּרְיָא III"]},"881":{"h":"אוּרִיאֵל","r":"A00881","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Uriël</i>, name of an angel. <span class=\"citation\">Targ. Y. Deut. XXXIV, 6</span>.—<span class=\"citation\">Num. R. s. 2</span>.</div>","alt":[]},"882":{"h":"אוֹרְיָאן","r":"A00882","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹרְיָין II\"><span dir=\"rtl\">אוֹרְיָין</span> I</a></div>","alt":[]},"883":{"h":"אוּרְיָה  I, II","r":"A00883","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּרְיָא\">אוּרְיָא</a></div>","alt":[]},"884":{"h":"אוֹרְיָה","r":"A00884","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹרָיָיא\">אוֹרָיָיא</a></div>","alt":[]},"885":{"h":"אוֹרְיוֹן","r":"A00885","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹרְיָין II\"><span dir=\"rtl\">אוֹרְיָין</span> II</a></div>","alt":[]},"886":{"h":"אוֹרִיזָא","r":"A00886","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּרְזָא\">אוּרְזָא</a></div>","alt":[]},"887":{"h":"אוּרְיָיא","r":"A00887","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹרְיָא ²\"><span dir=\"rtl\">אוּרְיָא</span> II</a> h. a. ch.</div>","alt":[]},"888":{"h":"אוֹרָיָיא","r":"A00888","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"ירי\">ירי</a>, Af. <a href=\"#\" data-headword=\"אוֹרִי\">אוֹרִי</a> = h. <a href=\"#\" data-headword=\"תּוֹרָה\">תֹּורָה</a>) </div><div class=\"sense\"><b>1)</b> <i>instruction, the Law, Bible-verse</i>. <span class=\"citation\">Targ. Lev. VI, 7</span>; a. fr.—<span dir=\"rtl\">מילה דא׳</span> (= <span dir=\"rtl\">דברי תורה</span>) <i>religious discourse, lesson, remarks</i> &amp;c. <span class=\"citation\">Y. B. Bath. VIII, 16ᵃ</span> <span dir=\"rtl\">אורייא</span>; Y. Taan. III, 66ᶜ bot. <span dir=\"rtl\">ייתא …</span>—<span class=\"citation\">Y. Snh. I, 18ᶜ</span> <span dir=\"rtl\">אפלגינון במילי דא׳</span> he entertained them with religious discussions. <span class=\"citation\">Y. Hor. III, beg. 47ᵃ</span> <span dir=\"rtl\">עתיד לך מילה דא׳</span> be prepared for a religious discourse. <span class=\"citation\">Y. Shek. III, 47ᶜ</span> top <span dir=\"rtl\">מאי א׳ חדתא שמעת</span> what novel interpretation hast thou heard? <span class=\"citation\">Y. Yeb. II, 4ᵃ</span> top <span dir=\"rtl\">מן הדא אורייה</span> from what verse?—<span class=\"citation\">Taan. 4ᵃ</span> <span dir=\"rtl\">ליה א׳ … מרתח׳</span> it is the zeal of study that makes him warm (excited). <span class=\"citation\">Kidd. 71ᵇ</span> <span dir=\"rtl\">אורייתין כשר׳</span> my instruction is acceptable, but my daughters are not desired. <span class=\"citation\">Sabb. 116ᵇ</span> <span dir=\"rtl\">א׳ דמשה</span> the Mosaic dispensation (opp. <span dir=\"rtl\">א׳ אחריתי</span> the new dispensation, v. <a href=\"#\" data-headword=\"אָוֶון\">אָוֶון</a>).—<span dir=\"rtl\">דְּאוֹרַיְיתָא</span> (sub. <a href=\"#\" data-headword=\"הֲלָכָה\">הלכה</a> = h. <span dir=\"rtl\">התורה מן</span>) <i>an enactment founded on the Bible text</i>, opp. <span dir=\"rtl\">דרבנן</span>. <span class=\"citation\">Succ. 44ᵃ</span> לולב דא׳ Lulab, the law concerning which is Biblical &amp;c.; a. fr.—<span dir=\"rtl\">מִדְּאוֹרַיְיתָא</span>, adv. <i>biblically, according to the Biblical law</i>, opp. <span dir=\"rtl\">מדרבנן</span>. <span class=\"citation\">Pes. 10ᵃ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>the Torah, the scroll containing the Pentateuch</i>, used at divine service. <span class=\"citation\">Y. Yoma VII, 44ᵇ</span> top <span dir=\"rtl\">כד היא חדא אוריא</span> when you have no more than one scroll. <span class=\"citation\">Y. Meg. IV, 75ᵇ</span> bot.; <span class=\"citation\">Y. Sot. VII, end, 22ᵃ</span> <span dir=\"rtl\">כד חזרא אורייה</span> (corr. as Y. Yoma l. c.). Ib. <span dir=\"rtl\">תא וכ׳</span>—תמן מייבלין א <i>there</i> (in Babylon) the Torah is carried to the Resh Galutha.—בר אוריא <i>a scholar, man of learning</i>. <span class=\"citation\">Yoma 78ᵃ</span>. <span class=\"citation\">Ḥag. 14ᵃ</span> <a href=\"#\" data-headword=\"אֲרִיחַ\">אריא</a> (corr. acc.); v. <a href=\"#\" data-headword=\"אוֹרְיָין\">next w.</a></div>","alt":["(אוֹרַיְיתָא)","(אוֹרָיָיתָא","אוֹרְיָא","אוֹרַיְתָא","אוֹרְיָה)"]},"889":{"h":"אוֹרְיָין","r":"A00889","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"אוֹרָיָיא\">same</a>; </div><div class=\"sense\"><b>1)</b>  the Law. <span class=\"citation\">Sabb. 31ᵇ</span>. <span class=\"citation\">Ib. 88ᵃ</span> <span dir=\"rtl\">א׳ תליתאי</span> the threefold law (Pentat., Proph., Hagiogr.).</div><div class=\"sense\"><b>—2)</b> <i>scholarship, authority to teach and judge</i>. <span class=\"citation\">Ber. 12ᵃ</span> <span dir=\"rtl\">בר אוריאן</span> ed. (Ms. M. <span dir=\"rtl\">אוריא</span>); v. <a href=\"#\" data-headword=\"אוֹרָיָיא\">foreg.</a> w.—[</div><div class=\"sense\"><b>3)</b>  *<i>authority, office</i>. <span class=\"citation\">Gen. R. s. 50</span> <span dir=\"rtl\">בית אוריין</span> ed. (Ar. <a href=\"#\" data-headword=\"מִיתוֹרְיִין\">מיתורין</a>, <span class=\"citation\">Lev. R. s. 26</span> <a href=\"#\" data-headword=\"מתורין\">מתורין</a>) <i>place of office</i>. V. <a href=\"#\" data-headword=\"מִיתוֹרְיִין\">מִיתוֹרְיִין</a>.]</div>","alt":["אוֹרְיָאן"]},"890":{"h":"אוֹרְיָין II","r":"A00890","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אוֹרְיָין\">foreg.</a>) pr. n. m. <i>Oryan, Oryon</i>. Esth. R. beg. <span dir=\"rtl\">אבא א׳</span>, Abba O. (cmp. <a href=\"#\" data-headword=\"אַבָּא I\">אַבָּא</a>). <span class=\"citation\">Y. Sabb. X, 12ᵈ</span> top <span dir=\"rtl\">יצחק בר אוריון</span>.</div>","alt":["אוֹרְיוֹן"]},"891":{"h":"*אוּרְיָינִי","r":"A00891","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אוֹרְיָין II\">foreg. ws.</a>) <i>officer’s or teacher’s chair</i>. <span class=\"citation\">M. Kat. 21ᵇ</span>; <span class=\"citation\">27ᵃ</span> א׳ גדולה Ms. M. (v. Rabb. D. S. a. l.; ed. <span dir=\"rtl\">אוד׳</span>) a high (teacher’s) chair. V. <a href=\"#\" data-headword=\"אוּדְיָינִי\">אוּדְיָינִי</a>.</div>","alt":[]},"892":{"h":"אוֹרְיָיר","r":"A00892","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (horrearius, ὡρειάριος, v. <a href=\"#\" data-headword=\"אוֹרְיָא\">אוֹרְיָא</a>, <a href=\"#\" data-headword=\"אֲהוּרְיָיר\"><a href=\"#\" data-headword=\"אֲהוּרְיָיר\">אֲהוֹרְיָיר</a>)</a><i>store-keeper</i>, used in the sense of <a href=\"#\" data-headword=\"אוֹלְיָאר\">אוֹלְיָיר</a>. Y. B. Bath. IV, beg. 14ᶜ <span dir=\"rtl\">מקום הא׳</span> (<span class=\"citation\">Tosef. ibid. III, 3</span> <span dir=\"rtl\">בית האוליירין</span>) the clothes-keeper’s room.—Pl. <span dir=\"rtl\">אוֹרְיָירִין</span>. Y. l. c. <a href=\"#\" data-headword=\"אורורין\">אורורין</a>, <span dir=\"rtl\">אורוו׳</span> (corr. acc.) <span class=\"citation\">Toh. VIII, 7</span> <span dir=\"rtl\">אודיארין</span> (corr. acc.; <span class=\"citation\">Tosef. ib. VII, 8</span> <span dir=\"rtl\">אוליארין</span>).</div>","alt":[]},"893":{"h":"אוּרְיָירָא","r":"A00893","html":"<div class=\"sense\">—Pl. <span dir=\"rtl\">אוּרְיָירַיָּא</span>. <span class=\"citation\">Targ. I Chr. XXVII, 25</span>; <span class=\"citation\">XXVI, 22</span> (ed. Rahm. <span dir=\"rtl\">אורייד׳</span>, corr. acc.; Var. <span dir=\"rtl\">אוּרְיָרַיָּא</span>, h. text <span dir=\"rtl\">על אוצרות</span>).</div>","alt":[]},"894":{"h":"אוֹרַיְיתָא","r":"A00894","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹרָיָיא\">אוֹרָיָיא</a></div>","alt":[]},"895":{"h":"אוּרִית","r":"A00895","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּרְיָא ²\"><span dir=\"rtl\">אוּרְיָא</span> I</a></div>","alt":[]},"896":{"h":"אוֹרַיְתָא","r":"A00896","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹרָיָיא\">אוֹרָיָיא</a></div>","alt":[]},"897":{"h":"אוריכות","r":"A00897","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אַרְכַת\">אַרְכַּת</a></div>","alt":[]},"898":{"h":"אוֹרִיכוּתָא","r":"A00898","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוֹרָכוּתָא\">אוֹרָכוּתָא</a></div>","alt":[]},"899":{"h":"אוֹרֶךְ","r":"A00899","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>length, lengthiness</i>. Midr. Sam. ch. XIII, <span dir=\"rtl\">וכל הא׳ הזה למה</span> and why all this lengthiness (of speech).</div>","alt":[]},"900":{"h":"אוּרְכָּא","r":"A00900","html":"<div class=\"sense\">, <i>length</i>. <span class=\"citation\">Targ. O. Gen. VI, 15</span> [Constr. <a href=\"#\" data-headword=\"אוֹרֶךְ\">אוֹרֶךְ</a> <span class=\"citation\">Targ. Y. Ex. XXVI, 13</span>; Targ. O. ib., corr. acc.]—<span class=\"citation\">Sabb. 140ᵇ</span> <span dir=\"rtl\">טונא כי טונא וא׳ וכ׳</span> a load (of twigs) is a load, and the length goes in the bargain (the price is the same).</div>","alt":[]},"901":{"h":"אוֹרָכוּתָא","r":"A00901","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"אֲרִיכָה\">אֲרִיכוּת</a>) </div><div class=\"sense\"><b>1)</b> <i>length</i> (of life). (of life). <span class=\"citation\">Targ. Ps. XCI, 16</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>waiting, hope</i>. Ibid. XXXIX, 8; a. e.</div><div class=\"sense\"><b>—3)</b> <i>tarrying</i>. <span class=\"citation\">Targ. Y. Deut. II, 31</span>.</div>","alt":["אוֹרִיכוּתָא"]},"902":{"h":"*אוּרְכָנִיס","r":"A00902","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Urkhanes</i>. <span class=\"citation\">Y. Yeb. VIII, 8ᵈ</span> bot. (allusion to a case concerning the child of a certain U., otherwise unknown).</div>","alt":[]},"903":{"h":"אורכתא","r":"A00903","html":"<div class=\"sense\"> <span class=\"citation\">B. Kam. 70ᵃ</span>; <span class=\"citation\">Shebu. 33ᵇ</span>, v. <a href=\"#\" data-headword=\"אַדְרַכְתָּא\">אַדְרַכְתָּא</a> 2).</div>","alt":[]},"904":{"h":"אוֹרְלוֹגִין","r":"A00904","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ὡρολόγιον) <i>horologe, time-piece</i>. <span class=\"citation\">Y. R. Hash. I, 57ᵇ</span> top. <span class=\"citation\">Pesik. R. s. 15</span>; a. e.</div>","alt":["אוֹרוֹלוֹגִין"]},"905":{"h":"אוֹרֶן","r":"A00905","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֹרֶן\">אֹרֶן</a></div>","alt":[]},"906":{"h":"אוֹרָן","r":"A00906","html":"<div class=\"sense\"> ch. = h. <a href=\"#\" data-headword=\"אֹרֶן\">אֹרֶן</a>. <span class=\"citation\">Targ. Is. XL, 20</span>; <span class=\"citation\">XLIV, 14</span>.</div>","alt":["אוּרְנָא"]},"907":{"h":"*אַוְרַנֹּוס","r":"A00907","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"אַבְרַנְסֵי\">אַוְרַנְסֵי</a>, <a href=\"#\" data-headword=\"אֲבָר ²\">אַבְרַ׳</a> (ῥάμνος, rhamnus) <i>a kind of prickly shrubs</i>, used for medical purposes and carried in lengthy bundles (v. D. C. Gr. s. v., a. Sm. Ant. s. v.). <span class=\"citation\">Sabb. 91ᵇ</span> <a href=\"#\" data-headword=\"*אימיקנטרון\">או׳</a> ed. (Ms. M. <a href=\"#\" data-headword=\"אֵיבָרָא\">אב׳</a>; Ar. <a href=\"#\" data-headword=\"אֲרַנְסֵי\">ארנסי</a>). [As to <span dir=\"rtl\">ור</span>, <span dir=\"rtl\">בר</span> for aspirate r, v. Lidd. a. Scott, Gr. Lex, 7<sup>ᵗʰ</sup> ed. s. lit. P.]</div>","alt":["אַבְרַנֹּוס"]},"908":{"h":"אורסיקין","r":"A00908","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אַוְורַקְסִין\">אוורקסין</a></div>","alt":["אורסקין"]},"909":{"h":"אוֹרָעָא","r":"A00909","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲרַע I\">ארע</a>) <i>meeting</i>. <span dir=\"rtl\">לא׳</span> with suff. of pers. pron., <i>to meet—, against</i>—. <span class=\"citation\">Targ. Prov. VII, 10</span> (ed. Vien. <span dir=\"rtl\">לְעוּרְ׳</span>); <span class=\"citation\">15</span>. <span class=\"citation\">Targ. Ps. XXXV, 3</span> <span dir=\"rtl\">לְאוֹרְעוּת</span>.</div>","alt":["אוֹרָעוּתָא"]},"910":{"h":"אוּרְעֵי","r":"A00910","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּרְעִיתָא\">next w.</a></div>","alt":[]},"911":{"h":"אוּרְעִיתָא","r":"A00911","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲרַע I\">ארע</a>; corresp. to h. <a href=\"#\" data-headword=\"צִרְעָה\">צִרְעָה</a>) <i>wasp, hornet</i> (collect.). <span class=\"citation\">Targ. Y. Ex. XXIII, 28</span>; a. e.—Pl. <span dir=\"rtl\">אוּרְעַיָּיתָא</span>. <span class=\"citation\">Targ. Y. Deut. I, 44</span>; a. e.—<a href=\"#\" data-headword=\"אוּרְעֵי\">אוּרְעֵי</a>, <span dir=\"rtl\">אוּרְעַיָּה</span>. <span class=\"citation\">Targ. Y. Lev. XI, 20</span> ed. pr. (corr. vowel signs; later ed. <a href=\"#\" data-headword=\"*(אוזפיה)\">אוזפיה</a>). Y. Sabb. I, 3ᵇ bot. <span dir=\"rtl\">תולעתא דסוסיא וכ׳</span> the mite in the horse’s carcass turns into hornets. [Cmp. same ideas among the Greek, Sachs Beitr. II, 92; Nican Ther. 741.]</div>","alt":[]},"912":{"h":"אורשינא","r":"A00912","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַוְורַשְׁנָא\">אַוְורַשְׁנָא</a></div>","alt":[]},"913":{"h":"אוּרְתָּא","r":"A00913","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אוֹר\">אוֹר</a></div><div class=\"sense\"><b>2)</b> <i>evening, night</i>. <span class=\"citation\">Pes. 2ᵃ</span>; <span class=\"citation\">2ᵇ</span> <span dir=\"rtl\">אור א׳</span> the <i>or</i> of the Mishn. means <i>evening</i>. <span class=\"citation\">Ber. 3ᵇ</span>; a. fr.—<span class=\"citation\">Y. Sot. I, 17ᵇ</span> top, v. <a href=\"#\" data-headword=\"בַּר II\">בְּרַת</a>.</div>","alt":[]},"914":{"h":"אֲוַשׁ","r":"A00914","html":"<div class=\"sense\">, <i>Pa</i>. <span dir=\"rtl\">אַוֵּושׁ</span>, (√<span dir=\"rtl\">אוו</span>, v. <a href=\"#\" data-headword=\"אָוָוז\">אָוָוז</a>; cmp. <a href=\"#\" data-headword=\"אוֹף I\">אוף</a>, <a href=\"#\" data-headword=\"*אָנַף\">אנף</a>, <a href=\"#\" data-headword=\"אָפַף\">אפף</a>, <span dir=\"rtl\">אופי</span>, <a href=\"#\" data-headword=\"אוסי\">אוסי</a>, <span dir=\"rtl\">אבב</span>) </div><div class=\"sense\"><b>1)</b> <i>to blow vehemently, make noise, shout</i>. <span class=\"citation\">B. Mets. 86ᵃ</span> <span dir=\"rtl\">נשב זיקא וא׳ וכ׳</span> the wind blew and howled between the branches. <span class=\"citation\">Ber. 50ᵃ</span> <span dir=\"rtl\">וכ׳ איידי דאוושו</span> because all shouted, the prayer was not heard. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אוושו כ&quot;ע ברכו</span> they all shouted <i>‘bar’khu’</i>.—<span class=\"citation\">Erub. 97ᵇ</span> <span dir=\"rtl\">אוושא מילתא</span> the thing grows loud, becomes known. <span class=\"citation\">Ḥull. 46ᵇ</span> <span dir=\"rtl\">ריאה דא׳</span> lungs which give out a sound when blown up (indicating perforation). <span class=\"citation\">Ber. 58ᵃ</span> <span dir=\"rtl\">כי קא אוושא</span> (Ms. M. <span dir=\"rtl\">שמעו קל א׳</span>) when shouting was heard.</div><div class=\"sense\"><b>—2)</b> <i>to swell, to be large, fulsome, lengthy</i> (in wording). <span class=\"citation\">R. Hash. 35ᵃ</span> <span dir=\"rtl\">משום דאוושי ברכות</span> (Ms. M. <span dir=\"rtl\">קראי …</span>) because the benedictions are numerous and lengthy. <span class=\"citation\">Ned. 2ᵇ</span> <span dir=\"rtl\">הלין דא׳ וכ׳ משום</span> because the last named propositions are lengthy, he explained first what he had commenced with.</div>","alt":["אֲוַושׁ"]},"915":{"h":"אוּשׁ I","r":"A00915","html":"<div class=\"sense\"> (v. foreg; cmp. <a href=\"#\" data-headword=\"יֵשׁ\">יֵשׁ</a>, <a href=\"#\" data-headword=\"אִישׁ\">אִישׁ</a>) <i>to be strong, exist.</i> <i> Nithpol</i>. <span dir=\"rtl\">נִתְאוֹשֵׁשׁ</span> <i>to be confirmed</i>. <span class=\"citation\">Gen. R. s. 67</span>; s. 78 <span dir=\"rtl\">והיכן נ׳ בידן</span> when were the blessings made sure &amp;c. Cmp. <a href=\"#\" data-headword=\"אָשַׁשׁ\">אָשַׁשׁ</a>.</div>","alt":[]},"916":{"h":"אוּשׁ II","r":"A00916","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (אשש 2, cmp. <a href=\"#\" data-headword=\"אוּשׁ I\">foreg.</a>) pl. <span dir=\"rtl\">אוּשִּׁין</span> <i>foundations</i>. <span class=\"citation\">B. Kam. 50ᵃ</span> <span dir=\"rtl\">חופר לא׳</span> digs excavations for supporting walls.</div>","alt":[]},"917":{"h":"אוּשָּׁא","r":"A00917","html":"<div class=\"sense\">, also <i>fortification</i>. <span class=\"citation\">Targ. Cant. VIII, 9</span>.—Pl. <span dir=\"rtl\">אוּשַּׁיָּא</span>. [<span class=\"citation\">Ezra IV, 12</span>; a. e.]. <span class=\"citation\">Targ. I Kings VII, 7</span>; <span class=\"citation\">VI, 16</span>; a. e. [<span class=\"citation\">Targ. Mic. I, 6</span> ed. Ven. <a href=\"#\" data-headword=\"אַנְשָׁהָא\">אַוְשָׁהָא</a> her foundations. <span class=\"citation\">Targ. Y. Ex. IX, 18</span> <a href=\"#\" data-headword=\"אַנְשָׁהָא\">אנשהא</a> (corr. <span dir=\"rtl\">אַוְ׳</span>)]. [Not to be conf. with <span dir=\"rtl\">אשיתא</span>].</div>","alt":["אֻשָּׁא","(אַוְשָׁא)"]},"918":{"h":"אוּשָׁא","r":"A00918","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Uhsa</i>, in Galilee; freq. the scene of rabbin. synods and enactments during and after the Hadrianic persecutions. <span class=\"citation\">Keth. 50ᵃ</span> <span dir=\"rtl\">מרה דשמעתא דא׳</span> master of the traditions of U. (in whose name they are quoted). [<span class=\"citation\">Ib.</span> <span dir=\"rtl\">קאי באוכלוסא דא׳</span>, read <span dir=\"rtl\">בהילכתא</span> engaged in teaching the laws passed at U.] <span class=\"citation\">R. Hash. 31ᵇ</span>; a. fr.</div>","alt":[]},"919":{"h":"אוּשְׁוָותָא","r":"A00919","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַשְׁיְתָא\">אֲשִׁיתָא</a></div>","alt":[]},"920":{"h":"אוֹשָׁטוּתָא","r":"A00920","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">ישט</span>) <i>stretching forth, obtaining</i>.—אוֹשָׁטוּת ידא <i>acquisition, business</i>. <span class=\"citation\">Targ. Deut. XII, 7</span>; a. e.</div>","alt":[]},"921":{"h":"אוּשְׁיָיתָא","r":"A00921","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַשְׁיְתָא\">אֲשִׁיתָא</a></div>","alt":[]},"922":{"h":"*אוּשְׁכִּי","r":"A00922","html":"<div class=\"sense\"> a word in a charm formula, supposed to mean <i>day</i>. <span class=\"citation\">Sabb. 67ᵇ</span> או׳ Ar. (ed. <span dir=\"rtl\">אש׳</span>, Ms. M. <span dir=\"rtl\">אושקי</span>). Cmp. <span class=\"citation\">Tosef. Sabb. VII</span> (<span class=\"citation\">VIII), 1</span>.</div>","alt":["אַשְׁכִּי"]},"923":{"h":"אוּשְׁכָּף","r":"A00923","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַשְׁכָּף\">אַשְׁכָּף</a></div>","alt":[]},"924":{"h":"אוּשְׁכָּפָא","r":"A00924","html":"<p class=\"morphology\">m.</p><div class=\"sense\">(= h. <a href=\"#\" data-headword=\"שַׁכָּף\">שַׁכָּף</a>; <a href=\"#\" data-headword=\"שַׁכָּף\">שכף</a>, √<span dir=\"rtl\">כף</span>, cmp. <a href=\"#\" data-headword=\"אוּכָּף\">אוּכָּף</a>) <i>worker in leather, saddler, shoemaker</i>. <span class=\"citation\">Git. 68ᵇ</span>.—Pl. <a href=\"#\" data-headword=\"אוּשְׁכָּף\">אוּשְׁכָּפֵי</a>. <span class=\"citation\">Sabb. 112ᵃ</span> the travellers’ sandals <span dir=\"rtl\">דקטרי א׳</span> which the shoemakers knot (tightly). <span class=\"citation\">Ib. 104ᵇ</span> <span dir=\"rtl\">חרתא דא׳</span> the blacking used by shoemakers. <span class=\"citation\">Ib. 123ᵇ</span> <span dir=\"rtl\">חרבא דא׳</span> the leather dressers’ knife. <span class=\"citation\">Pes. 42ᵇ</span> <span dir=\"rtl\">פרורא דא׳</span> the shoemakers’ paste. <span class=\"citation\">Ib. 113ᵇ</span></div>","alt":[]},"925":{"h":"אוּשְׁלָא","r":"A00925","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"חוּשְׁלָא\">חוּשְׁלָא</a>.</div>","alt":[]},"926":{"h":"אוּשְׁלַיָּא","r":"A00926","html":"<div class=\"sense\"> <span class=\"citation\">Targ. I Chr. I, 20</span>, v. <a href=\"#\" data-headword=\"אַשְׁלָא\">אַשְׁלָא</a></div>","alt":[]},"927":{"h":"אוֹשַׁעְיָא","r":"A00927","html":"<div class=\"sense\"> (in Y. <a href=\"#\" data-headword=\"הוֹשַׁעְיָא\">הוֹשַׁעְיָא</a> q. v.) pr. n. m. <i>Oshāya</i>, </div><div class=\"sense\"><b>1)</b>  freq. surnamed <a href=\"#\" data-headword=\"רַב\">רַבָּא</a> (the elder), an Amora of the first generation, redactor of Tosefta. <span class=\"citation\">Yeb. 18ᵇ</span>; a. fr.</div>","alt":[]},"928":{"h":"אוּשְׁפְּזִיכָא","r":"A00928","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּשְׁפִּיזָא\">אוּשְׁפִּיזָא</a></div>","alt":[]},"929":{"h":"אוּשְׁפְּזִיכְנָא","r":"A00929","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אוּשְׁפִּיזְכָנָא\">אוּשְׁפִּיזְכָנָא</a></div>","alt":[]},"930":{"h":"אושפזתי","r":"A00930","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אוּשְׁפַּרְתִּי\">אושפרתי</a></div>","alt":[]},"931":{"h":"אוּשְׁפֵּיז","r":"A00931","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נְשַׁף I\">נשף</a>, with <a href=\"#\" data-headword=\"ז\">ז</a> format; cmp. <a href=\"#\" data-headword=\"אַטְלֵיז\">אטליז</a>) <i>night’s lodging, inn.</i> <i>—</i> Pl. <span dir=\"rtl\">אוּשְׁפִּיזִין</span>. <span dir=\"rtl\">בעלי א׳</span> <i>innkeepers</i>. <span class=\"citation\">Tosef. Maas. Sh. I, 13</span>; <span class=\"citation\">Meg. 26ᵃ</span>. [Mand. <span dir=\"rtl\">שפינזא</span>, v. Nœld. Mand. Gr. p. 51.]</div>","alt":[]},"932":{"h":"אוּשְׁפִּיזָא","r":"A00932","html":"<div class=\"sense\"><span class=\"citation\">Git. 44ᵇ</span> <span dir=\"rtl\">אית ליה א׳ וכ׳</span> he has a lodging place in Palestine, (is an occasional resident), opp. <a href=\"#\" data-headword=\"בַּיְתָא\">ביתא</a> permanent home. <span class=\"citation\">Meg. 26ᵃ</span>; <span class=\"citation\">Yoma 12ᵃ</span> it is customary to leave empty jars and hides of slaughtered animals <span dir=\"rtl\">(<a href=\"#\" data-headword=\"ל\">ל</a>) <span dir=\"rtl\">באושפיזֵיה</span></span> in one’s inn. <span class=\"citation\">Zeb. 61ᵇ</span> <span dir=\"rtl\">א׳ הוה נקט וכ׳</span> (Ms. M. <span dir=\"rtl\">אוּשְׁפְּזִיכָא … נקיטא</span>, v. <a href=\"#\" data-headword=\"אוּשְׁפִּיזְכָן\">אושפיזכן</a>; v. Rabb. D. S. a. l.) the Divine fire took up its abode now here and now there. <span class=\"citation\">Erub. 53ᵇ</span> <span dir=\"rtl\">שאיל בא׳</span> (Rashi <span dir=\"rtl\">משייל בעניין אושפזיכני</span>, read <span dir=\"rtl\">ניה …</span>, v. Rabb. D. S. a. l. note 80) inquired after the character of an inn (of his landlord). <span class=\"citation\">Ib.</span> (enigmatic inquiry that the landlord might not overhear it) <span dir=\"rtl\">גבר פום דין חי מה טיבו</span> Ar. (v. Rabb. l. c. note 90) = <span dir=\"rtl\">איש־פי־ז־נא</span> our inn—what is its character?</div>","alt":[]},"933":{"h":"אוּשְׁפִּיזִיכְנָא","r":"A00933","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אושפיזכ׳</span></div>","alt":["אוּשְׁפִּיזִיכְתָּא"]},"934":{"h":"אוּשְׁפִּיזְכָן","r":"A00934","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Denom. of <a href=\"#\" data-headword=\"אוּשְׁפֵּיז\">אושפיז</a> = <span dir=\"rtl\">אושפיזך</span>, with locat. <a href=\"#\" data-headword=\"כ\">ך</a>, cmp. <a href=\"#\" data-headword=\"דָּא I\">דָּא</a>, <a href=\"#\" data-headword=\"דֵּךְ\">דֵּךְ</a>) <i>innkeeper, landlord, host</i>. <span class=\"citation\">Meg. 26ᵃ</span>; <span class=\"citation\">Yoma 12ᵃ</span>; <span class=\"citation\">Sot. 37ᵃ</span>; <span class=\"citation\">Zeb. 54ᵃ</span> נעשה א׳ וכ׳ Benjamin became the host of the Divine Presence (the Temple being partly situated in his territory).</div>","alt":[]},"935":{"h":"אוּשְׁפִּיזְכָנָא","r":"A00935","html":"<div class=\"sense\"> <span class=\"citation\">Zeb. 18ᵇ</span> <span dir=\"rtl\">בר אושפיזכניה</span> (Ms. M. only <a href=\"#\" data-headword=\"אוּשְׁפְּזִיכְנָא\">אוּשְׁפְּזִיכְנֵיה</a>) (the son of) his host. <span class=\"citation\">Snh. 7ᵇ</span> bot. <span class=\"citation\">Yoma 78ᵃ</span> פיזכנה … Ms. M. (ed. <span dir=\"rtl\">נין …</span>). <span class=\"citation\">Bets. 4ᵃ</span>; a. fr.—<span class=\"citation\">Erub. 53ᵇ</span>, v. <a href=\"#\" data-headword=\"אוּשְׁפִּיזָא\">אוּשְׁפִּיזָא</a>.—Fem. <a href=\"#\" data-headword=\"אוּשְׁפִּיזִיכְנָא\">אוּשְׁפִּיזַכְתָּא</a> <i>hostess</i>. <span class=\"citation\">Ber. 18ᵇ</span> ed. Ms. M. <span dir=\"rtl\">(בת אושפיזכניה</span>).</div>","alt":["אוּשְׁפִּיזִיכְנָא"]},"936":{"h":"*אוּשְׁפַּרְתִּי","r":"A00936","html":"<p class=\"morphology\">pr. n. f.</p><div class=\"sense\"> (?) <i>Ushparti</i>. <span class=\"citation\">Taan. 24ᵇ</span> Ms. (ed. <span dir=\"rtl\">אושפז׳</span>, v. Rabb. D. S. a. l. note, a. Var. lect. ibid.).</div>","alt":[]},"937":{"h":"אוּשְׁקָקָא","r":"A00937","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִשְׁקָק\">אִשְׁקָקָא</a></div>","alt":[]},"938":{"h":"אֶוְשַׁר","r":"A00938","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֶוְושַׁר\">אֶוְושַׁר</a></div>","alt":[]},"939":{"h":"אוֹת I","r":"A00939","html":"<div class=\"sense\"><i>to join, fit</i>.</div><div class=\"sense\"><b>Nif. נֵאוֹת  נֵיאוֹת</b> <div class=\"sense\"> (b. h.) <i>to be suited, pleased</i>, whence <i>to be gratified, to enjoy</i>. Y. Ber. III, 6ᶜ top <span dir=\"rtl\">ראה את עצמו נ׳ וכ׳</span> he dreamt he felt sexual gratification; Y. Yoma VII, 44ᵈ bot.; Y. Taan. I, 64ᶜ bot.—Y. Bets. I, 61ᵃ <span dir=\"rtl\">כל שנֵאותין בו בי&quot;ט</span> whatever you are permitted to make use of on Holy Days.—<i>Fut</i>. <a href=\"#\" data-headword=\"יָאוּת\">יֵאוֹת</a>. <span class=\"citation\">Ber. VIII, 6</span> <span dir=\"rtl\">עד שיֵאוֹתוּ לאורו</span> until being near enough to enjoy its light. Y. Ab. Zar. I, 39ᶜ top, a. e., differences as to spelling <span dir=\"rtl\">יֵאוֹתוּ</span> or <span dir=\"rtl\">יֵעוּתוּ</span>.—Denom. <a href=\"#\" data-headword=\"הֲנָיָיה\">הֲנָאָה</a>, <a href=\"#\" data-headword=\"נָאֶה\">נָאֶה</a>, <a href=\"#\" data-headword=\"נָאוֶה\">נָאוֶה</a>, <a href=\"#\" data-headword=\"נוֹי\">נוֹי</a>.</div></div>","alt":["אוּת"]},"940":{"h":"אוֹת II","r":"A00940","html":"<div class=\"sense\"> c. (b. h.; v. <a href=\"#\" data-headword=\"אוי\">אוי</a>, </div><div class=\"sense\"><b>1)</b> <i>mark, sign, emblem; test, signal, military ensign</i>. Ḥag. 16ᵃ (play on <span dir=\"rtl\">ואתה</span> <span class=\"citation\">Deut. XXXIII, 2</span>; cmp. <a href=\"#\" data-headword=\"אוֹת I\">foreg.</a>) <span dir=\"rtl\">אות הוא וכ׳</span> He is the ensign among his myriad; v. <a href=\"#\" data-headword=\"דּוּגְמָא\">דּוּגְמָא</a>. <span class=\"citation\">M. Kat. 25ᵇ</span> <span dir=\"rtl\">אל תזניחנו בא׳ וכ׳</span> forsake us not in the symbolic trial of bitter waters (in our trials). Pl. <span dir=\"rtl\">אוֹתוֹת</span>. <span class=\"citation\">Kil. IX, 10</span> <span dir=\"rtl\">א׳ הגרדין וכ׳</span> the marks which the weavers &amp;c. put on goods in their charge. <span class=\"citation\">B. Kam. 119ᵇ</span> you must not buy from the dyer <span dir=\"rtl\">לא א׳ ולא דוגמות</span> either <i>tests</i> (pieces cut off to test the color) or samples (as specimens of color).</div><div class=\"sense\"><b>—2)</b> <i>letter, writing, symbol</i>. <span class=\"citation\">B. Bath. 15ᵃ</span> <span dir=\"rtl\">אות אחת</span> one letter. <span class=\"citation\">Sabb. 103ᵃ</span>; a. fr.—Pl. <span dir=\"rtl\">אוֹתִיּוֹת</span> (fr. <span dir=\"rtl\">אוֹתוּת</span> or <span dir=\"rtl\">אוֹתִית</span>). <span class=\"citation\">Kidd. 30ᵃ</span> <span dir=\"rtl\">סופרים כל הא׳</span> recorded (or counted) all the letters of the Torah. <span class=\"citation\">Snh. X, 1</span> <span dir=\"rtl\">השם באוֹתִיוֹתָיו</span> the Divine Name with the letters in which it is written (Jehovah). <span class=\"citation\">Kidd. 71ᵃ</span> <span dir=\"rtl\">שם בן ארבע א׳</span> the quadriliteral Name; cmp. <a href=\"#\" data-headword=\"שֵׁם\">שֵׁם</a>.—<span class=\"citation\">Lev. R. s. 26</span>, beg. <span dir=\"rtl\">ח׳ א׳</span> eight letters. <span class=\"citation\">Sabb. XII, 3</span>; a. fr.—Trnsf. <i>notes, documents</i>. <span class=\"citation\">Tosef. Kidd. I, 7</span>; <span class=\"citation\">B. Bath. 75ᵇ</span>; a. e.</div>","alt":[]},"941":{"h":"אוֹת III","r":"A00941","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֵת\">אֵת</a>) only with pronominal suffix </div><div class=\"sense\"><b>1)</b>  indicating the objective case, <a href=\"#\" data-headword=\"יְתַר\">אוֹתִי</a> <i>me</i>, <span dir=\"rtl\">אוֹתְךָ</span> <i>thee</i></div><div class=\"sense\"><b>—2)</b>  with pronom. suffix of third person, for emphasizing the subject, <span dir=\"rtl\">אוֹתוֹ</span> <i>he himself, this one, the same, he who</i> &amp;c. <span class=\"citation\">Gen. R. s. 2</span>, beg. <span dir=\"rtl\">ישב לו א׳ וכ׳</span> the latter now sat there confounded &amp;c. <span class=\"citation\">Y. Git. VI, 47ᵈ</span> <span dir=\"rtl\">באותו ענין</span> on this very subject (divorce). <span class=\"citation\">Sabb. 13ᵇ</span> <span dir=\"rtl\">זכור אותו האיש וכ׳</span> may that man be remembered for good. <span class=\"citation\">Ber. V, 3</span> <span dir=\"rtl\">באוֹתָהּ שעה</span> in that hour; a. fr.—<span dir=\"rtl\">אותו מקום</span> euphem. for <i>pudenda</i>. <span class=\"citation\">Nidd. 47ᵇ</span>. <span class=\"citation\">Git. 69ᵇ</span>; a. e.—אותו ואת בנו <i>the law concerning the killing of the young with its mother on the same day</i> (<span class=\"citation\">Lev. XXII, 28</span>). <span class=\"citation\">Ḥull. V, 1</span>; a. fr.—Pl. <span dir=\"rtl\">אוֹתָן</span>. <span class=\"citation\">Y. Meg. IV, 74ᵈ</span> top <span dir=\"rtl\">א׳ שבפה</span> those laws delivered orally. <span class=\"citation\">Keth. 4ᵃ</span> <span dir=\"rtl\">כל א׳ הימים</span> all those days; a. fr. [In later writings <span dir=\"rtl\">אותו האיש</span> is freq. used for Jesus of Nazareth.</div>","alt":[]},"942":{"h":"אוֹתָבוּתָא","r":"A00942","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">יתב</span>) <i>sitting down, sitting</i>. <span class=\"citation\">Targ. Ps. CXXXIX, 2</span>.</div>","alt":[]},"943":{"h":"אותונין","r":"A00943","html":"<div class=\"sense\">, <span class=\"citation\">Cant. R. to III, 11</span>, read <a href=\"#\" data-headword=\"אִיקוֹנִין\">אִיקוֹנִין</a> as <span class=\"citation\">Ex. R. s. 35</span>, end.</div>","alt":[]},"944":{"h":"*אוּתְיָא","r":"A00944","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>night-bird, owl</i>. <span class=\"citation\">Targ. Y. Lev. XI, 18</span> (<span class=\"citation\">Targ. O. ib.</span> <span dir=\"rtl\">בותא</span> q. v.; <span class=\"citation\">Targ. Y. Deut. XIV, 16</span> <a href=\"#\" data-headword=\"צַדְיָא I\">צַדְיָא</a>). [Perh. corrupt. of <a href=\"#\" data-headword=\"בָּוְתָא\">בָּאוְתָא</a> v. <a href=\"#\" data-headword=\"בָּאוָת\">בָּאוָת</a>.]</div>","alt":[]},"945":{"h":"אותיום","r":"A00945","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֶוְותִּיאוֹס\">אֶוְותִּיאוֹס</a></div>","alt":["אֶוְתִּיוֹס"]},"946":{"h":"אותינייה","r":"A00946","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַוותֶּנְטְיָא\">אַוְותֶּנְטְיָא</a></div>","alt":[]},"947":{"h":"אותניתיה","r":"A00947","html":"<div class=\"sense\"> <span class=\"citation\">Y. Snh. II, 20ᶜ</span> bot. read <span dir=\"rtl\">כִּיתְנִיתֵיה</span>, v. <a href=\"#\" data-headword=\"כִּיתָּנִיתָא\">כִּיתְנִיתָא</a></div>","alt":[]},"948":{"h":"אֲזָא","r":"A00948","html":"<div class=\"sense\"><i>to kindle</i>, v. <a href=\"#\" data-headword=\"אֲזִי\">אֲזִי</a>.</div>","alt":[]},"949":{"h":"*אָזָא","r":"A00949","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>sea-eagle</i> (cmp. <a href=\"#\" data-headword=\"עִוּזָּא I\">עוזא</a>). <span class=\"citation\">Targ. Y. Deut. XIV, 12</span> Ar. (ed. <span dir=\"rtl\">בר גזא</span>, <span dir=\"rtl\">בר גיזא</span>; h. text <span dir=\"rtl\">עזניה</span>).</div>","alt":["אַזָּא"]},"950":{"h":"אזביון","r":"A00950","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֵזוֹב\">אַזוֹב</a></div>","alt":[]},"951":{"h":"*אַזְגָּא","r":"A00951","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>glass</i> (v. <a href=\"#\" data-headword=\"זַגָּגָא\">זְגָגָא</a>). <span class=\"citation\">Keth. 77ᵇ</span> גירדא דא׳ Ar. parings of glass (ed. <a href=\"#\" data-headword=\"אֱגוּזָא\">אגוזא</a>).</div>","alt":[]},"952":{"h":"אִזְגַּד","r":"A00952","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אִזְתַּוְודָּא\">אִיזְ׳</a></div>","alt":["אִזְגַּדָּא"]},"953":{"h":"אזגור","r":"A00953","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיזְגְּדַר\">אִיזְגְּדַר</a></div>","alt":[]},"954":{"h":"אזד־","r":"A00954","html":"<div class=\"sense\"> Ithpe. prefix of verbs with prim. lit. <a href=\"#\" data-headword=\"ז\">ז</a> as <a href=\"#\" data-headword=\"זְוַג\">אזדווג</a> fr. <span dir=\"rtl\">זווג</span></div>","alt":[]},"955":{"h":"אֲזַד","r":"A00955","html":"<div class=\"sense\"> (= <span dir=\"rtl\">אזז</span> √<span dir=\"rtl\">אז</span>; cmp. <a href=\"#\" data-headword=\"אֲזַל I\"><span dir=\"rtl\">אזל</span> I</a>; <span dir=\"rtl\">גז</span>, <a href=\"#\" data-headword=\"חֵז\">חז</a>, <span dir=\"rtl\">עז</span>, <a href=\"#\" data-headword=\"חֲצַד I\">חצד</a> &amp;c.) <i>to be cut off; to go apart, be gone</i>. <span class=\"citation\">Sabb. 34ᵇ</span>; a. fr. <span dir=\"rtl\">ואזדו לטעמייהו</span> they differ (cmp. <a href=\"#\" data-headword=\"פְּלַג I\">פלג</a>), each following his own principle (or consistent with opinions elsewhere expressed). <span class=\"citation\">Ned. 41ᵃ</span> <span dir=\"rtl\">שיתא אזדו</span> (Rashi <span dir=\"rtl\">אזלו ליה</span>) six of them are gone (escaped his memory). <span class=\"citation\">Bets. 10ᵇ</span> <span dir=\"rtl\">אזדו לעלמא</span> disappeared (Ms. M. <span dir=\"rtl\">אזלו</span>; <span class=\"citation\">11ᵃ</span> <span dir=\"rtl\">אזלו</span>). <span class=\"citation\">Meïl. 17ᵇ</span> נפק אזדא Ar. (read <span dir=\"rtl\">אזד</span>, ed. <a href=\"#\" data-headword=\"אֲזַל I\">אזל</a>) he went out and away. V. <a href=\"#\" data-headword=\"אֲזַל I\">אֲזַל</a>.</div>","alt":[]},"956":{"h":"אַזְדָּא","r":"A00956","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲזַד\">foreg.</a>) [<i>it is</i>] <i>decreed</i> (cmp. <a href=\"#\" data-headword=\"גְּזֵרָה\">גְּזֵרָה</a>). <span class=\"citation\">Dan. II, 5</span>.—<span class=\"citation\">B. Mets. 116ᵇ</span> if the landlord said, I let you <i>this</i> loft (as it is) <a href=\"#\" data-headword=\"א׳\">א׳</a> it is a (divine) decree, i.e. it is the tenant’s misfortune that the loft fell in, and he has no claims. V. Ges. H. Dict. s. v.</div>","alt":[]},"957":{"h":"אִזְדַּעְזְעָא","r":"A00957","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִזְדַּעֲזָעוּתָא\">next w.</a></div>","alt":[]},"958":{"h":"אִזְדַּעֲזָעוּתָא","r":"A00958","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זוּעַ\">זוּעַ</a>) <i>shaking, trembling</i>. <span class=\"citation\">Targ. Job. XII, 5</span> Ms. (ed. <a href=\"#\" data-headword=\"אִזְדַּעְזְעָא\">אזדעזעא</a>, const. … <a href=\"#\" data-headword=\"עֵת\">עַת</a>).</div>","alt":[]},"959":{"h":"אִזְדְּקָפוּתָא","r":"A00959","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<i>Ithpe.</i> or <i>Ithpa.</i> of <a href=\"#\" data-headword=\"זְקַף\">זְקַף</a>) <i>rising</i>. <span class=\"citation\">Targ. Job. XIII, 11</span>. <span class=\"citation\">Ib. XLI, 17</span> Ms. Var., v. <span dir=\"rtl\">מספיא</span>.</div>","alt":["אִזְדַּקָּפוּתָא"]},"960":{"h":"אֵזֶהוּ","r":"A00960","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֵיזֶה\">אֵיזֶה</a></div>","alt":[]},"961":{"h":"אַזְהָרָא","r":"A00961","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַזְהַרְתָּא\">אַזְהַרְתָּא</a></div>","alt":[]},"962":{"h":"אַזְהָרָה","r":"A00962","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">זהר</span>) </div><div class=\"sense\"><b>1)</b> <i>forewarning, prohibition</i>, esp. <i>the explicit prohibition</i> (‘<i>thou shalt not</i>’) <i>in the Bible</i>, required for punishing trespassers. <span class=\"citation\">Y. Peah I, 16ᵃ</span> top <span dir=\"rtl\">א׳ ללה&quot;ר</span> a biblical admonition against calumny. <span class=\"citation\">Num. R. s. 7</span> (play on <i>zara</i> <span class=\"citation\">Num. XI, 20</span>) <span dir=\"rtl\">והי׳ לכם לא׳</span> it shall be a warning to you. <span class=\"citation\">Yeb. 3ᵇ</span> <span dir=\"rtl\">א׳ שמענו וכ׳</span> we learn here the legal prohibition, whence do we derive the penalty? a. tr.—Pl. <span dir=\"rtl\">אַזְהָרוֹת</span>. <span class=\"citation\">Kerith. III, 10</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>enlightenment</i>. <span class=\"citation\">Cant. R. to VII, 3</span>, v. <a href=\"#\" data-headword=\"אֵדֶר I\">אִדַּר</a>.</div>","alt":[]},"963":{"h":"אַזְהַרְתָּא","r":"A00963","html":"<div class=\"sense\">as <a href=\"#\" data-headword=\"אַזְהָרָה\">foreg.</a> 1. <span class=\"citation\">Shebu. 20ᵇ</span> <span dir=\"rtl\">ואַזְהַרְתֵּיה מה׳</span> and the legal prohibition concerning it, is to be derived from this verse.—Pl. <a href=\"#\" data-headword=\"אַזְהָרָא\">אַזְהָרָן</a>. <span class=\"citation\">Y. Yoma VIII, 45ᵃ</span> <span dir=\"rtl\">תלת א׳</span> three prohibitory verses.</div>","alt":["אַזְהָרָא"]},"964":{"h":"אֵזוֹב","r":"A00964","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>hyssop.</i> <span class=\"citation\">Neg. XIV, 6</span> <span dir=\"rtl\">א׳ יון</span> (Ar. <a href=\"#\" data-headword=\"אזביון\">אזביון</a>) Greek hyssop. <span class=\"citation\">Sabb. XIV, 3</span> (<span class=\"citation\">109ᵇ</span>) <span dir=\"rtl\">איזוביון</span>, <a href=\"#\" data-headword=\"אֵיזֹבְיָוָן\">איזביון</a> (read two words, Ms. O., v. Rabb. D. S. a. l. note 4); a. fr.—Pl. <span dir=\"rtl\">אֵיזוֹבִים</span> <span class=\"citation\">M. Kat. 25ᵇ</span> <span dir=\"rtl\">אֵיזוֹבֵי קִיר</span> the hyssop (moss) on the wall (common humanity); v. <a href=\"#\" data-headword=\"אֶרֶז\">אֶרֶז</a>.</div>","alt":["אֵיזוֹב"]},"965":{"h":"אֵזוֹבָא","r":"A00965","html":"<div class=\"sense\"><span class=\"citation\">Targ. Ex. XII, 22</span>; a. e.</div>","alt":["אֵיזוֹבָא"]},"966":{"h":"אֵזוֹר","r":"A00966","html":"<div class=\"sense\"> c. (b. h.; <i>girdle, belt</i>. <span class=\"citation\">M. Kat. 14ᵃ</span> <span dir=\"rtl\">אֵיזוֹרוֹ וכ׳</span> his girdle (around his house-gown) testifies for him (that he has no more than the shirt he is washing). <span class=\"citation\">Tosef. Shebu. V, 12</span> sq.; a. e.—Pl. <span dir=\"rtl\">אֵזוֹרִים</span>, <a href=\"#\" data-headword=\"*אִזְתַּוְודָּא\">אֵיז׳</a>. <span class=\"citation\">Gen. R. s. 100</span> <span dir=\"rtl\">אֵזוֹרֵי מתניהם וכ׳</span> they loosened the girdles of their loins (in mourning sympathy). [Ch. <span dir=\"rtl\">זריז</span>.]</div>","alt":["אֵיזוֹר"]},"967":{"h":"אֵזוֹרָא","r":"A00967","html":"<div class=\"sense\">Sot. I, 17ᵇ top <span dir=\"rtl\">איזורִי ואיזורֵיה דברי וכ׳</span> my belt, and my son’s belt and that of his father in law; <span class=\"citation\">Num. R. s. 9</span> (p. 232ᵇ ed. Amst.); <span class=\"citation\">Y. Peah VII, 20ᵃ</span> bot. (corr. acc.); cmp. Midr. Sam. ch. XIII.</div>","alt":["אֵיזוֹרָא"]},"968":{"h":"אֲזִי","r":"A00968","html":"<div class=\"sense\"> (= <span dir=\"rtl\">אַזְעִי</span>, v. <a href=\"#\" data-headword=\"*אוּדְיָיתָא I\">אוּדְיָיתָא</a> a. <a href=\"#\" data-headword=\"זִיעַ\"><a href=\"#\" data-headword=\"זִיעַ\">זִיעַ</a>)</a><i>to heat</i> (<i>make steam</i>). <span class=\"citation\">Dan. III, 19</span>; <span class=\"citation\">22</span>.—<span class=\"citation\">Targ. Is. XXXIII, 4</span> <span dir=\"rtl\">וַאֲזַן</span> (Regia <span dir=\"rtl\">אֵיזִין</span>) and they shall heat (baths, ovens) therewith (h. text <span dir=\"rtl\">מַשַּׂק</span> = <span dir=\"rtl\">מַשַּׁק</span>), v. <a href=\"#\" data-headword=\"זִירְקְתָא\">זִירְקְתָא</a>; (cmp. <span class=\"citation\">Ezek. XXXIX, 9</span>). Ib. XLIV, 15 (for baking); a. e.—Y. Ter. VIII, end, 46ᶜ a bath house <span dir=\"rtl\">דאזייה וכ׳</span> which he had heated for seven days. <span class=\"citation\">Koh. R. to II, 8</span>; a. e. <span dir=\"rtl\">דהוון אָזְיִין בהון</span> that entertained the fires in them.—<span class=\"citation\">Lev. R. s. 28</span>, end <span dir=\"rtl\">ועל מזגיה וקנחיה</span> (read <span dir=\"rtl\">ואַזְּיֵיה</span> Pa.) and he (Haman) went and made him sweat and cleansed him (with the scraper).</div><div class=\"sense\"><b>Ithpe. אִתְּזִי</b> <div class=\"sense\"> (contr. of <span dir=\"rtl\">אתאזי</span>) <i>to be heated</i>. <span class=\"citation\">Gen. R. s. 63</span> קלוון אנא דיִתְּזוּן וכ׳ I command that the bath-houses be heated. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אזלון ואִתְּזוּן</span> they went off, and the bath-houses were heated (some ed. <span dir=\"rtl\">דְּיִחֲמוּן</span> a. <span dir=\"rtl\">אַחְמוּן</span>).</div></div>","alt":["אֲזָא"]},"969":{"h":"אֲזִיל","r":"A00969","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲזַל I\">אֲזַל</a></div>","alt":[]},"970":{"h":"אֲזֵינָא","r":"A00970","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. (<span dir=\"rtl\">זין</span>) <span dir=\"rtl\">אֲזֵינִין</span> <i>weapons</i>, <a href=\"#\" data-headword=\"אֶבֶן\">בית א׳</a> <i>receptacle of weapons, quiver</i>. <span class=\"citation\">Targ. Jer. V, 16</span>. <span class=\"citation\">Targ. Is. XLIX, 2</span> (ed. Ven. <span dir=\"rtl\">אַזְנִין</span>). V. Targ. to <span class=\"citation\">Deut. XXIII, 14</span> <span dir=\"rtl\">אֲזֵנֶךָ</span>.</div>","alt":[]},"971":{"h":"*אַזֵּיק","r":"A00971","html":"<div class=\"sense\"> (Af. of <span dir=\"rtl\">אזק</span>, v. <span dir=\"rtl\">חזק</span>, <span dir=\"rtl\">עזק</span>)<i>to tie up</i>. <span class=\"citation\">Koh. R. to VIII, 1</span> א׳ לרישי I have to tie up my head. (<span class=\"citation\">Yalk. Koh. 977</span> <span dir=\"rtl\">דחיק</span>, Vers. <span dir=\"rtl\">אדיק</span>; <span class=\"citation\">Y. Pes. X, 37ᶜ</span> <span dir=\"rtl\">חזיק רישיה</span> his head was tied; cmp. <span class=\"citation\">Ned. 49ᵇ</span>.)</div>","alt":[]},"972":{"h":"אַזְכָּרָה","r":"A00972","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.; = <a href=\"#\" data-headword=\"הַזְכָּרָה\">הַזְכָּרָה</a>, </div><div class=\"sense\"><b>1)</b> <i>remembrance, mention</i> (of Div. Name), <i>recitation</i> (of prayer); <i>reference</i>. <span class=\"citation\">Y. Ber. V, 9ᵇ</span> <span dir=\"rtl\">א׳ שהיא מריוח</span> the reference to rain (in the second section of the eighteen benedictions) which is an expression of satisfaction (plenty), opp. <a href=\"#\" data-headword=\"שְׁאֵלָה\">שאלה</a>, the prayer for rain (in the ninth benediction) which is an expression of anxiety.—<span class=\"citation\">Y. Meg. III, 74ᵇ</span> top <span dir=\"rtl\">שתהא אַזְכָּרָתָן קודם וכ׳</span> that the recitation (of the events commemorated on Purim) precede the celebration thereof.</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"אַדְכָּרָה\">אַדְכָּרָה</a>) <i>the Divine Name, Tetragrammaton</i>. <span class=\"citation\">Num. R. s. 2</span>, beg. the students <span dir=\"rtl\">מראים את הא׳ וכ׳</span> point out the Div. Name with their fingers; <span class=\"citation\">Cant. R. to II, 4</span> <span dir=\"rtl\">מדלג על הא׳</span> skips the Div. Name in recitation of lessons.—Pl. <span dir=\"rtl\">אַזְכָּרוֹת</span>. <span class=\"citation\">Yoma 8ᵃ</span> <span dir=\"rtl\">שיש בהן א׳ הרבה</span> in which the Div. N. frequently occurs. <span class=\"citation\">Y. Ber. III, 6ᶜ</span>.—Y. Sabb. XVI, 15ᶜ bot.; Bab. <span class=\"citation\">ibid. 116ᵃ</span> <span dir=\"rtl\">קודר אזכרותֵיהֶן</span> you must cut out the Div. N. occurring in them (the heretic writings). <span class=\"citation\">Y. Taan. II, 65ᶜ</span> top <span dir=\"rtl\">י&quot;ח א׳ וכ׳</span> eighteen times that the Tetragrammaton appears in the Psalm <i>Habu</i> (XXIX). <span class=\"citation\">Num. R. s. 2</span>, beg.; a. fr.</div>","alt":[]},"973":{"h":"אֲזַל I","r":"A00973","html":"<div class=\"sense\"><i>to be gone, to leave; to go</i>. <span class=\"citation\">Targ. Gen. XXXII, 1</span>. <i>Imper</i>. <span dir=\"rtl\">אִיזֵּיל</span>, <span dir=\"rtl\">אִזֵּיל</span>. <span class=\"citation\">Targ. O. Num. XXII, 20</span>; a. fr.—<span class=\"citation\">Y. Snh. X, 28ᵇ</span> <span dir=\"rtl\">איזיל חמי וכ׳</span> go, show thy face &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לינה מֵיזַל … דנא מיזל וכ׳</span> I will not go … for if I did go &amp;c. <span class=\"citation\">Sabb. 116ᵃ</span> <span dir=\"rtl\">א׳ כתב א׳ וכ׳</span> after the writing is gone, the sacredness of the scroll is gone (after the scroll has become unfit for sacred use, the material has lost its sacred character). <span class=\"citation\">Y. Dem. III, 23ᵇ</span> bot. <span dir=\"rtl\">הא אזילא מיבלא וכ׳</span> that man’s load would soon be gone (if each were permitted to take a chip). <span class=\"citation\">Y. Ber. VIII, 12ᵃ</span> <span dir=\"rtl\">הא אזילא ההיא דרב וכ׳</span> is the decision of Rab and Samuel gone (to be disregarded)? <span class=\"citation\">Y. Snh. X, 28ᵃ</span> bot. <span dir=\"rtl\">הא א׳ הדא וכ׳</span> (ed. Krot. <a href=\"#\" data-headword=\"חדא\">חדא</a>) is that which was received from (is the tradition of) … to be disregarded? <span class=\"citation\">Y. Yeb. VIII, 9ᶜ</span> bot. <span dir=\"rtl\">הא אזילא היא וכ׳</span> (ed. Krot. <a href=\"#\" data-headword=\"אִיזְלָא\">איזלא</a>, corr. acc.; for <span dir=\"rtl\">היא</span> read <span dir=\"rtl\">הדא</span> or <a href=\"#\" data-headword=\"הַהוּא\">ההיא</a>).—Trnsf. <i>to depart life, die</i>. <span class=\"citation\">Y. Ḥag. II, 77ᵈ</span> bot. this one committed a sin <span dir=\"rtl\">וא׳ בה</span> and died in it, and the other &amp;c. <span class=\"citation\">M. Kat. 28ᵇ</span> <span dir=\"rtl\">ווי לאזלא</span> woe, for the departed one! <span class=\"citation\">Y. Keth. XII, 35ᵃ</span> top <span dir=\"rtl\">אזיל</span> <i>to die</i>, contrad. to <span dir=\"rtl\">אתי</span> to <i>resurrect</i>.—Imperat. usu. <a href=\"#\" data-headword=\"זִיל\">זִיל</a> = <span dir=\"rtl\">אזיל</span>.—<span class=\"citation\">Ḥull. 11ᵇ</span> <span dir=\"rtl\">ז׳ בתר רובא</span> follow the majority of cases; a. fr.</div>","alt":["אָזַל","אֲזִיל"]},"974":{"h":"אֲזַל II","r":"A00974","html":"<div class=\"sense\"> (= <a href=\"#\" data-headword=\"עֲזַל\">עזל</a>; v. <span class=\"citation\">Ezek. XXVII, 19</span>; √<a href=\"#\" data-headword=\"זָל\">זל</a>) <i>to spin, weave</i>. <span class=\"citation\">B. Mets. 24ᵇ</span> <span dir=\"rtl\">קיבורא דאזלי ביה אזלויי</span> a skein which the net-weavers had used; v. <a href=\"#\" data-headword=\"זוּל II\"><span dir=\"rtl\">זוּל</span> II</a>. Denom. <a href=\"#\" data-headword=\"אִיזְלָא\">אִיזְלָא</a> a. <a href=\"#\" data-headword=\"אַזְלוֹיָא\">next w.</a></div>","alt":[]},"975":{"h":"אַזְלוֹיָא","r":"A00975","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲזַל II\">foreg.</a>) <i>weaver.</i> Pl. <span dir=\"rtl\">אַזְלוֹיֵי</span>. <span class=\"citation\">B. Mets. 24ᵇ</span> (some ed. <span dir=\"rtl\">אזלוי</span> corr. acc.), v. <a href=\"#\" data-headword=\"אֲזַל II\">foreg.</a></div>","alt":[]},"976":{"h":"*אֲזָלַיָּא","r":"A00976","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (= <span dir=\"rtl\">נזל</span>) <i>running waters, waves</i>. <span class=\"citation\">Targ. O. Ex. XV, 8</span> (Var. <a href=\"#\" data-headword=\"*אֲזָלַיָּא\">אָזְלַיָּא</a>; Y. <a href=\"#\" data-headword=\"נוֹזְלַיָּא\">נָזְלַיָּא</a>).</div>","alt":[]},"977":{"h":"אזמאזמא","r":"A00977","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיזְמָא\">אִיזְמָא</a></div>","alt":[]},"978":{"h":"אזמורד","r":"A00978","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִזְמַרְגַּד\">אִזְמַרְגַּד</a></div>","alt":[]},"979":{"h":"אִזְמֵל","r":"A00979","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיזְמֵיל\">אִיזְמֵל</a></div>","alt":[]},"980":{"h":"אִזְמַרְגַּד","r":"A00980","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (σμάραγδος, σμαράγδιον) <i>emerald</i>, a jewel (also <i>colored crystal</i>; v. <a href=\"#\" data-headword=\"זְמַרְגַּד\">זמרגד</a> a. <a href=\"#\" data-headword=\"זְמַרַגְדִּין\"><a href=\"#\" data-headword=\"זְמַרַגְדִּין\">זמרגדין</a>)</a>. <span class=\"citation\">Targ. Job. XLII, 13</span>. <span class=\"citation\">Targ. O. Ex. XXVIII, 18</span> (<span class=\"citation\">Targ. Y. ib.</span> <a href=\"#\" data-headword=\"אזמורד\">אִזְמוֹרַד</a>); a. e. <span class=\"citation\">Ex. R. s. 38</span>, end <a href=\"#\" data-headword=\"אִסְמַרַגְדִּין\">אִסְמַרַגְדִּין</a>.</div>","alt":["אִזְמַרְגְּדָא","אִזְמַרְגְּדִין","(אִזְמַרְגְּזִין","אִזְמְרַגְדִּין)"]},"981":{"h":"אֲזַן","r":"A00981","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Is. XXXIII, 4</span>, third pers. pl. of <a href=\"#\" data-headword=\"אֲזָא\">אֲזָא</a>, v. <a href=\"#\" data-headword=\"אֲזִי\">אֲזִי</a></div>","alt":[]},"982":{"h":"אֹזֶן","r":"A00982","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>to be pointed, cut</i>, cmp. <a href=\"#\" data-headword=\"חֵז\">חז</a>, <span dir=\"rtl\">גז</span>. v. <a href=\"#\" data-headword=\"אוֹדֶן\">אוּדְנָא</a>) </div><div class=\"sense\"><b>1)</b> <i>ear</i>. <span class=\"citation\">B. Kam. 79ᵇ</span> <span dir=\"rtl\">א׳ של מַטָּה</span> human ear, opp. Divine perception. Y. Sabb. I, 3ᵇ top; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>handle</i>. Cant. R. beg. <span dir=\"rtl\">ולא הי׳ לה א׳ וכ׳</span> but had no handle and could not be carried; a. fr.—<i>Du</i>. <span dir=\"rtl\">אָזְנַיִם</span> 1) <i>ears</i>. <span class=\"citation\">Lev. R. s. 32</span>, beg. <span dir=\"rtl\">א׳ לדרך</span> the road has ears (be on your guard in speaking); a. fr.—2) <i>handles.</i> <span class=\"citation\">Kel. IV, 3</span>, v. <a href=\"#\" data-headword=\"גִּיסְטְרָא\">גיסטרא</a>; a. fr.</div><div class=\"sense\"><b>—3)</b>  <span dir=\"rtl\">אָזְנַיִם</span> or <span dir=\"rtl\">בנות א׳</span> <i>swollen glands of the throat</i> (Rashi). <span class=\"citation\">Ab. Zar. 28ᵇ</span> <a href=\"#\" data-headword=\"א׳\">א׳</a>; Y. ib. II, 40ᵈ top; <span class=\"citation\">Y. Sabb. XIV, 14ᵈ</span> top <span dir=\"rtl\">בנות א׳</span>.</div>","alt":["אוֹזֶן"]},"983":{"h":"אָזְנִיֹּות","r":"A00983","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*אוּזְנִיֹּות\">אוּזְנִיּוֹת</a></div>","alt":[]},"984":{"h":"אָזַר","r":"A00984","html":"<div class=\"sense\"><i>to put around, girdle; to strengthen</i>.</div><div class=\"sense\"><b>Hithpa. הִתְאַזָּר</b> <div class=\"sense\"><i>to gird, strengthen one’s self</i>. <span class=\"citation\">Ber. 16ᵇ</span> <span dir=\"rtl\">ותִתְאַזָּר וכ׳</span> and gird thyself with thy mercy.</div></div>","alt":[]},"985":{"h":"אֶזְרָח","r":"A00985","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> [<i>planted</i>], <i>native, citizen</i>. <span class=\"citation\">Succ. 28ᵃ</span> <span dir=\"rtl\">א׳ זה א׳</span> if it read <i>ezraḥ</i> (<span class=\"citation\">Lev. XXIII, 42</span>), it would mean every native (man or woman); a. fr.—Pl. <span dir=\"rtl\">אֶזְרָחִים</span>. Sifra Emor, end.—Fem. <span dir=\"rtl\">אֶזְרָחִית</span>, pl. <span dir=\"rtl\">אֶזְרָחִיּות</span>. Succ. l. c.</div>","alt":[]},"986":{"h":"אֶזְרְעָא","r":"A00986","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>arm</i>. Targ. Y. II. <span class=\"citation\">Num. XXXI, 50</span>; v. <a href=\"#\" data-headword=\"זְרוֹעַ\">זְרוֹעַ</a>.</div>","alt":[]},"987":{"h":"*אִזְתַּוְודָּא","r":"A00987","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"זַוֵּוג\">זווד</a>) <i>attachment, handle.</i> Pl. <a href=\"#\" data-headword=\"*אִזְתַּוְודָּא\">אִזְתַּוְודֵּי</a>. <span class=\"citation\">Targ. Y. Ex. XXV, 12</span> ed. Vien. (oth. ed. <span dir=\"rtl\">אזתוור׳</span>; <span class=\"citation\">ib. XXXVII, 3</span> <span dir=\"rtl\">אסתוור׳</span>, v. Ibn Ezra comment. a. l.).</div>","alt":["אִיזְ׳"]},"988":{"h":"אָח I","r":"A00988","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>brother, kinsman; fellow, equal, fellow-believer</i> &amp;c. <span class=\"citation\">Meg. 11ᵃ</span> (play on <i>ăhashverosh</i>, Ahasverus) <span dir=\"rtl\">אָׄחִׄיו ש̇ל ר̇אש̇ וכ׳</span> a brother (in cruelty) to the chief tyrant (Nebucadn.); a. fr.—Pl. <a href=\"#\" data-headword=\"אַחִים\">אַחִים</a>, <span dir=\"rtl\">אַחִין</span>. <span class=\"citation\">Gen. R. s. 89</span>, beg. (play on <i>āḥu</i>, <span class=\"citation\">Gen. XLI, 2</span>) in years of plenty <span dir=\"rtl\">הבריות נעשו א׳ וכ׳</span> people are brotherly to each other. <span class=\"citation\">Gen. R. s. 99</span> <span dir=\"rtl\">אחים דפחתא וכ׳</span> brothers to the degraded woman (Dinah), … but not to Joseph; a. fr.—<span class=\"citation\">Cant. R. to VIII, 1</span> שני אחים <i>brother and sister</i></div>","alt":[]},"989":{"h":"אַח","r":"A00989","html":"<div class=\"sense\"> Targ. fr.—Pl. <span dir=\"rtl\">אָחִין</span>. <span class=\"citation\">Targ. Gen. XIII, 8</span>; a. e.—אַחֵי <span class=\"citation\">Yeb. 65ᵇ</span>.—<span class=\"citation\">Y. Yoma VI, 43ᵈ</span> אֲחֵינָן <i>our brothers</i></div>","alt":["אַחָא","אָחָא"]},"990":{"h":"אָח II","r":"A00990","html":"<div class=\"sense\"> interj. interj. </div><div class=\"sense\"><b>1)</b>  (b. h.) exclamation of sorrow, <i>Oh!</i> <span class=\"citation\">Meg. 11ᵃ</span> (play on <i>ăhashverosh;</i> v. <a href=\"#\" data-headword=\"אָח I\"><span dir=\"rtl\">אָח</span> I</a>) <span dir=\"rtl\">א׳ לראשו</span> woe upon his head. <span class=\"citation\">Snh. 102ᵇ</span> (play on <i>Ahab</i> <span dir=\"rtl\">אח־אב</span>) <span dir=\"rtl\">א׳ לשמי׳</span> a subject of grief to the Lord, and father (friend) of idolatry.—2 (= Syr.) exclamation of joy, <i>Ah!</i> <span class=\"citation\">Targ. Is. XLIV, 16</span> (h. <span dir=\"rtl\">הֶאָח</span>).</div>","alt":[]},"991":{"h":"אַחָא","r":"A00991","html":"<div class=\"sense\"><b>1)</b> <i>brother;</i> v. <a href=\"#\" data-headword=\"אַח\">אַח</a>.</div><div class=\"sense\"><b>—2)</b>  pr. n. m. <i>Aḥa</i>. <span class=\"citation\">Arakh. 22ᵇ</span>; <span class=\"citation\">Keth. 88ᵃ</span>, surnamed <span dir=\"rtl\">שר הבירה</span> superintendent of the palace. <span class=\"citation\">Y. Ber. II, 5ᵃ</span> R. A. surnamed Roba; a. many others. <span class=\"citation\">Y. Taan. II, 65ᵃ</span> bot.; a. v. fr.</div>","alt":["אָחָא"]},"992":{"h":"אַחַאי","r":"A00992","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Aḥai</i>. <span class=\"citation\">Ḥull. 59ᵇ</span></div>","alt":[]},"993":{"h":"אַחֲבָא","r":"A00993","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (contr. of <span dir=\"rtl\">אחי אבא</span>) <i>father’s brother, uncle</i>. <span class=\"citation\">Targ. Jer. XXXII, 7</span> <span dir=\"rtl\">אַחֲבוּךְ</span> thy uncle. <span class=\"citation\">Targ. O. Lev. X, 4</span> (Ms. I a. III <span dir=\"rtl\">אח אבוהי</span>; Targ. Y. <a href=\"#\" data-headword=\"חָבִיב\">חביבא</a> q. v.); a. e. <span class=\"citation\">Yeb. 21ᵇ</span> Ar. s. v. <span dir=\"rtl\">בי אחבא</span> (ed. <span dir=\"rtl\">בי דודי</span>).</div>","alt":["אַחְבָּא"]},"994":{"h":"אֶחָד","r":"A00994","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, <a href=\"#\" data-headword=\"אַחַת\">אַחַת</a> f. (b. h.; v. <a href=\"#\" data-headword=\"אָחַד\">next w.</a>, <i>one</i>. [Freq. represented by <a href=\"#\" data-headword=\"א׳\">א׳</a>.] <span class=\"citation\">Kidd. 50ᵇ</span>, a. fr. <span dir=\"rtl\">בבת אחת</span> <i>simultaneously</i>, v. <a href=\"#\" data-headword=\"בַּת III\"><span dir=\"rtl\">בַּת</span> III</a>. <span class=\"citation\">Peah III, 3</span> <span dir=\"rtl\">המחליק מאחת יד וכ׳</span> (Ms. M. <span dir=\"rtl\">בא׳</span>) he who takes out onions with a unity of hand, i.e. all of them for one purpose. <span class=\"citation\">Ber. 61ᵇ</span>, a. fr. <span dir=\"rtl\">על אחת כמה וכמה</span> (abbr. <span dir=\"rtl\">עאכ&quot;ו</span>) how much against one, i.e. <i>how much the more</i>.—אחד … אחד <i>both … as well as</i>. <span class=\"citation\">Tem. I, 1</span> <span dir=\"rtl\">א׳ האנשים וכ׳</span> both, men as well as women. <span class=\"citation\">Y. Keth. V, 29ᵈ</span> top <span dir=\"rtl\">אחת זו ואחתֹ זו</span> the one as well as the other; a. fr.—<span dir=\"rtl\">כְּאֶחָד</span>, <span dir=\"rtl\">כְּאַחַת</span> <i>at the same time</i>. <span class=\"citation\">Tosef. Neg. I, 11</span>; sq. <span class=\"citation\">Sot. 8ᵃ</span>; a. fr.—<span class=\"citation\">Yoma I, 7</span> <span dir=\"rtl\">והפג אחת</span> and cool thyself <i>for once, for a change</i>, v. <a href=\"#\" data-headword=\"חֲדַת\">חֲדַת</a>.—Pl. <span dir=\"rtl\">אֲחָדִים</span></div><div class=\"sense\"><b>1)</b> <i>singular, unique</i>. <span class=\"citation\">Yalk. Gen. 62</span> (ref. to <span dir=\"rtl\">דברים אחדים</span> <span class=\"citation\">Gen. XI, 1</span>) they spoke words <span dir=\"rtl\">על שני א׳</span> against two only ones (ref. to <span dir=\"rtl\">אחד</span> <span class=\"citation\">Ezek. XXXIII, 24</span> a. <span class=\"citation\">Deut. VI, 4</span>) [corr. acc. <span class=\"citation\">Gen. R. s. 38</span>].</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"אֲחַד\">אֲחַד</a>) <i>closed up, mysterious</i>. Gen. R. l. c. (Yalk. l. c. <span dir=\"rtl\">אֲחוּדִים</span> v. <a href=\"#\" data-headword=\"אָחַד\">next w.</a>).</div>","alt":[]},"995":{"h":"אָחַד","r":"A00995","html":"<div class=\"sense\"> (sec. r. of <a href=\"#\" data-headword=\"חוּד\">חוּד</a>, v. <span dir=\"rtl\">חוּד I</span>) <i>to join, close.</i> <i> Part. pass</i>. <span dir=\"rtl\">אָחוּד</span>, pl. <span dir=\"rtl\">אֲחוּדִים</span></div><div class=\"sense\"><b>1)</b> <i>closed up, mysterious</i>. <span class=\"citation\">Yalk. Gen. 62</span>, v. <a href=\"#\" data-headword=\"אֶחָד\">foreg.</a></div><div class=\"sense\"><b>—2)</b> <i>joined, united</i>. <span class=\"citation\">Gen. R. s. 38</span> (ref. to <span class=\"citation\">Gen. XI, 1</span>, v. <a href=\"#\" data-headword=\"אֶחָד\">foreg.</a>) <span dir=\"rtl\">דברים א׳</span> common goods, communism.</div>","alt":[]},"996":{"h":"אֲחַד","r":"A00996","html":"<div class=\"sense\">, <i>Pa</i>. <a href=\"#\" data-headword=\"חוּד\">אָחֵיד</a>, <a href=\"#\" data-headword=\"אָחַד\">אַחֵד</a> ch. (v. <a href=\"#\" data-headword=\"אָחַד\">foreg.</a>) </div><div class=\"sense\"><b>1)</b>  (corresp. to h. <span dir=\"rtl\">סגר</span> a. <span dir=\"rtl\">תפש</span>; cmp. h. <a href=\"#\" data-headword=\"אָחַז\">אחז</a>) <i>to close</i> (the door), <i>to lock up; to seize, capture</i>. <span class=\"citation\">Targ. Is. XXII, 22</span> <a href=\"#\" data-headword=\"חוּד\">אָחֵיד</a>. Ib. <a href=\"#\" data-headword=\"יִחוּד\">יֵיחוֹד</a>, <a href=\"#\" data-headword=\"יִחוּד\">יִיחוֹד</a> (fut.).—<span class=\"citation\">Targ. Deut. XXI, 19</span> <span dir=\"rtl\">יְאַ׳</span> = <span dir=\"rtl\">יַחֲדוּן</span> (Pa.; Var. <span dir=\"rtl\">יֶחֱדוּן</span> = <span dir=\"rtl\">יֶאֶח׳</span> Pe.). <span class=\"citation\">Targ. Am. III, 5</span>; a. fr.—<span class=\"citation\">Snh. 26ᵃ</span> bot., a. e. <span dir=\"rtl\">אחדיה לדשא</span> locked the door. <span class=\"citation\">Pes. 111ᵇ</span> <span dir=\"rtl\">ליה רוחא אחדא</span> a spirit (demon, disease) seizes him.—<i>Part. pass</i>. <a href=\"#\" data-headword=\"אֲחִיד\">אֲחִיד</a> a) <i>locked up</i>. <span class=\"citation\">Targ. Josh. VI, 1</span>; a. e.—b) (v. <span dir=\"rtl\">אָחוּז</span>, s. v. <a href=\"#\" data-headword=\"אָחַז\">אָחַז</a>) <i>holding</i>. <span class=\"citation\">Targ. Am. II, 15</span>; a. fr.—<i>Part. pass. Pa</i>. <span dir=\"rtl\">מְאַחַד</span> <i>locked up, hidden</i>. <span class=\"citation\">Targ. Job. XXVI, 9</span>. </div><div class=\"sense\"><b>2)</b> <i>to devote</i>, v. <a href=\"#\" data-headword=\"אֲחִיד\">אֲחִיד</a>.</div><div class=\"sense\"><b>Af. אוֹחַד</b> <div class=\"sense\"><i>to seize</i>. <span class=\"citation\">Targ. Ps. LXXIII, 23</span>.</div></div><div class=\"sense\"><b>Ithpa. אִתְאָחַד  אִתָּחַד</b> </div><div class=\"sense\"><b>Ithpe. אִתְאֲחִיד</b> <div class=\"sense\"><b>1)</b> <i>to be seized</i>. <span class=\"citation\">Targ. Ez. XIX, 4</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be locked up, joined</i>. <span class=\"citation\">Targ. Is. XXIV, 10</span> <span dir=\"rtl\">את אחידו …</span> (read <span dir=\"rtl\">אתאחידו</span>). <span class=\"citation\">Ib. LIX, 10</span> Rashi (ed. <span dir=\"rtl\">אתא חד</span> corr. acc.). <span class=\"citation\">Targ. Job XLI, 9</span> (<span class=\"citation\">8</span>); a. e.—<span dir=\"rtl\">אִתְּחִיד</span>. <span class=\"citation\">Ḥull. 52ᵇ</span> <span dir=\"rtl\">א׳ דשא</span> the door was locked.</div></div>","alt":[]},"997":{"h":"אַחֲדָא","r":"A00997","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אֲחַד\">foreg.</a>) </div><div class=\"sense\"><b>1)</b> <i>bolt</i>. <span class=\"citation\">Targ. Prov. XVIII, 19</span> (read … <span dir=\"rtl\">היך א׳ ד</span>).</div><div class=\"sense\"><b>—2)</b> <i>shutting up</i>. <span dir=\"rtl\">אֵחֲדַת רחמי</span> shutting up of the womb, barrenness. Ibid. XXX, 16.</div>","alt":[]},"998":{"h":"אֲחַדְבֹּוי","r":"A00998","html":"<div class=\"sense\"> (contr. of <span dir=\"rtl\">אח־דאבא</span>; v. <a href=\"#\" data-headword=\"אַחֲבָא\">אחבא</a>) pr. n. m. <i>Aḥadboy</i>, an Amora. <span class=\"citation\">Ḥull. 113ᵇ</span>; a. e.</div>","alt":[]},"999":{"h":"אָחָה","r":"A00999","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אחי\">אחי</a></div>","alt":[]},"1000":{"h":"אַחְוָא","r":"A01000","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= b. h. <span dir=\"rtl\">אָחוּ</span>, v. Ges. H. Dict. s. v.) [green], <i>meadow-grass, reed</i>. <span class=\"citation\">Targ. O. Gen. XLI, 2</span>.</div>","alt":["אַחְוָה"]},"1001":{"h":"אֲחוּדְתָּא","r":"A01001","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֲחַד\">אֲחַד</a>) = <a href=\"#\" data-headword=\"אֲחוּזְתָּא\">אֲחוּזְתָּא</a> <i>possession</i>. <span class=\"citation\">Targ. O. Num. XXVII, 7</span>; a. e.</div>","alt":[]},"1002":{"h":"אַחֲוָה","r":"A01002","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>brotherhood, brotherly love, friendship</i>. <span class=\"citation\">Snh. 58ᵇ</span> <span dir=\"rtl\">בא׳</span> among brothers and sisters. <span class=\"citation\">Gen. R. s. 89</span> (play on <i>aḥu</i>, <span class=\"citation\">Gen. XLI</span>, </div><div class=\"sense\"><b>2)</b>  in days of plenty there is <span dir=\"rtl\">אהבה וא׳</span> love and friendship.—<span class=\"citation\">Lev. R. s. 2</span>; a. fr.—Trnsf. <span dir=\"rtl\">בא׳</span> <i>jointly</i>. <span class=\"citation\">Sabb. 20ᵃ</span> (explain. <a href=\"#\" data-headword=\"אָח I\">אָח</a> <span class=\"citation\">Jer. XXXVI, 23</span>) <span dir=\"rtl\">עצים שנדלקין בא׳</span> Ar., Ms. Oxf. (v. Rabb. D. S. a. l. note, ed. <span dir=\"rtl\">באחוונא</span> cler. error) wood kindled all together [perh. with <i>reeds?</i> v. next w.].—2) (law) <i>status of consanguinity</i>. <span class=\"citation\">B. Kam. 88ᵃ</span> a slave <span dir=\"rtl\">שאין לו א׳</span> who has no legal status of consanguinity.</div>","alt":[]},"1003":{"h":"אַחְוָה","r":"A01003","html":"<div class=\"sense\"> ch., v. <a href=\"#\" data-headword=\"אַחְוָא\">אַחְוָא</a></div>","alt":[]},"1004":{"h":"אַחֲוָוא","r":"A01004","html":"<div class=\"sense\"> pr. n. m., v. <a href=\"#\" data-headword=\"אַהֲבָה II\"><span dir=\"rtl\">אַהֲבָה</span> II</a></div>","alt":[]},"1005":{"h":"אחווינא","r":"A01005","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַחְוָונָא\">אַחְוָונָא</a></div>","alt":[]},"1006":{"h":"אַחְוַויְתָא","r":"A01006","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַחֲוֵיתָא\">אַחְוֵיתָא</a></div>","alt":[]},"1007":{"h":"אַחְוָונָא","r":"A01007","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אַחְוָא\">אַחְוָא</a>) </div><div class=\"sense\"><b>1)</b> <i>meadow-grass, grass</i> (as fodder). <span class=\"citation\">Y. Ber. VI, 10ᵃ</span>, bot.</div><div class=\"sense\"><b>—2)</b> <i>willow-twigs</i> used for kindling, <i>kindling wood</i>. <span class=\"citation\">Sabb. 20ᵃ</span> (explain. <a href=\"#\" data-headword=\"אָח I\">אָח</a> <span class=\"citation\">Jer. XXXVI, 23</span>; v. <a href=\"#\" data-headword=\"אַחֲוָה\">אַחֲוָה</a> 1, end) <a href=\"#\" data-headword=\"אַחְוָונָא\">אַחְוָונָא</a> (Var. <a href=\"#\" data-headword=\"אַחְוָנָא\">אַחְוָנָא</a>) willow-fire. Ib. one cried <span dir=\"rtl\">מאן בעי א׳ וכ׳</span> who wants <i>Aḥvana</i>?, and it was found he had willow twigs for sale.</div><div class=\"sense\"><b>—3)</b> <i>willow-bast</i>. Ib. 20ᵇ explaining <a href=\"#\" data-headword=\"*אִידָּן\">אִידָּן</a>; Ms. M. (ed. <span dir=\"rtl\">אחוינא</span>, <a href=\"#\" data-headword=\"אחווינא\">אחווינא</a>).</div>","alt":[]},"1008":{"h":"אֲחוּזָה","r":"A01008","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>possession, inheritance</i>. <span class=\"citation\">Y. Kidd. I 60ᶜ</span> top; a. e. <span class=\"citation\">Y. Ḥall. IV, 60ᵇ</span>. [<span class=\"citation\">Ib.</span> <span dir=\"rtl\">אחיזה עצמה וכ׳</span> strike out the entire sentence.]. <span class=\"citation\">Ḥull. 75ᵃ</span> <span dir=\"rtl\">אחוזת עינים</span>, v. <span dir=\"rtl\">אֲחִיזָה</span>.</div>","alt":[]},"1009":{"h":"אֲחוּזְתָּא","r":"A01009","html":"<div class=\"sense\"><span class=\"citation\">Targ. Ps. II, 8</span> Ms. (ed. <a href=\"#\" data-headword=\"אֲחוּדְתָּא\">אחודתא</a>).</div>","alt":[]},"1010":{"h":"אַחֲוָיָה","r":"A01010","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חוי\">חוי</a>) <i>telling, interpretation.</i> <span class=\"citation\">Dan. V, 12</span>.</div>","alt":[]},"1011":{"h":"אַחֲוֵיתָא","r":"A01011","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אַחֲוָיָה\">foreg.</a>) <i>instruction</i>. <span class=\"citation\">Targ. Ps. XLIX, 5</span>; a. fr.</div>","alt":["אַחֲוַויְתָא"]},"1012":{"h":"אֲחוּכֵי","r":"A01012","html":"<div class=\"sense\"> inf. of <span dir=\"rtl\">אֲחוּךְ</span>, v. <a href=\"#\" data-headword=\"חוּךְ I\">חוּךְ</a> a. <a href=\"#\" data-headword=\"אֲחִיךְ\"><a href=\"#\" data-headword=\"אֲחִיךְ\">אֲחִיךְ</a>.</a></div>","alt":[]},"1013":{"h":"אחום","r":"A01013","html":"<div class=\"sense\">, v. <span dir=\"rtl\">(<a href=\"#\" data-headword=\"בְּקִיעִין\">כפר</a>) <a href=\"#\" data-headword=\"אַחִים\">אַחִים</a></span>.</div>","alt":[]},"1014":{"h":"אַחְוָנָא","r":"A01014","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַחְוָונָא\">אַחְוָונָא</a></div>","alt":[]},"1015":{"h":"אַחְוָנַיָּיא","r":"A01015","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (Syr. <span dir=\"rtl\">חחוניתא</span>, v. <a href=\"#\" data-headword=\"חוֹחָא\">חוֹחָא</a>, a. Löw Aram. Pfl. p. 149) <i>plums</i>. <span class=\"citation\">Y. Ber. VI, 10ᵇ</span> bot. (Bab. <span class=\"citation\">ib. 39ᵃ</span> <a href=\"#\" data-headword=\"דורמסקין\">דורמסקין</a>).</div>","alt":[]},"1016":{"h":"אַחְוָנַיְתָא","r":"A01016","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אַחְוָנַיָּיא\">foreg.</a>) <i>a dish of plums</i>. <span class=\"citation\">Y. Ber. VI, 10ᶜ</span> top.</div>","alt":["אַחְוָנַיְיתָא"]},"1017":{"h":"אָחוֹר","r":"A01017","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <span dir=\"rtl\">חור</span> a. </div><div class=\"sense\"><b>1)</b> <i>back, hind-part, buttock</i>. <span class=\"citation\">Bekh. 8ᵃ</span>; <span class=\"citation\">Gen. R. s. 20</span>, beg.—Du. <span dir=\"rtl\">אֲחוֹרַיִים</span> (Ar. <span dir=\"rtl\">אחורים</span>). <span class=\"citation\">Pes. 17ᵇ</span>, a. fr. <span dir=\"rtl\">א׳ ותוך</span> the back (outside) and the inside of a vessel.—<span class=\"citation\">Y. Yoma V, 42ᶜ</span> top <span dir=\"rtl\">אֲחוֹרָיו לקדש</span> his back turned to the sanctuary.—<span class=\"citation\">Y. Pes. VI, 33ᵃ</span> bot., a. fr. <span dir=\"rtl\">מֵאֲחוֹרֵי</span> (prepos.) <i>behind</i>.—<a href=\"#\" data-headword=\"אֲחוֹרִי\">אֲחוֹרֵי</a>, <span dir=\"rtl\">לַאֲחוֹרֵי</span> same. <span class=\"citation\">Ber. 61ᵃ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>last</i>. Ib. (ref. to <span class=\"citation\">Ps. CXXXIX, 5</span>) <span dir=\"rtl\">א׳ למעשה וכ׳</span> the last of all things created; <span class=\"citation\">Lev. R. s. 14</span> <span dir=\"rtl\">א׳ לכל המעשים</span>.</div><div class=\"sense\"><b>—3)</b> <i>farthest back, earliest</i>. Ib. <span dir=\"rtl\">א׳ זה יום ראשון</span> <i>aḥor</i> (Ps. l. c.) means the first day.</div>","alt":[]},"1018":{"h":"אֲחוֹרָא","r":"A01018","html":"<div class=\"sense\"> לאחורא <i>backward</i>. <span class=\"citation\">Targ. Gen. XLIX, 17</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"אֲחוֹרִי\">אֲחוֹרִין</a>, const. <a href=\"#\" data-headword=\"אֲחוֹרִי\">אֲחוֹרֵי</a>. <span class=\"citation\">Targ. Ps. LXXVIII, 66</span> (buttocks).—אֲחוֹרֵי <i>behind, after</i>. <span class=\"citation\">Y. R. Hash. II, 58ᵇ</span> top <span dir=\"rtl\">מן אחוֹרוֹיי</span> behind him; a. fr. V. <a href=\"#\" data-headword=\"חוֹרֵי\">חוֹרֵי</a>. [<span class=\"citation\">Targ. Y. Lev. XIX, 26</span>, v. <a href=\"#\" data-headword=\"חָרוֹרָא\">חָרוֹרָא</a>.]</div>","alt":["(אַחְרָא)"]},"1019":{"h":"אֲחוֹרִי","r":"A01019","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= h. <a href=\"#\" data-headword=\"אֲחֶרֶת\">אֲחֶרֶת</a>) <i>another, something else</i>. <span class=\"citation\">Y. Shebu. IV, 35ᵈ</span> top <span dir=\"rtl\">איתא או׳</span> another woman (wife). <span class=\"citation\">Y. Ber. IX, 13ᵃ</span> bot. <span dir=\"rtl\">שיטה או׳</span> another method, <span class=\"citation\">Lev. R. s. 14</span>, beg. <span dir=\"rtl\">אמר או׳</span> said differently. Y. Meg. II, 74ᵃ top <span dir=\"rtl\">אחו׳</span> another (scroll). <span class=\"citation\">Gen. R. s. 76</span> <span dir=\"rtl\">אחו׳</span> another (word, in reply). [Targ. <a href=\"#\" data-headword=\"אוֹחֲרִי\">אוֹחֲרִי</a>. <span class=\"citation\">Targ. Gen. XXVI, 21</span>; a. fr.]—[<span class=\"citation\">Dan. II, 39</span>; <span class=\"citation\">VII, 5</span>; <span class=\"citation\">6</span>; <a href=\"#\" data-headword=\"אָחֳרִי\">אָחֳרִי</a>.] V. <a href=\"#\" data-headword=\"חוֹרִי I\">חוֹרִי</a>.</div>","alt":["אוֹחֲרִי"]},"1020":{"h":"אָחוֹת","r":"A01020","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"אָח I\"><span dir=\"rtl\">אָח</span> I</a>) <i>sister</i>. <span class=\"citation\">Yeb. I, 1</span>; a. fr.—<span class=\"citation\">Ḥull. 114ᵃ</span> (of animals).—Pl. <a href=\"#\" data-headword=\"אַחֲיוֹת\">אַחֲיוֹת</a>. <span class=\"citation\">Yeb. III, 1</span>; a. e.</div>","alt":[]},"1021":{"h":"אָחַז","r":"A01021","html":"<div class=\"sense\"><b>1)</b> <i>to press, seize, hold, keep; to befall</i>. <span class=\"citation\">Snh. 27ᵇ</span> <span dir=\"rtl\">אוֹחֲזִין מעשה וכ׳</span> holding in their hands the doing of their fathers, i.e. following their father’s example. <span class=\"citation\">Bekh. 33ᵇ</span> <span dir=\"rtl\">אֲחָזוֹ דם</span> he had an attack of congestion. <span class=\"citation\">Y. Pes. I, 28ᵇ</span> <span dir=\"rtl\">אֲחוּזַת הדם</span> the animal attacked with congestion. <span class=\"citation\">Y. Sabb. XIV, 14ᶜ</span> bot. <span dir=\"rtl\">אֲחָזַתֹּו עין</span> a pain in the eye seized him. Ib. XIX, end, 17ᵇ <span dir=\"rtl\">אחזתו חמה</span> fever overtook him; a. fr.—אָחַז בְּ־ <i>to have a hold of</i>.—<span class=\"citation\">B. Mets. I, 1</span>. Y. Yoma II, 39ᶜ top; a. fr.—Part. pass. <span dir=\"rtl\">אָחוּז</span> <i>holding fast, having a firm hold</i>. <span class=\"citation\">Ex. R. s. 46</span> (v. <a href=\"#\" data-headword=\"אֲחַד\">אֲחַד</a>).</div><div class=\"sense\"><b>—2)</b>  א׳ את העינים <i>to capture the eyesight, to delude by optical deception</i>. <span class=\"citation\">Snh. 65ᵇ</span>; a. e.</div><div class=\"sense\"><b>Nif. נֶאֱחַז</b> <div class=\"sense\"><i>to be seized</i>. Y. Taan. II, 65ᵈ top; a. e.</div></div><div class=\"sense\"><b>*Nif. הֶאֱחִיז</b> <div class=\"sense\"><i>to distribute split wood</i> (<i>kindling chips</i>) <i>in the gaps of a large pile, to ignite with kindling wood</i>. <span class=\"citation\">Sabb. I, 11</span> (<span class=\"citation\">19ᵇ</span> sq.) <span dir=\"rtl\">ומַאֲחִיזִין</span> ed. (Mss., Ar. a. Y. ib. beg. 4ᶜ <span dir=\"rtl\">ומחזין</span>, ed. Ven. <span dir=\"rtl\">ומחיזין</span>); v. <a href=\"#\" data-headword=\"חזי\">חָזָה</a>.</div></div>","alt":[]},"1022":{"h":"אחזיונה","r":"A01022","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"חִזָּיוֹן I\">חִזָּיוֹן</a> 2).</div>","alt":[]},"1023":{"h":"אחי","r":"A01023","html":"<div class=\"sense\"> (√<a href=\"#\" data-headword=\"חוּ\">חו</a>, cmp. <a href=\"#\" data-headword=\"חָבַב I\">חבב</a>) <i>to unite</i>. Part. pass. <a href=\"#\" data-headword=\"חוי ²\">אָחוּי</a> <i>united</i>. <span class=\"citation\">Num. R. s. 13</span>, beg. <span dir=\"rtl\">שיהיו אֲחוּיִים אצלו</span> they shall be united with him (around his table).</div><div class=\"sense\"><b>Pi. אִיחָה</b> <div class=\"sense\"><i>to join; to sew together</i> (with fine stitches); cmp. <a href=\"#\" data-headword=\"חוּט\">חוּט</a>; <span dir=\"rtl\">חוּד I</span>. <span class=\"citation\">Gen. R. s. 39</span> beg. <span dir=\"rtl\">אברהם שאֹ׳ את וכ׳</span> Abraham who united all mankind into a brotherhood (by the belief in one God), <span dir=\"rtl\">כזה שהוא מְאָחֶה וכ׳</span> like one who sews &amp;c., v. infra. <span class=\"citation\">Ex. R. s. 40</span>, end.—Esp. <i>to mend, by stitching, the rent of the garment torn in mourning</i>. <span class=\"citation\">M. Kat. 22ᵇ</span>; a. fr. <span class=\"citation\">Ib. 26ᵃ</span> <span dir=\"rtl\">לאַחוֹתָן</span> to stitch them together.</div></div><div class=\"sense\"><b>Hithpa. a. Nithpa. הִתְאָחֶה  נִתְאָחֶה</b> <div class=\"sense\"><b>1)</b> <i>to be joined; to be stitched together</i>. <span class=\"citation\">Num. R. s. 13</span>, beg. (play on <span dir=\"rtl\">אחותי</span> <span class=\"citation\">Cant. V, 1</span>) <span dir=\"rtl\">נִתְאָחוּ לי וכ׳</span> they were joined to me (I joined them) in the captivity. <span class=\"citation\">Gen. R. s. 68</span> <span dir=\"rtl\">מִתְאָחוֹת</span>, v. <a href=\"#\" data-headword=\"אֶבֶן\">אֶבֶן</a>. <span class=\"citation\">M. Kat. 26ᵃ</span> <span dir=\"rtl\">אין מתאחין</span> must not be stitched together.</div><div class=\"sense\"><b>—2)</b> <i>to be joined by grafting, to grow together</i>. Y. Kil. I, 27ᵃ top <span dir=\"rtl\">הן נתא׳ וכ׳</span> they (the two seeds) combine. Y. Shebi. II, end, 34ᵃ bot. Y. Orl. I, 61ᵃ bot.</div></div>","alt":["אָחָה"]},"1024":{"h":"אחי ²","r":"A01024","html":"<div class=\"sense\"><i>Pa</i>. <a href=\"#\" data-headword=\"חֲיִי\">אַחֵי</a> as <a href=\"#\" data-headword=\"אחי\">foreg.</a> <i>Pi</i>. <span class=\"citation\">Targ. Koh. III, 7</span> <span dir=\"rtl\">לאחאה</span> to sew together.</div>","alt":[]},"1025":{"h":"אֲחִיד","r":"A01025","html":"<div class=\"sense\"><b>1)</b>  part. pass. of part. pass. of <a href=\"#\" data-headword=\"אֲחַד\">אֲחַד</a> q. v.</div><div class=\"sense\"><b>—2)</b>  (= h. <span dir=\"rtl\">מְיוּחָד</span>, v. <span dir=\"rtl\">יחד</span>) <i>singled out, devoted, betrothed</i>. <span class=\"citation\">Targ. O. Lev. XIX, 20</span>. <span class=\"citation\">Targ. Ps. CXIV, 2</span>. <span class=\"citation\">Targ. Cant. VI, 9</span>.</div>","alt":[]},"1026":{"h":"אֲחִידָה I","r":"A01026","html":"<div class=\"sense\"> (<span dir=\"rtl\">אחד</span>) <i>taking possession, capture</i>. <span class=\"citation\">Meg. 6ᵃ</span> היו קורין אותו אֲחִידַת מגדל צור Ms. (ed. <a href=\"#\" data-headword=\"שִׁיר I\">שיר</a>, Ar. <span dir=\"rtl\">שד</span>) they recorded the act (of taking the place afterwards called Cæsarea) as the capture of Migdal Tsor.</div>","alt":[]},"1027":{"h":"אֲחִידָה II","r":"A01027","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>enigma.</i> <i>—</i> Pl. <span dir=\"rtl\">אֲחִידָן</span> <span class=\"citation\">Dan. V, 12</span>.</div>","alt":[]},"1028":{"h":"אֲחִיָּה","r":"A01028","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Aḥiyah</i>, several men of various periods., several men of various periods. </div><div class=\"sense\"><b>1)</b>  <span class=\"citation\">Shek. V, 1</span> א׳ על הנסכים A. superintendent of the Temple libations (wines, oils).</div><div class=\"sense\"><b>—2)</b>  <span class=\"citation\">Ber. 63ᵇ</span> A., a Babylonian scholar opposing Palestine authorities.</div><div class=\"sense\"><b>—3)</b>  רבי אחייה R. A., a Tannai. <span class=\"citation\">M. Kat. 20ᵃ</span>; a. e. <span class=\"citation\">Ibid. 20ᵇ</span> ר׳ חייא לחוד וכ׳ R. Ḥiya (although a Chald. abbreviation of Aḥiyah) and R. A. are two different persons.</div>","alt":[]},"1029":{"h":"אַחֲיוֹת","r":"A01029","html":"<div class=\"sense\"> pl. of <a href=\"#\" data-headword=\"אָחוֹת\">אָחוֹת</a>.</div>","alt":[]},"1030":{"h":"אַחֲיוּתָא","r":"A01030","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חיי\">חיי</a>) <i>reanimation, resurrection</i>. <span class=\"citation\">Targ. Hos. VI, 2</span> … <a href=\"#\" data-headword=\"אַחֲיוֹת\">אַחֲיוּת</a> resurrection of &amp;c.; a. e.</div>","alt":[]},"1031":{"h":"אַחַיי","r":"A01031","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Aḥai</i> (v. <a href=\"#\" data-headword=\"אַחַאי\">אַחַאי</a>). <span class=\"citation\">Kidd. 22ᵇ</span></div>","alt":[]},"1032":{"h":"אֲחִיָּיה","r":"A01032","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲחִיָּה\">אֲחִיָּה</a></div>","alt":[]},"1033":{"h":"אֲחִיךְ","r":"A01033","html":"<div class=\"sense\"><i>to laugh</i>, v. <a href=\"#\" data-headword=\"חוּךְ I\">חוּךְ</a>.</div>","alt":[]},"1034":{"h":"אֲחִילוּ","r":"A01034","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חִיל\">חִיל</a>) <i>chills and fever, trembling</i>. <span class=\"citation\">Git. 70ᵃ</span> (explained, as ‘fire of the bones’). <span class=\"citation\">Ber. 32ᵃ</span> (play on <span dir=\"rtl\">ויחל</span> <span class=\"citation\">Ex. XXXII, 11</span>). [Ib. 12ᵇ אחילו Af. of <a href=\"#\" data-headword=\"חוּל II\"><span dir=\"rtl\">חוּל</span> II</a>.]</div>","alt":[]},"1035":{"h":"אַחִים","r":"A01035","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>K’far Aḥim</i>. <span class=\"citation\">Men. 85ᵃ</span>. <span class=\"citation\">Tosef. ib. IX, 2</span> <a href=\"#\" data-headword=\"אחום\">אחום</a>.</div>","alt":["כְּפַר א׳"]},"1036":{"h":"אֲחִינִית","r":"A01036","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, pl. <span dir=\"rtl\">אֲחִינִיֹּות</span> (prob. to be read <span dir=\"rtl\">אַחְוָנִיֹּות</span>, v. <a href=\"#\" data-headword=\"אַחְוָנַיָּיא\">אַחְוָנַיָּיא</a>) <i>plums</i>. <span class=\"citation\">Y. Dem. II, 22ᵈ</span> top.</div>","alt":[]},"1037":{"h":"*אֲחִלָּה","r":"A01037","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חָלַל\">חלל</a>) <i>defilement</i> of a priest’s daughter, v. <a href=\"#\" data-headword=\"חֲלָלָה\">חֲלָלָה</a>. <span class=\"citation\">Snh. 66ᵇ</span> <span dir=\"rtl\">אם תחלת אֲחִלָּתָהּ וכ׳</span> if her first defilement occurred in whoredom (not in wedlock with one degraded).</div>","alt":[]},"1038":{"h":"*אַחְמִיתָא","r":"A01038","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (cmp. h. <a href=\"#\" data-headword=\"חֵמֶת\">חֵמֶת</a>) <i>pot, closed vessel.</i> Pl. <span dir=\"rtl\">אַחְמִיתִין</span>. <span class=\"citation\">Targ. Esth. I, 4</span>.</div>","alt":[]},"1039":{"h":"אַחְמַר","r":"A01039","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">חמר</span>) <i>ruby</i>, name of a jewel in the High-priest’s breast-plate. <span class=\"citation\">Targ. Cant. V, 14</span>; v. <a href=\"#\" data-headword=\"סָמְקָן\">סַמְקָן</a>.</div>","alt":[]},"1040":{"h":"אַחְמְרָא","r":"A01040","html":"<div class=\"sense\"> m., Ar., v. <a href=\"#\" data-headword=\"חוּמְרָא III\"><span dir=\"rtl\">חוּמְרָא</span> III</a></div>","alt":["אהמרא"]},"1041":{"h":"אַחְמְתָא","r":"A01041","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Aḥm’tha, Ecbatana</i>, capital of Media. <span class=\"citation\">Ezra VI, 2</span>, v. <a href=\"#\" data-headword=\"הַמְדָּן\">הַמְדָּן</a>; v. Schr. K. A. T. p. 378.</div>","alt":[]},"1042":{"h":"אח\"ס","r":"A01042","html":"<div class=\"sense\">, <span dir=\"rtl\">אח&quot;ס בט&quot;ע</span>, a formula representing a permutation of letters wherein the first (<a href=\"#\" data-headword=\"א\">א</a>) interchanges with the eighth (<a href=\"#\" data-headword=\"ח\">ח</a>) and with the fifteenth <a href=\"#\" data-headword=\"ס\">(ס</a>); the second (<a href=\"#\" data-headword=\"ב\">ב</a>) with the ninth (<a href=\"#\" data-headword=\"ט\">ט</a>) and with the sixteenth <a href=\"#\" data-headword=\"ע\">(ע</a>), &amp;c. <span class=\"citation\">Sabb. 104ᵃ</span> <span dir=\"rtl\">אח&quot;ס בט&quot;ע גי&quot;ף</span> = <span dir=\"rtl\">א̇ני ח̇ס̇ עליהם מפני שב̇ע̇ט̇ו בג̇י̇ף̇</span> I shall spare them because they resisted sensual temptations; v. <a href=\"#\" data-headword=\"*גִּיף\">גִּיף</a></div>","alt":[]},"1043":{"h":"אַחְסָנָא","r":"A01043","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"חֹסֶן\">חסן</a>) <i>property, inheritance</i>. <span class=\"citation\">Targ. Lev. XIV, 34</span>; a. e.—<span class=\"citation\">B. Bath. 133ᵇ</span> <span dir=\"rtl\">עבורי א׳</span> who unlawfully pass an inheritance from one hand to another.</div>","alt":["אַחְסַנְתָּא"]},"1044":{"h":"אָחַר","r":"A01044","html":"<div class=\"sense\"><b>1)</b> <i>to be behind</i>, v. <i>Pi</i>.</div><div class=\"sense\"><b>—2)</b>  (euphem.) <i>to cover</i> (of camels). <span class=\"citation\">B. Bath. 93ᵃ</span>; <span class=\"citation\">Shebu. 34ᵃ</span>; <span class=\"citation\">Snh. 37ᵇ</span> (Ms. M. B. Bath. l. c. <a href=\"#\" data-headword=\"יָהִיר\">יהיר</a>). <span class=\"citation\">Tosef. B. Kam. III, 6</span> <span dir=\"rtl\">אוֹחֵיר</span>.</div><div class=\"sense\"><b>Pi. אֵחַר  אֵיחַר</b> <div class=\"sense\"><i>to tarry, hesitate; to set behind</i>. <span class=\"citation\">Pes. IX, 9</span> <span dir=\"rtl\">אם אֵחַרְתִּי</span> if I should be late. Y. Yoma III, 40ᶜ top <span dir=\"rtl\">א׳ בו מעשה</span> the text orders a later action after it. Y. Ned. X, 42ᵃ; 42ᵇ <span dir=\"rtl\">א׳ בעמידה</span> he tarried in standing, i.e. was the last to sit down. <span class=\"citation\">Gen. R. s. 81</span>, beg. <span dir=\"rtl\">א׳ אדם את נדרו</span> if one procrastinates the fulfillment of his vow; a. fr.</div></div><div class=\"sense\"><b>Pu. אוּחָר  הוּאֲחָר</b> <div class=\"sense\"><i>to be postponed, be done late, be placed later</i>. Y. Yoma III, 40ᶜ top <span dir=\"rtl\">בכלל מְאוּחָר היה</span> would belong to things to be done later. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">יוּאֲחַר וכ׳</span> let it be done later than &amp;c.—<span dir=\"rtl\">אין מוקדם ומאוחר בתורה</span> there is no ‘earlier’ or ‘later’ (no chronological order) in the events or laws of the Scripture. <span class=\"citation\">Pes. 6ᵇ</span>; a. e.; Y. Sot. VIII, 22ᵈ <span dir=\"rtl\">מוּאֲחַר</span>.—<span class=\"citation\">Shebi. X, 5</span>, a. fr. <span dir=\"rtl\">מאוחר</span> (a document) <i>postdated</i>, opp. <span dir=\"rtl\">מוקדם</span> antedated. <span class=\"citation\">B. Mets. V, 10</span> <span dir=\"rtl\">רבית מְאוּחֶרֶת</span> postpaid interests.</div></div>","alt":[]},"1045":{"h":"אֲחַר","r":"A01045","html":"<div class=\"sense\"><b>1)</b> <i>to be behind</i>. </div><div class=\"sense\"><b>2)</b>  *<i>to cover</i>. <span class=\"citation\">Targ. Jer. V, 8</span> (of steeds, h. text <span dir=\"rtl\">מוזנים</span>; some ed. <a href=\"#\" data-headword=\"ד\">ד</a> for. <a href=\"#\" data-headword=\"ר\">ר</a>).</div><div class=\"sense\"><b>Pa. אחרוה</b> <div class=\"sense\"> take ye a later meal (on Sabbaths).</div></div><div class=\"sense\"><b>Af. אוֹחַר</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"אָחַר\">same</a>. <span class=\"citation\">Targ. II Sam. XX, 5</span>; a. fr.—[<span class=\"citation\">Targ. Prov. XXIII, 30</span> <span dir=\"rtl\">מַוְחֲרִין</span>, <span dir=\"rtl\">מְוַוחֲרִין</span> Part. Af. or Pa. of <span dir=\"rtl\">יחר</span> = <span dir=\"rtl\">מוֹחר׳</span>, <span dir=\"rtl\">מאחר׳</span>.]</div></div><div class=\"sense\"><b>*Ithpe. אִתְאֲחַר</b> <div class=\"sense\">, contr. <a href=\"#\" data-headword=\"חֲרַר ³\">אִתְחַר</a> to <i>be delayed</i>. <span class=\"citation\">Targ. Y. I Deut. I, 2</span>; cmp. however ib. v. 6, v. <a href=\"#\" data-headword=\"אֲרַח\">אֲרַח</a>.</div></div>","alt":[]},"1046":{"h":"אַחַר","r":"A01046","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֲחַר\">foreg.</a>), pl. constr. <a href=\"#\" data-headword=\"אָחֳרִי\">אַחֲרֵי</a> <i>after, behind</i>. <span class=\"citation\">Gen. R. s. 44</span> wherever the Bible uses the preposition <i>aḥaré</i> <a href=\"#\" data-headword=\"סָמוּךְ\">סמוך</a>, it means <i>in connection with</i>, <span dir=\"rtl\">אחר מופלג</span> while <i>aḥar</i> means without connection (<i>later on</i>). <span class=\"citation\">Yoma 6ᵃ</span> <span dir=\"rtl\">אחר א׳</span> after ‘after’, i.e. some time after the act, opp. <span dir=\"rtl\">חד אחר</span> one ‘after’, immediately, v. <a href=\"#\" data-headword=\"אֶוְותִּיאוֹס\">אֶוְתִּיוֹס</a>.—<span dir=\"rtl\">לְאַחֲרָיו</span>, <span dir=\"rtl\">לְאַחֲרֶיהָ</span>, <span dir=\"rtl\">מֵאַחֲרָיו</span>, <span dir=\"rtl\">מֵאַחֲרֶיהָ</span> after it, as concluding, opp. <span dir=\"rtl\">לפניה</span>, <span dir=\"rtl\">לפניו</span> introductory (prayer).—<span class=\"citation\">Ber. I, 4</span> <span dir=\"rtl\">אחת לא׳</span> one benediction after the Sh’ma. <span class=\"citation\">Ib. III, 4</span> <span dir=\"rtl\">לאחריו</span> (prayer) after meal; a. fr.—<span dir=\"rtl\">כִּלְאַחַר יד</span> as if doing a thing with the back of the hand, i.e. in a manner different from the usual way of doing it. <span class=\"citation\">Sabb. 153ᵇ</span>; a. fr.—<span dir=\"rtl\">מֵאַחַר</span> </div><div class=\"sense\"><b>1)</b>  (conj. followed by <span dir=\"rtl\">ש־</span> or <span dir=\"rtl\">ד־</span>) <i>after, since, whereas, because</i>. <span class=\"citation\">Ḥull. 29ᵃ</span> <span dir=\"rtl\">מא׳ ששנינו</span> after it has once been stated in the Mishnah … why was it necessary (?) &amp;c. <span class=\"citation\">Ib.ᵇ</span> <span dir=\"rtl\">ומאחר דאפי׳ וכ׳</span> and since it is not even rabbinically unfit, why &amp;c.; a. fr.</div><div class=\"sense\"><b>—2)</b>  a legal term, <i>meaḥar</i>, the presumption of the truth of one’s statement, <i>because</i> he might have pleaded more profitably, if he had been inclined to lie. <span class=\"citation\">Y. Shebu. VI, 36ᵈ</span> bot. <span dir=\"rtl\">אין אומרים בממון מא׳ מאחר וכ׳</span> in money matters we do not apply the principle of <i>meaḥer</i>, so as to say that because he might have said ‘thou hast not lent me anything’, he may say, ‘thou didst lend me, but I paid half of it’ (and his plea must be accepted without an oath); v. <a href=\"#\" data-headword=\"מִיגּוֹ\">מִיגּוֹ</a> s. v. <a href=\"#\" data-headword=\"גֵּו ²\">גּוֹ</a>.—אַחֲרֶיךָ <i>thy successor</i>. <span class=\"citation\">Y. Kil. IX, 32ᶜ</span> top <span dir=\"rtl\">יהודה בני א׳ וכ׳</span> my son Judah shall succeed thee, none else (is worthy). <span class=\"citation\">Keth. 95ᵇ</span> my property I bequeath to thee <span dir=\"rtl\">ואַחֲרַיִיךְ לפ׳</span> and after thee it shall go over to …—<span dir=\"rtl\">אַחַר כָּךְ</span> (abbrev. <span dir=\"rtl\">אח&quot;כ</span>) <i>afterwards, subsequently</i>. <span class=\"citation\">Pes. X, 2</span>; a. v. fr.</div>","alt":[]},"1047":{"h":"אַחֵר","r":"A01047","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"אַחַר\">foreg.</a> a.  [back of,] <i>another, the other, stranger</i>. <span dir=\"rtl\">דבר א׳</span> (abbr. <span dir=\"rtl\">ד&quot;א</span>) </div><div class=\"sense\"><b>1)</b> <i>another thing, another explanation</i>. <span class=\"citation\">Snh. IV, 5</span>; a. v. fr. in Midr.</div><div class=\"sense\"><b>—2)</b>  euphem. for <i>idolatry, swine</i> &amp;c., v. <a href=\"#\" data-headword=\"דָּבָר\">דָּבָר</a>. </div><div class=\"sense\"><b>3)</b> <i>Aḥer</i>, [apostate,] byname of Elisha ben Abuyah. <span class=\"citation\">Ḥag. 14ᵇ</span>; a. e.—Pl. <a href=\"#\" data-headword=\"חֲרַם\">אֲחֵרִים</a> <i>others</i>; 1) freq. in Mishn. for anonymous authorities differing in opinion, <span dir=\"rtl\">א׳ אומרים</span>, v. <span class=\"citation\">Hor. 13ᵇ</span> אסיקו לר׳ מאיר א׳ R. Meïr is quoted under the word <i>aḥerim</i>.—2) freq. for <i>strangers, gentiles</i>. <span class=\"citation\">Snh. 52ᵇ</span> <span dir=\"rtl\">אשת א׳</span> the wife of a non-Israelite. <span class=\"citation\">B. Mets. 111ᵇ</span>; a. fr.—Fem. <a href=\"#\" data-headword=\"אֲחֶרֶת\">אֲחֶרֶת</a>. <span class=\"citation\">Yoma I, 1</span> <span dir=\"rtl\">אשה א׳</span> a second (additional) wife; a. fr.—<span class=\"citation\">Snh. 104ᵃ</span> <span dir=\"rtl\">זאת ועוד א׳</span> this and something besides (shall happen).</div>","alt":[]},"1048":{"h":"אַחְרָא","r":"A01048","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֲחוֹרָא\">אֲחוֹרָא</a></div>","alt":["אֲחֹרָא"]},"1049":{"h":"אַחֲרָאִי","r":"A01049","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אַחְרָא\">foreg.</a> wds.) prop. <i>designated to step behind, substitute;</i> hence, <i>he who</i> (or <i>that which</i>) <i>is gone back to, obligated, pledged; surety, guarantor.</i> <i>—</i> Pl. <a href=\"#\" data-headword=\"אַחֲרָאִי\">אַחֲרָאִים</a>, <a href=\"#\" data-headword=\"אַחֲרָיִי\">אַחֲרָיִין</a>. <span class=\"citation\">Dem. III, 5</span> <span dir=\"rtl\">אין אנו א׳ וכ׳</span> we are not responsible for deceivers. <span class=\"citation\">Pes. IX, 9</span> <span dir=\"rtl\">אינן אחראין זה לזה</span> they are not responsible to one another (need not care for each other). <span class=\"citation\">Y. Keth. VIII, end, 32ᵇ</span>, a. fr. <span dir=\"rtl\">כל נכסיו א׳</span></div>","alt":["אַחֲרָיִי"]},"1050":{"h":"אַחֲרוֹן","r":"A01050","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, <span dir=\"rtl\">אַחֲרוֹנָה</span> f. (<a href=\"#\" data-headword=\"אַהֲרוֹנִית\">אַחֲרוֹנִית</a> f. noun) <i>other, next, last</i>. <span class=\"citation\">Meg. 21ᵇ</span>; a. fr. <a href=\"#\" data-headword=\"א׳\">א׳</a> the last of those called up to read from the Torah.—Pl. <span dir=\"rtl\">אַחֲרוֹנִים</span> m., <span dir=\"rtl\">אַחֲרוֹנוֹת</span> f.—<span dir=\"rtl\">מים א׳</span> the washing of hands after meals before grace, opp. <span dir=\"rtl\">מים ראשונים</span> washihg before meals. <span class=\"citation\">Ber. 53ᵇ</span>; a. fr.—<span dir=\"rtl\">דורות א׳</span> or only <span dir=\"rtl\">אחרונים</span> the latter (present) generation, opp. <span dir=\"rtl\">ראשונים</span> ancients. <span class=\"citation\">Yoma 9ᵇ</span>; a. fr.—<span class=\"citation\">Ber. 13ᵃ</span> <span dir=\"rtl\">צרות א׳ וכ׳</span> the latter (present) troubles bring the former into oblivion.—<span dir=\"rtl\">(<span dir=\"rtl\">ברכות</span>) <a href=\"#\" data-headword=\"א׳\">א׳</a></span> the three last sections in the Prayer of Benedictions. <span class=\"citation\">Ibid. 34ᵃ</span>; a. fr.—<span class=\"citation\">Erub. 53ᵇ</span> אַחְרוֹנִית <i>second wife;</i> v. <a href=\"#\" data-headword=\"אַהֲרוֹנִית\">אַהֲרוֹנִית</a>.—<span dir=\"rtl\">בָּאַחֲרוֹנָה</span> (adv.) <i>last</i>. <span class=\"citation\">B. Kam. 8ᵃ</span>; a. e.</div>","alt":[]},"1051":{"h":"אָחֳרִי","r":"A01051","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֲחוֹרִי\">אְחוֹרִי</a></div>","alt":[]},"1052":{"h":"אַחֲרָיוּת","r":"A01052","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אַחֲרָאִי\">אַחֲרָאִי</a>) <i>surety</i>, esp. <i>mortgaged property</i>, or <i>property which may be resorted to in case of non-payment</i> (even if sold).—<span dir=\"rtl\">נכסים שיש להן א׳</span> property from which debts may eventually be collected (landed property), <span dir=\"rtl\">נ׳ שאין להם א׳</span> property which cannot be resorted to (movable property). <span class=\"citation\">Kidd. I, 5</span>; a. fr.—<span class=\"citation\">B. Mets. III, 11</span> <span dir=\"rtl\">חייב באחריותן</span> is responsible for them (if lost). <span class=\"citation\">Men. 109ᵃ</span>; a. fr.—<span dir=\"rtl\">א׳ נכסים</span> an obligation for which property is pledged. <span class=\"citation\">Keth. 34ᵇ</span>; a. fr.—<span class=\"citation\">Ib. 51ᵇ</span>, a. e. documents <span dir=\"rtl\">שאין בהן א׳ נ׳</span> in which the clause pledging property is omitted. <span class=\"citation\">Ib. 51ᵃ</span>; a. e. <span dir=\"rtl\">א׳ טעות סופר הוא</span> the omission of the clause pledging property is considered as the scribe’s mistake (hence has no legal consequences). <span class=\"citation\">B. Mets. 14ᵃ</span>, a. e. <span dir=\"rtl\">ראובן שמכר … בא׳</span> if R. sold to S. a field with surety (guaranteeing the title).</div>","alt":[]},"1053":{"h":"אַחֲרָיוּתָא","r":"A01053","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= h. <a href=\"#\" data-headword=\"אַחֲרִית\">אַחֲרִית</a>) <i>future</i>. <span class=\"citation\">Targ. Y. II, Deut. XXXII, 29</span>; a. e.</div>","alt":[]},"1054":{"h":"אַחֲרָיִי","r":"A01054","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אַחֲרָאִי\">אַחֲרָאִי</a></div>","alt":[]},"1055":{"h":"אַחֲרָיָיא","r":"A01055","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>another, the other, later, last</i>. <span class=\"citation\">Y. Pes. I, end, 28ᵇ</span> <span dir=\"rtl\">ר׳ יושוע א׳</span> the other (last named) R. Josh.—<span class=\"citation\">Y. Ber. II, 5ᵇ</span> top <span dir=\"rtl\">פירקא א׳</span> last chapter.—Pl. <span dir=\"rtl\">אחְרָיִין</span>. <span class=\"citation\">Y. Ter. VIII, 45ᵈ</span> bot. <span dir=\"rtl\">א׳ ומיתון</span> those (drinking) later, drank and died.—<a href=\"#\" data-headword=\"אַחֲרָיָיא\">אַחְרַיָּיא</a>. <span class=\"citation\">Y. Meg. III, 74ᵇ</span> bot. <span dir=\"rtl\">תומנתי פסוקייא א׳</span> the last eight verses.—Fem. <a href=\"#\" data-headword=\"אַחֲרַיְתָא\">אַחֲרַיְתָא</a>, <a href=\"#\" data-headword=\"אַחֲרַיְתָא\">אַחֲרַיְיתָא</a>. Y. Taan. I, beg. 63ᶜ. Y. Shebu. III, 34ᵈ <span dir=\"rtl\">בא׳</span> in the last one.—<span class=\"citation\">Targ. Prov. V, 20</span> אחריתא <i>stranger</i>.—<span class=\"citation\">Ib. XXV, 8</span>, a. fr. <span dir=\"rtl\">בא׳</span> <i>at last, in the end.—</i> Pl. <a href=\"#\" data-headword=\"אַחֲרָיוּתָא\">אַחֲרָיָיתָא</a>. <span class=\"citation\">Ib. XXIV, 14</span> Ms. (ed. sing.).</div>","alt":[]},"1056":{"h":"אַחֲרִינָא","r":"A01056","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>another</i>. <span class=\"citation\">Ḥull. 12ᵃ</span> <span dir=\"rtl\">אינש א׳</span> another man. <span class=\"citation\">Bets. 28ᵃ</span> <span dir=\"rtl\">מידי א׳</span> something different.—<span dir=\"rtl\">לישנא א׳</span> (abbr. <span dir=\"rtl\">ל&quot;א</span>) another version. <span class=\"citation\">Pes. 97ᵇ</span>, a. fr.—Pl. <span dir=\"rtl\">אַחְרִינֵי</span>. <span class=\"citation\">Yeb. 45ᵃ</span>; a. fr. Cmp. <a href=\"#\" data-headword=\"אָחֳרָן\">אָחֳרָן</a>.</div>","alt":[]},"1057":{"h":"אַחֲרִית","r":"A01057","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <i>future, end</i>. <span class=\"citation\">Y. Meg. III, 74ᵃ</span> bot.</div>","alt":[]},"1058":{"h":"אַחֲרַיְתָא","r":"A01058","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אַחֲרַיְתָא\">אַחְרַיְיתָא</a> s. v. <a href=\"#\" data-headword=\"אַחֲרָיָיא\">אַחְרָיָיא</a>.</div>","alt":[]},"1059":{"h":"אַחֲרִיתִּי","r":"A01059","html":"<div class=\"sense\"><i>another, something besides</i>. <span class=\"citation\">Erub. 23ᵃ</span> <span dir=\"rtl\">מילתא א׳</span> another subject. <span class=\"citation\">Pes. 50ᵃ</span>; a. fr.</div>","alt":[]},"1060":{"h":"אָחֳרָן","r":"A01060","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <span class=\"citation\">Targ. Ex. XX, 3</span>; a. fr.—Fem. <a href=\"#\" data-headword=\"אוּחֲרָן\">אוֹחֲרַנְתָּא</a>, <span dir=\"rtl\">אוֹחֲרָנִית</span>, <span dir=\"rtl\">אָחֳרָנִיתָא</span>. <span class=\"citation\">Targ. O. ib. XXI, 10</span> (another, additional wife). Ibid. <span class=\"citation\">Gen. XVII, 21</span>.—<span class=\"citation\">Lam. R. to IV, 2</span>.—<span class=\"citation\">B. Bath. 16ᵃ</span> <span dir=\"rtl\">אחרניתא</span> a stranger (not his own wife).—Pl. <span dir=\"rtl\">אוּחֲרנְיָן</span>, <span dir=\"rtl\">אוּחֲרַנְיָין</span>. <span class=\"citation\">Targ. O. Gen. XLI, 3</span>; a. e. <span dir=\"rtl\">אָחֲרַנְיָיאתָא</span>. <span class=\"citation\">Cant. R. to IV, 12</span>.—[<span class=\"citation\">Targ. Y. Gen. XXXV, 8</span> <span dir=\"rtl\">אוֹחֲרַן בכיותא</span> a repetition of weeping, v. <a href=\"#\" data-headword=\"אַלֹּון II\"><span dir=\"rtl\">אִלֹּון</span> II</a>.]</div>","alt":["אוֹחֲרָן","אוֹחֲרָנָא"]},"1061":{"h":"אֲחֶרֶת","r":"A01061","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אַחֵר\">אַחֵר</a></div>","alt":[]},"1062":{"h":"אֲחַשְׁדַּרְפְּנַיָּא","r":"A01062","html":"<div class=\"sense\"> … m. pl.(h. <i>satraps, Persian governors.</i> <span class=\"citation\">Dan. III, 2</span>; a. e.—<span class=\"citation\">Cant. R. to VII, 9</span>.</div>","alt":["נִין"]},"1063":{"h":"אַחַת","r":"A01063","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֶחָד\">אֶחָד</a></div>","alt":[]},"1064":{"h":"אֲחָת","r":"A01064","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span class=\"citation\">Targ. Jer. XXII, 18</span>; a. fr.—<span class=\"citation\">Pes. 4ᵃ</span>; a. fr.—Pl. <span dir=\"rtl\">אַחֲוָותָא</span>. <span class=\"citation\">Targ. Job. I, 4</span> (ed. <span dir=\"rtl\">אַחְיָ׳</span>); a. e.—<span class=\"citation\">Yeb. 32ᵇ</span>. <span class=\"citation\">Sabb. 13ᵃ</span>. <span class=\"citation\">Yeb. 66ᵃ</span> top (<i>twin sisters</i>).</div>","alt":["(אַחַת)","אֲחָתָא"]},"1065":{"h":"א\"ט","r":"A01065","html":"<div class=\"sense\"><i>Atbaḥ</i>, a formula of combination or interchange of two letters the numerical sum of which is either ten (e.g. <a href=\"#\" data-headword=\"א\">א&quot;ט</a> = 1 + 9; <span dir=\"rtl\">ב&quot;ח</span> = 2 + 8) or <i>one hundred</i> (e.g. <span dir=\"rtl\">י&quot;צ</span> = 10 + 90; <span dir=\"rtl\">כ&quot;פ</span> = 20 + 80 = 100), whereby <a href=\"#\" data-headword=\"ה\">ה</a> and <a href=\"#\" data-headword=\"נ\">נ</a>, remain isolated or substitute each other. <span class=\"citation\">Ex. R. s. 15</span> (allusion to <span dir=\"rtl\">ה̇ן̇</span> <span class=\"citation\">Num. XXIII, 9</span>).—<span class=\"citation\">Succ. 52ᵇ</span> <span dir=\"rtl\"><span dir=\"rtl\">באטב&quot;ח</span> (<span dir=\"rtl\">של ר׳ חייא</span>) <span dir=\"rtl\">קורין כ׳ לס̇ה̇ד̇ה̇ מ̇נ̇ו̇ן̇</span></span> in the Atbaḥ (of R. Ḥiya) <i>sahadah</i> finds a substitute in <i>manon</i> (v. <span class=\"citation\">Prov. XXIX, 21</span>).</div>","alt":["אטב\"ח"]},"1066":{"h":"אִטָּא","r":"A01066","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">אטט</span>, cmp. <a href=\"#\" data-headword=\"חֲטַט I\">חטט</a> = b. h. <a href=\"#\" data-headword=\"אֵת\">אֵת</a>, pl. <span dir=\"rtl\">אִתִּים</span>), pl. <span dir=\"rtl\">אִטִּין</span> <i>plough-shares</i>. Y. Sabb. VI, 8ᵇ bot. (expl. <span dir=\"rtl\">לאִתִּים</span> (<span class=\"citation\">Is. II, 4</span>) <span dir=\"rtl\">לאִ׳</span> (Ar. by cler. err. <a href=\"#\" data-headword=\"אבויין\">אבויין</a>).</div>","alt":[]},"1067":{"h":"אֲטָא","r":"A01067","html":"<div class=\"sense\">, Af. <a href=\"#\" data-headword=\"יְטִי\">אַיְיטִי</a>, v. <a href=\"#\" data-headword=\"יְטָא\">יְטָא</a>, <a href=\"#\" data-headword=\"יְטִי\"><a href=\"#\" data-headword=\"יְטִי\">יְטִי</a>.</a></div>","alt":[]},"1068":{"h":"אַטְבָּא","r":"A01068","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טָבַע I\">טבע</a>, v. <a href=\"#\" data-headword=\"טַבַּעַת\">טַבַּעַת</a>) <i>ring, hook, clasp</i>. <span class=\"citation\">Men. 32ᵃ</span> <span dir=\"rtl\">א׳ דסיפרי</span> clasp for fastening the leaves of books while reading.—Pl. <span dir=\"rtl\">(<span dir=\"rtl\">אַטְבְּעֵי</span>) <a href=\"#\" data-headword=\"טְבַל\">אַטְבֵּי</a></span>. <span class=\"citation\">Sabb. 98ᵃ</span> Ar. <span dir=\"rtl\">אטבי</span> (ed. <span dir=\"rtl\">באטבעי אטבעי</span>, some ed. <span dir=\"rtl\">בא׳ בטבעי</span>, corr. acc., Ms. M. only <span dir=\"rtl\">בטבעי</span>, margin <span dir=\"rtl\">אטבי</span>; v. Rabb. D. S. a. l.). <span class=\"citation\">Num. R. s. 6</span> (in Hebr. diction) <span dir=\"rtl\">א׳ של ברזל</span> iron clasps (to fasten the boards on the wagon).</div>","alt":["(אַטְבְּעָא)"]},"1069":{"h":"אט\"בח","r":"A01069","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"א\">א&quot;ט</a></div>","alt":[]},"1070":{"h":"אַטְבְּעָא","r":"A01070","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אַטְבָּא\">אַטְבָּא</a></div>","alt":[]},"1071":{"h":"אָטָד","r":"A01071","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"אִטָּא\">אִטָּא</a>) <i>thorn</i>. <span class=\"citation\">Gen. R. s. 100</span>. <span class=\"citation\">Sot. 13ᵃ</span>.—<span class=\"citation\">Y. Ned. VI, end 40ᵃ</span> <span dir=\"rtl\">מדבר הא׳</span> the desert of <i>Atad.—</i> Pl. <span dir=\"rtl\">אֲטָדִין</span>. <span class=\"citation\">Shebi. VII, 5</span>; a. e. [V. Sm. Ant. s. v. Carduus.]</div>","alt":[]},"1072":{"h":"אָטָד ²","r":"A01072","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Gen. L, 10</span>.—<span class=\"citation\">Targ. Ps. LVIII, 10</span>. Ms. (ed. <a href=\"#\" data-headword=\"אָטָד ²\">אֲטָדָא</a>); a. e.—Pl. <span dir=\"rtl\">אַטְדִין</span>. <span class=\"citation\">Targ. O. Gen. III, 18</span>. (Y. <span dir=\"rtl\">אַטְטִין</span>). <span class=\"citation\">Targ. Hos. X, 8</span> (some ed. <span dir=\"rtl\">אטטין</span>).</div>","alt":["אַטְדָא"]},"1073":{"h":"אָטוּ","r":"A01073","html":"<div class=\"sense\"> (abbrev. of <a href=\"#\" data-headword=\"אַמְטוּל\">אמטול</a>, v. <a href=\"#\" data-headword=\"אַמְטוּ\">אַמְטוּ</a>) </div><div class=\"sense\"><b>1)</b> <i>on account of, because of, for the sake of</i>(h. . <span dir=\"rtl\">קנסו שוגג א׳ מזיד</span> they fined the inadvertent transgressor for the sake of the wilful one (in order to prevent wilful sin). <span class=\"citation\">Git. 53ᵇ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  (in questions expressing <i>surprise, indignation</i>) <i>is it because? do you mean to say?</i> Ib. 7ᵃ <span dir=\"rtl\">א׳ אנא לא ידענא</span> do I not know it myself? Ib. 30ᵇ <span dir=\"rtl\">א׳ ברשיעי עסקינן</span> is it with wicked men we have to deal? (i.e. shall we presume deliberate sin?); a. v. fr.</div>","alt":[]},"1074":{"h":"אֵטוּנָא","r":"A01074","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. b. h. <span dir=\"rtl\">אֵטוּן</span>; prob. fr. <a href=\"#\" data-headword=\"טוי\">טוה</a> <i>to spin;</i> for oth. etym. v. Ges. H. Dict. s. v. <span dir=\"rtl\">אטן</span>) <i>rope, chord</i>. <span class=\"citation\">Targ. Josh. II, 15</span>. <span class=\"citation\">Targ. Job. XXX, 11</span> (ed. give all var. combined, v. <a href=\"#\" data-headword=\"שׁוּשְׁלָא\">שׁוֹשַׁלְתָּא</a>).—<span class=\"citation\">R. Hash. 23ᵃ</span> <span dir=\"rtl\">א׳ דכיתנא</span> (some ed. <span dir=\"rtl\">אטוני</span> pl.) flaxrope.—Pl. <span dir=\"rtl\">אֵטוּנִין</span>, <span dir=\"rtl\">(<span dir=\"rtl\">אַטּ׳</span>) <span dir=\"rtl\">אֵטוּנַיָּא</span></span>. <span class=\"citation\">Targ. I Kings XX, 31</span>; a. fr. [<span class=\"citation\">Tosef. Maasr. III, 8</span> <span dir=\"rtl\">אטונין</span> ed., ed. Zuck. <span dir=\"rtl\">עטינין</span>, Var. <a href=\"#\" data-headword=\"*אַטִּינִין\">אטינין</a> q. v.]</div>","alt":["אַטּוּנָא"]},"1075":{"h":"אֲטוּנָס","r":"A01075","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. θύννος; v. Sm. Ant. s. v.) <i>tunny-fish</i>. <span class=\"citation\">Ḥull. 66ᵇ</span>; <span class=\"citation\">Ab. Zar. 39ᵃ</span> Ms. M. (ed. <span dir=\"rtl\">אוט׳</span>). <span class=\"citation\">Tosef. Ḥull. III</span> (<span class=\"citation\">IV), 27</span> <a href=\"#\" data-headword=\"אנתינוס\">אַנְתִּינִיס</a> ed. Zuck. (Var. <a href=\"#\" data-headword=\"אנתינוס\">אַנְתִּינוֹס</a>). Ib. Kel. <span class=\"citation\">B. Mets. II, 17</span> <span dir=\"rtl\">ליטול בטינס</span>; (read as) <span class=\"citation\">Ḥull. 25ᵃ</span> <span dir=\"rtl\">להטיהו בטו׳</span> to polish a vessel with the skin of a tunny. *<span class=\"citation\">Cant. R. to I, 7</span> <span dir=\"rtl\">כמה מיני אנונס וכ׳</span> (read <span dir=\"rtl\">אטו׳</span>; <span class=\"citation\">Ex. R. s. 2</span> <span dir=\"rtl\">מזונות</span>) how many kinds of tunny fish hast thou prepared for the lying-in among them? V. <a href=\"#\" data-headword=\"*אכספטיאס\">אכספטיאס</a>.</div>","alt":["טוּנָס"]},"1076":{"h":"אטורנגא","r":"A01076","html":"<div class=\"sense\"> <span class=\"citation\">Keth. 61ᵃ</span> bot., v. <a href=\"#\" data-headword=\"אַכְוַנְגַּר\">אַכְוַנְגָּר</a></div>","alt":[]},"1077":{"h":"אֲטָטָא","r":"A01077","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אָטָד ²\">אַטְדָא</a></div>","alt":[]},"1078":{"h":"*אטיטס","r":"A01078","html":"<div class=\"sense\"> <span class=\"citation\">Ḥall. IV, 11</span> (<span class=\"citation\">12</span>) Ar., Ms. M.; ed. Talm. Y. <span dir=\"rtl\">בן א׳</span>, Mishn. <a href=\"#\" data-headword=\"אַנְטִינוּס\">אנטינוס</a>; <span class=\"citation\">Tem. 21ᵃ</span> Ar., ed. <span dir=\"rtl\">בן אַנְטִיגְנוֹס</span>, q. v.</div>","alt":[]},"1079":{"h":"אטימוייס","r":"A01079","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*איינים\">אייניס</a></div>","alt":[]},"1080":{"h":"אֱטִימוֹס","r":"A01080","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ἕτοιμος) <i>present, ready</i>. <span class=\"citation\">Targ. Y. Num. XI, 26</span>; a. fr.—<span class=\"citation\">Gen. R. s. 48</span> it does not read <span dir=\"rtl\">עומד</span> (standing) but <span dir=\"rtl\">נצב</span> (placed on his post), i.e. <span dir=\"rtl\">אט׳</span> ready (to proceed). <span class=\"citation\">Cant. R. to II, 9</span> <a href=\"#\" data-headword=\"אִסְקְרִיטִין\">אי׳</a>. <span class=\"citation\">Gen. R. s. 100</span>.</div>","alt":["אִיטִימוֹס"]},"1081":{"h":"אטימטון","r":"A01081","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֲטִימִיטוֹן\">אֲטִימִיטוֹן</a></div>","alt":[]},"1082":{"h":"אֲטִימיטָא","r":"A01082","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֲטִימִיטוֹן\">next w.</a></div>","alt":[]},"1083":{"h":"אֲטִימִיטוֹן","r":"A01083","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (neut., or accus. of ἀτίμητος (something) <i>invaluable, priceless</i>. <span class=\"citation\">Y. Peah I, 15ᵈ</span> bot. <span dir=\"rtl\">חד מרגלי טבא א׳</span> (read <a href=\"#\" data-headword=\"חדא\">חדא</a>) a pearl worth a priceless treasure. <span class=\"citation\">Gen. R. s. 35</span> end <span dir=\"rtl\">מרגלית אטימטון</span>. *Ruth R. next to I, 18 <span dir=\"rtl\">מילא דאיסטופיטא</span> read <span dir=\"rtl\">מרגליתא אטימיטא</span> an invaluable pearl.</div>","alt":[]},"1084":{"h":"אטימיסיאה","r":"A01084","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֱטִימָסִיאָה\">next w.</a></div>","alt":[]},"1085":{"h":"אֱטִימָסִיאָה","r":"A01085","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (ἑτοιμασία) <i>well secured and supplied station</i>. <span class=\"citation\">Num. R. s. 16</span>, end.</div>","alt":["אִיטִ׳"]},"1086":{"h":"*אַטִּינִין","r":"A01086","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (a contr. of <span dir=\"rtl\">אטעינין</span>; <span dir=\"rtl\">נטע</span>) <i>herbs selected for planting purposes</i>. <span class=\"citation\">Tosef. Maasr. III, 8</span> <span dir=\"rtl\">אטי׳</span> ed. Zuck. (Var. <span dir=\"rtl\">עטי׳</span>; ed. <span dir=\"rtl\">אטו׳</span>). Y. ib. V, beg. 51ᶜ <span dir=\"rtl\">עטנין</span>. Cmp. <a href=\"#\" data-headword=\"שֹׁתֶל\">שֵׁתֶל</a>; <span dir=\"rtl\">שְׁתִילִין</span>.</div>","alt":["עַטִּינִין","(עִטְּנִין)"]},"1087":{"h":"*אַטִּיפָא","r":"A01087","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">נטף</span>, cmp. <a href=\"#\" data-headword=\"טִיף I\">טִיף</a>) <i>drop-like cavity in the cheese</i>. . <span class=\"citation\">Ab. Zar. 35ᵇ</span> <span dir=\"rtl\">ביני א׳</span>. Ar. (ed. <a href=\"#\" data-headword=\"טְפֵי\">אַטְּפֵי</a>) between the holes.</div>","alt":[]},"1088":{"h":"אַטֵּל","r":"A01088","html":"<div class=\"sense\"> Af. of <a href=\"#\" data-headword=\"נְטַל\">נְטַל</a>.</div>","alt":[]},"1089":{"h":"אִטְלוּלָא","r":"A01089","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טְלַל I\">טְלַל</a>) <i>jest</i>. <span class=\"citation\">Erub. 68ᵇ</span> <span dir=\"rtl\">חוכא וא׳</span> derision and jest (Ar. a. Ms. Oxf. <a href=\"#\" data-headword=\"טְלוּלָא\">טְלוּלָא</a>).</div>","alt":["אִיטְ׳"]},"1090":{"h":"אַטְּלוּתָא","r":"A01090","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, const. (<span dir=\"rtl\">נטל</span>) <a href=\"#\" data-headword=\"אַטְּלוּתָא\">אַטְּלוּת</a> <i>thowing, casting</i>. <span dir=\"rtl\">א׳ אבנין</span> stoning to death. <span class=\"citation\">Targ. Y. Ex. XXI, 17</span>; a. e.</div>","alt":[]},"1091":{"h":"אִטַלְיָא","r":"A01091","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיטַלְיָא\">אִיטַלְיָא</a></div>","alt":["אִטַלְיוֹן"]},"1092":{"h":"אַטְלֵיז","r":"A01092","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טְלַל I\">טלל</a>, with format. <a href=\"#\" data-headword=\"ז\">ז</a> or <a href=\"#\" data-headword=\"ס\">ס</a>; cmp. <a href=\"#\" data-headword=\"אוּשְׁפֵּיז\">אוּשְׁפֵּיז</a>; v. <a href=\"#\" data-headword=\"טְלַל II\"><span dir=\"rtl\">טָלַל</span> II</a>, טְלַל I, II) <i>a number of booths</i> put up for a <i>mercantile fair</i>, or for <i>popular entertainments;</i> whence (cmp. <a href=\"#\" data-headword=\"חָנוּת\">חָנוּת</a>) <i>shops, bazaar</i> (v. esp. <span class=\"citation\">Gen. R. s. 79</span>, quot. bel.). <span class=\"citation\">Ḥull. 91ᵇ</span> <span dir=\"rtl\">א׳ של אמאוס</span> the fair of Emmaus. Pesik. Asser p. 98ᵇ. <span class=\"citation\">Arakh. VI, 5</span> (<span class=\"citation\">24ᵃ</span>) <span dir=\"rtl\">אם ממתינין אותה לאיטלס</span> if they delay the sale for the market day; a. fr.—Pl. <span dir=\"rtl\">אַטְלֵסִין</span> &amp;c. <span class=\"citation\">Gen. R. s. 79</span> (ref. to <span dir=\"rtl\">ויחן</span> ‘and he encamped’ = made a <a href=\"#\" data-headword=\"חָנוּת\">חנות</a> <span class=\"citation\">Gen. XXXIII, 18</span>) Jacob was the first <span dir=\"rtl\">מעמיד א׳</span> Ar. (ed. also <span dir=\"rtl\">הטלסין</span>, v. <a href=\"#\" data-headword=\"*הֶטְלֵיס\">הֶטְלֵיס</a>) to put up stores and sell cheap; [<span class=\"citation\">Koh. R. to X, 8</span>; Est. R. to I, 9, sing., some ed. <a href=\"#\" data-headword=\"אִיתְּלִיס\">אִיתְּלִיס</a>, <span dir=\"rtl\">אַתְּלִיס</span> (!)]. Cmp. <a href=\"#\" data-headword=\"עַטְלֵיז\">עַטְלֵיז</a>, <a href=\"#\" data-headword=\"אִסְטֵל\">אִסְטֵל</a> [<span class=\"citation\">Tosef. Ḥull. I, 7</span> <span dir=\"rtl\">באטלס</span> read <span dir=\"rtl\">באַטְלֵק</span> by <i>throwing;</i> cmp. <span class=\"citation\">Ḥull. 12ᵇ</span> <span dir=\"rtl\">זרק סכין וכ׳</span>.] V. <a href=\"#\" data-headword=\"אִיטְלִיסִית\">אִיטְלִיסִית</a>.</div>","alt":["אִיטְלֵיז","אַטְלֵס","אִיטְלֵיס"]},"1093":{"h":"אטליט","r":"A01093","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אַתְלֵיט</span></div>","alt":[]},"1094":{"h":"אַטְלֵיס","r":"A01094","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַטְלֵיז\">אטְלֵיז</a></div>","alt":["אַטְלֵס"]},"1095":{"h":"*אַטְלֵק","r":"A01095","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אִטְלָקוּתא\">next w.</a>) <i>throw, thrust</i>. <span class=\"citation\">Tosef. Ḥull. I, 7</span>; v. <a href=\"#\" data-headword=\"אַטְלֵיז\">אַטְלֵיז</a> end.</div>","alt":[]},"1096":{"h":"אִטְלָקוּתא","r":"A01096","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"טְלַק\">טלק</a>) <i>being thrown</i>. <span class=\"citation\">Targ. Job. III, 4</span> <span dir=\"rtl\">באִטְלָקוּתֵיה</span> (Var. <span dir=\"rtl\">אִיטַלָּ׳</span>) on his being thrown.</div>","alt":[]},"1097":{"h":"אָטַם","r":"A01097","html":"<div class=\"sense\"><i>to obstruct, close, fill up</i>. Part. pass. <span dir=\"rtl\">אָטוּם</span>, f. <span dir=\"rtl\">אֲטוּמָה</span> </div><div class=\"sense\"><b>1)</b> <i>filled up, solid</i>. <span class=\"citation\">Zeb. 61ᵇ</span> <span dir=\"rtl\">א׳ באדמה</span> filled up with earth, opp. <a href=\"#\" data-headword=\"חָלוּל\">חָלוּל</a>. <span class=\"citation\">Ḥull. 47ᵇ</span> <span dir=\"rtl\">א׳ בריאה</span> v. <a href=\"#\" data-headword=\"אוֹטֶם\">אוֹטֶם</a>. <span class=\"citation\">Y. B. Bath. II, 13ᶜ</span> top <span dir=\"rtl\">כותל א׳</span> a solid wall.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"טוּמְטוּם\">טוּמְטוּם</a>) <i>stumped, shapeless</i>. <span class=\"citation\">Nidd. 24ᵃ</span> <span dir=\"rtl\">גוף א׳</span> the stump of a human body (of the embryo). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אתּ שגולגלתו א׳</span> an embryo whose scull is a shapeless lump (no scull discernible). Y. ib. III, 50ᵈ top.—<i>Trnsf.</i> <span class=\"citation\">Snh. 44ᵇ</span> <span dir=\"rtl\">אוֹטֵם עונות</span> he locks up the sins (makes them invisible, cmp. <a href=\"#\" data-headword=\"טָמַן\">טָמַן</a>); v. <a href=\"#\" data-headword=\"אִיטְמוֹן\">אִיטְמוֹן</a>.</div>","alt":[]},"1098":{"h":"אַטְמָא","r":"A01098","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אָטַם\">foreg.</a>) <i>something solid</i>, whence <i>the solid part, flank</i>. Targ. II, <span class=\"citation\">Esth. I, 2</span>.—<span class=\"citation\">B. Mets. 23ᵇ</span> אי דדפנא אי דא׳ Ar. (ed. <span dir=\"rtl\">או דדפקא או דא׳</span>, v. Rabb. D. S. a. l. note 3) whether from the ribs or from the flank. <span class=\"citation\">Ḥull. 42ᵇ</span> <span dir=\"rtl\">בוקא דא׳</span> the thickest part of the flank (the thigh, hip).—<span class=\"citation\">B. Bath. 73ᵇ</span> <span dir=\"rtl\">חדא דלי א׳</span> one (goose) lifted up its thigh (leg).—Pl. <a href=\"#\" data-headword=\"טְוִי II\">אַטְמֵי</a>. <span class=\"citation\">Ḥull. 8ᵃ</span> <span dir=\"rtl\">א׳ דקיימי לקורבנא</span> solid pieces (roast) intended for a present. <span class=\"citation\">Sabb. 49ᵃ</span>.—<span dir=\"rtl\">אַטְמָתָא</span>. <span class=\"citation\">Snh. 59ᵇ</span> ed. (Ms. <span dir=\"rtl\">אַטְמָהָתָא</span>). <span class=\"citation\">Lam. R. to I, 1</span> <span dir=\"rtl\"><span dir=\"rtl\">אַטְמָאָתָא</span> (רבתי</span>).—<span class=\"citation\">Ḥull. 97ᵇ</span> <span dir=\"rtl\">הנהו אַטְמָהָתָא</span> those solid pieces of the thigh. <span class=\"citation\">Erub. 57ᵇ</span> <span dir=\"rtl\">א׳ דשורא</span> ed. (Ms. <span dir=\"rtl\">אטמאתא</span>) flanks (projecting parts) of a wall. V. <a href=\"#\" data-headword=\"אִיטְמָא\">אִיטְמָא</a>.</div>","alt":["(אִיטְמָא)"]},"1099":{"h":"אטנים","r":"A01099","html":"<div class=\"sense\"> <span class=\"citation\">Esth. R. to I, 14</span>, read <a href=\"#\" data-headword=\"אנונים\">אֲנוֹנִים</a>, v. <a href=\"#\" data-headword=\"אַנֹּונָא\">אְנוֹנָא</a></div>","alt":["אטנם","אטנס"]},"1100":{"h":"אַטְּפָא","r":"A01100","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"*אַטִּיפָא\">אַטִּיפָא</a></div>","alt":[]},"1101":{"h":"*אטקטיא","r":"A01101","html":"<div class=\"sense\">, prob. <span dir=\"rtl\">אֲטַקְטִין</span> or <span dir=\"rtl\">אֲטַקְטֵי</span> m. pl. (ἄτακτοι) <i>undisciplined, irregular troops</i>. Pesik. Ekhah p. 122ᵇ (explaining: ‘thy princes are rebels’ <span class=\"citation\">Is. I, 23</span>) <span dir=\"rtl\">אדוניך מריונים דהוו מזיינין א׳</span> ‘thy lords are rebels’—for they equipped irregulars. [This seems to be the proper version restored from Ar. a. Var.; v. Pesik. l. c. note 75.]</div>","alt":[]},"1102":{"h":"אִטֵּר","r":"A01102","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> Dict.), sub. <span dir=\"rtl\">יד ימינו</span> <i>one whose right hand is tied up</i> or <i>unfit for labor; left-handed</i>. <span class=\"citation\">Sabb. 103ᵃ</span> <span dir=\"rtl\">אי׳ יד</span>. <span class=\"citation\">Men. 37ᵃ</span> only <a href=\"#\" data-headword=\"א׳\">א׳</a>. <span class=\"citation\">Tosef. Bekh. V, 8</span> <span dir=\"rtl\">א׳ בין בידיו וכ׳</span>; <span class=\"citation\">Bekh. 45ᵇ</span> <span dir=\"rtl\">א׳ בין ביד וכ׳</span> one either left-handed or left-legged (v. Rashi a. l.).</div>","alt":["אִיטֵּר"]},"1103":{"h":"אַטְרִבֹּולִיס","r":"A01103","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Tripolis</i>, on the coast of Phœnicia. <span class=\"citation\">Y. Sabb. III, 6ᶜ</span> top; (Bab. <span class=\"citation\">ib. 45ᵇ</span> <i>Sidon</i>).</div>","alt":[]},"1104":{"h":"אֶטְרוֹגָא","r":"A01104","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אַתְרוֹגָא\">אֶתְרוֹגָא</a>) <i>orange</i> (tree, a. fruit). <span class=\"citation\">Targ. Cant. II, 3</span> (h. text <span dir=\"rtl\">תפוח</span>, some ed. <a href=\"#\" data-headword=\"אִיתְכָּלָא\">אֶתְ׳</a>). <span class=\"citation\">Y. Ab. Zar. II, 41ᵃ</span> bot.</div>","alt":["אִיטְרוֹגָא"]},"1105":{"h":"אִטְרוֹן","r":"A01105","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אִיטְרוֹן\">אִיטְרוֹן</a></div>","alt":[]},"1106":{"h":"אִטְּרִי","r":"A01106","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">נטר</span>; cmp. <a href=\"#\" data-headword=\"הִטְּרִית\">הִטְּרִי</a> a. <a href=\"#\" data-headword=\"טָרִית\">טָרִית</a>) prop. <i>something preserved</i>, hence <i>dough preserved, vermicelli</i>. <span class=\"citation\">Y. Ḥall. I, 57ᵈ</span> bot. as I intend making <span dir=\"rtl\">אצוותי א׳</span> my dough into vermicelli. <span class=\"citation\">Y. Bets. I, 60ᵈ</span> <span dir=\"rtl\">הדא אטריתא וכ׳</span></div>","alt":["אִטְּרִיתָא"]},"1107":{"h":"אֲטַרְכוֹנָא","r":"A01107","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Trachonitis</i>, a district east of Gaulanitis. <span class=\"citation\">Targ. Y. II, Deut. III, 14</span> (h. Argob). V. <a href=\"#\" data-headword=\"טְרָכוֹנָא\">טרכונא</a>.</div>","alt":[]},"1108":{"h":"אַטְרַף","r":"A01108","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"טַרְפָא I\">טַרְפָּא</a>, h. <a href=\"#\" data-headword=\"טֶרֶף\">טֶרֶף</a>) <i>leaf.</i> <span class=\"citation\">Git. 69ᵇ</span> (collect.).—Pl. <span dir=\"rtl\">אַטְרְפִין</span>, <span dir=\"rtl\">אַטְרְפֵי</span>. <span class=\"citation\">Targ. Ps. I, 3</span>. <span class=\"citation\">B. Mets. 114ᵇ</span> (Var. <span dir=\"rtl\">טרפי</span>, v. Rabb. D. S. a. l.).</div>","alt":["אֲטְרְפָא"]},"1109":{"h":"אִי־","r":"A01109","html":"<div class=\"sense\"> prefix, v. <a href=\"#\" data-headword=\"אִ־\">אִ־</a></div>","alt":[]},"1110":{"h":"אִי I","r":"A01110","html":"<div class=\"sense\"> fem. of <a href=\"#\" data-headword=\"אוּ\">אוּ</a> q. v.</div>","alt":[]},"1111":{"h":"אִי II","r":"A01111","html":"<div class=\"sense\"> (= <a href=\"#\" data-headword=\"אִין I\">אִין</a>; h. <a href=\"#\" data-headword=\"אִם\">אִם</a>; cmp. <a href=\"#\" data-headword=\"אוֹ\">אוֹ</a>) </div><div class=\"sense\"><b>1)</b> <i>if, whether</i>. <span class=\"citation\">Targ. Cant. VII, 13</span>; a. e.—<span class=\"citation\">Ber. 2ᵃ</span>, a. fr. <span dir=\"rtl\">אי הכי</span> (abbrev. <span dir=\"rtl\">א&quot;ה</span>) if this be so (introducing an argument against one’s opinion).—<span class=\"citation\">R. Hash. 3ᵃ</span> כי משמש וכ׳ <i>khi</i> has four meanings, <span dir=\"rtl\">אי</span> <i>if</i>, &amp;c.—<span dir=\"rtl\">אי נמי</span> (abbrev. <span dir=\"rtl\">א&quot;נ</span>) a) if you choose, it may also be said; <i>or</i>. <span class=\"citation\">B. Mets. 98ᵃ</span>; a. fr.—b) <i>even if</i>, v. <a href=\"#\" data-headword=\"נַמִּי\">נַמִּי</a>. <span class=\"citation\">Ḥull. 12ᵃ</span> <span dir=\"rtl\">א&quot;נ דילמא וכ׳</span> (Rashi <span dir=\"rtl\">א&quot;נ שמע איניש וכ׳</span>) even if somebody else overheard it; a. fr.—<span dir=\"rtl\">אי אמרת בשלמא</span> (abbr. <span dir=\"rtl\">אא&quot;ב</span> = <span dir=\"rtl\">בשלמא אי אמרת</span>) I grant, if you were to say … <a href=\"#\" data-headword=\"הַיְינוּ\">היינו</a> then would be right what &amp;c.; v. <a href=\"#\" data-headword=\"בִּשְׁלָמָא\">בשלמא</a>. <span class=\"citation\">Yoma 17ᵇ</span>; a. fr.—אי … אי <i>whether … or.</i> <span class=\"citation\">Targ. Koh. XI, 6</span>. <span class=\"citation\">B. Mets. 98ᵃ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  adv. of interrogation, v. <a href=\"#\" data-headword=\"אִין II\"><span dir=\"rtl\">אִין</span> II</a>. <span class=\"citation\">Targ. Job XI, 2</span> Ms. (ed. <span dir=\"rtl\">אין</span>).</div>","alt":["אֵי I"]},"1112":{"h":"אִי III","r":"A01112","html":"<div class=\"sense\"> (= h. <a href=\"#\" data-headword=\"אֵין\">אֵין</a>) <i>not.</i> <span class=\"citation\">Git. IV, 5</span> <span dir=\"rtl\">אי אפשר</span> it is impossible. <span class=\"citation\">Keth. XII, 3</span> אי אפשי I want not; a. fr.</div>","alt":[]},"1113":{"h":"אִי IV","r":"A01113","html":"<div class=\"sense\"> (abbr. of <a href=\"#\" data-headword=\"אִית\">אִית</a>, as <a href=\"#\" data-headword=\"לֵי\">לי</a> = <a href=\"#\" data-headword=\"לַיִת\">לית</a>) <i>there is</i>. Y. Snh. VI, 23ᵇ bot. <span dir=\"rtl\">אי בי וכ׳</span> there is in me (the possibility of) doing, i.e. I can do it. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מה אי וכ׳</span> what is it thou canst do? (v. <span class=\"citation\">Y. Ḥag. II, 78ᵃ</span> top).</div>","alt":[]},"1114":{"h":"אֵי II","r":"A01114","html":"<div class=\"sense\"> Interj. <i>Eh! Oh! Woe!</i> <span class=\"citation\">Targ. Y. II, Lev. XXVI, 29</span>.—<span class=\"citation\">Taan. 7ᵃ</span> אי חכמה וכ׳ Oh, for such a brilliant mind in such an ugly vessel (body)! <span class=\"citation\">R. Hash. 19ᵃ</span> אי שמים Oh heavens!; a. fr. <span class=\"citation\">Y. Shek. V, end, 49ᵇ</span> <span dir=\"rtl\">אי לי שאני וכ׳</span> woe unto me, that I thus see thee! <span class=\"citation\">Y. Yeb. XIII, 14ᵃ</span> top; a. fr. [Babli, usually <a href=\"#\" data-headword=\"אוֹי\">אוֹי</a>.]</div>","alt":[]},"1115":{"h":"אֵי III","r":"A01115","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"אֵיי\">אֵיי</a>) h.  (b. h. <a href=\"#\" data-headword=\"אִי II\">אֵי</a>, <a href=\"#\" data-headword=\"אַיָּה\">אַיֵה</a>) <i>where? what? how?</i>—אי מנן <i>whence?</i> <span class=\"citation\">Targ. Josh. II, 4</span>; a. e.—Hebr. <span dir=\"rtl\">אי זה</span> (often <a href=\"#\" data-headword=\"אֵיזֶה\">אֵיזֶה</a>, <a href=\"#\" data-headword=\"אֵיזֶה\">אֵזֶה</a> in one word) <i>who? which?</i> Y. Kil. VIII, beg. 31ᵇ <span dir=\"rtl\">לאי זה דבר נאמר</span> with regard to what (in what way, sense) has it been said? <span class=\"citation\">Y. Shebi. I, beg. 33ᵃ</span> <span dir=\"rtl\">ואי זה זה</span> and which (ploughing time) is this?; a. v. fr.—<span class=\"citation\">Y. Peah III, 17ᶜ</span> top <span dir=\"rtl\">ואיי דינו מירוג</span> (= <span dir=\"rtl\">אידין</span>) and what is the meaning of <i>merog?</i> Kerith. 6ᵇ <span dir=\"rtl\">לאיי מיצרך צריכי</span> what need is there (of the others)? Cmp. <a href=\"#\" data-headword=\"אֵיזֶה\">אֵיזֶה</a>; <a href=\"#\" data-headword=\"אֵימָתַי\">אֵימָתי</a>; &lt;<span class=\"citation\">Kerith. 6ᵇ</span> <span dir=\"rtl\">לאיי מיצרך צריכי</span> what need is there (of the others)? Cmp. <a href=\"#\" data-headword=\"אֵיזֶה\">אֵיזֶה</a>; <a href=\"#\" data-headword=\"אֵימָתַי\">אֵימָתי</a>; <a href=\"#\" data-headword=\"כֵּיצַד\">כֵּיצַד</a>.</div>","alt":[]},"1116":{"h":"אֵיב","r":"A01116","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֵב\">אֵב</a></div>","alt":[]},"1117":{"h":"אִיבָּא I","r":"A01117","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"אֵב\">אֵב</a>) <i>growth, fruit</i>. <span class=\"citation\">Targ. Gen. IV, 3</span>; a. e.; v. <a href=\"#\" data-headword=\"אִנְבָּא I\">אִנְבָּא</a>.</div>","alt":["אִבָּא"]},"1118":{"h":"אִיבָּא II","r":"A01118","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"אַבָּא I\">אַבָּא</a> <i>father</i>. <span class=\"citation\">Targ. Y. Num. XXX, 4</span>; a. fr.</div>","alt":["אִיבָא"]},"1119":{"h":"*אִיבְבָא","r":"A01119","html":"<div class=\"sense\">= <a href=\"#\" data-headword=\"אִיבָּא I\">אִיבָּא</a><b> I,</b> pl. <span dir=\"rtl\">איבְבַיָּא</span>. <span class=\"citation\">Targ. I Kings VI, 38</span> (ed. Vien. <span dir=\"rtl\">אִבְּבַיָא</span>).</div>","alt":[]},"1120":{"h":"אֵיבָה","r":"A01120","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>enmity, hostility, grudge</i>. <span class=\"citation\">Snh. III, 5</span> an enemy is he who has not spoken to his neighbor for three days <span dir=\"rtl\">בא׳</span> in his grudge; a. fr.—<span dir=\"rtl\"><span dir=\"rtl\">משום</span> (<span dir=\"rtl\">מפני</span>) <a href=\"#\" data-headword=\"א׳\">א׳</a></span> for the sake of preventing ill-feeling. <span class=\"citation\">Y. Dem. IV, 24ᵃ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>aversion, disgust, loss of attraction</i>. <span class=\"citation\">Y. Yoma VIII, 44ᵈ</span> bot. <span dir=\"rtl\">הכלה מפני א׳</span> the bride (is permitted to wash her face on the Day of Atone.) that she may not lose her attraction.</div>","alt":[]},"1121":{"h":"אִיבּוּ","r":"A01121","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">אנב</span>, √<a href=\"#\" data-headword=\"אָב I\">אב</a>. cmp. <a href=\"#\" data-headword=\"אָבֵל I\">אבל</a>) [<i>black</i>], name of a bird (h. <span dir=\"rtl\">אֲנָפָה</span>) <i>vulture</i> or <i>kite</i>. <span class=\"citation\">Targ. O. Lev. XI, 19</span>; <span class=\"citation\">Deut. XIV, 18</span> (Targ. Y. <span dir=\"rtl\">אוכמתא</span>). [<span class=\"citation\">Targ. Y. I Deut. XIV, 13</span>, <span class=\"citation\">Targ. Y. II, Deut. XIV, 13</span>; <span class=\"citation\">14</span>, gloss to v. 18; confounded with v. 13—h. text <a href=\"#\" data-headword=\"אַיָּה\">אַיָּה</a>.]—<a href=\"#\" data-headword=\"אִיבּוּ\">אִיבּוּ</a> pr. n. m., v. <a href=\"#\" data-headword=\"אִבּוּ\">אִבּוּ</a>.</div>","alt":["אִבּוּ","(אִיבֹּו)"]},"1122":{"h":"אִיבּוּד","r":"A01122","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">אבד</span>) <i>ruin, destruction</i>. <span class=\"citation\">Ab. Zar. 33ᵃ</span> <span dir=\"rtl\">אזיל לא׳</span> is wasted. <span class=\"citation\">Ḥull. 11ᵇ</span> <span dir=\"rtl\">משום א׳ נשמה</span> to prevent loss of life (to save the convict). <span class=\"citation\">Bets. 22ᵃ</span> <span dir=\"rtl\">אִבּוּד ממון</span> pecuniary loss; a. fr.</div>","alt":[]},"1123":{"h":"אִיבּוּל I","r":"A01123","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָבֵל I\">אבל</a>) <i>mourning;</i> v. <a href=\"#\" data-headword=\"אֲבֵילוּת\">אֲבֵילוּת</a>. <span class=\"citation\">Yeb. IV, 10</span>; a. e.</div>","alt":[]},"1124":{"h":"אִיבּוּל II","r":"A01124","html":"<div class=\"sense\"> ch., v. <a href=\"#\" data-headword=\"אֵיבָרָא\">אִבּ׳</a></div>","alt":["אִיבּוּלָא"]},"1125":{"h":"אֵיבוּס","r":"A01125","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֵבוּס\">אֵבוּס</a></div>","alt":[]},"1126":{"h":"*איבּוּס","r":"A01126","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אָמוּס</span></div>","alt":["כפר א׳"]},"1127":{"h":"אִיבּוּס","r":"A01127","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אָבַס\">אָבַס</a>) <i>stuffing, forcing food down the animal’s throat</i>. <span class=\"citation\">Erub. 20ᵇ</span> (first time) <span dir=\"rtl\">והא אי׳ כמאן וכ׳</span> in stuffing, is it not as if taking a vessel in hand &amp;c.? [Second time <span dir=\"rtl\">והא א׳ כמאן וכ׳</span> omitted in Ms. M.]</div>","alt":[]},"1128":{"h":"*אִיבִּירְיָתָא","r":"A01128","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (prob. contr. of <span dir=\"rtl\">איבעיר׳</span>; <a href=\"#\" data-headword=\"בְּעַר I\">בער</a>), <span dir=\"rtl\">א׳ דזהרא</span> <i>lamp-lighters</i>, hand-maids who attended to the lights. <span class=\"citation\">Y. Yoma III, beg. 40ᵇ</span>; Y. R. Hash. II, beg. 57ᵈ R. … handled things forbidden to handle on the Sabbath <span dir=\"rtl\">על פום א׳ דז׳</span> (Y. R. Hash. l. c., insert <a href=\"#\" data-headword=\"פּוּם\">פום</a>) on the lamplighters’ declaring that night had set in <span dir=\"rtl\">(חשיכה מוצאי שבת</span>). [The context proves that our w. designates a person or persons.]</div>","alt":["אִיבִּירְיָתָה"]},"1129":{"h":"אִיבְלָא","r":"A01129","html":"<div class=\"sense\">= <a href=\"#\" data-headword=\"אֶבְלָא\">אֶבְלָא</a>. <span class=\"citation\">Targ. O. Gen. L, 10</span>; a. e. ed. Berl., oth. ed. <a href=\"#\" data-headword=\"אֶבְלָא\">אֶבְלָא</a>.</div>","alt":[]},"1130":{"h":"אֵיבְלַיִים","r":"A01130","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲבֵילִין\">אֲבֵילִין</a></div>","alt":[]},"1131":{"h":"אִיבָּעִית","r":"A01131","html":"<div class=\"sense\"> (= <a href=\"#\" data-headword=\"אִיבָּעִית\">אִי בָּעִית</a>, v. <a href=\"#\" data-headword=\"בעי\">בעי</a>) <i>if thou so desirest; or</i>. <span dir=\"rtl\">וא׳ אימא</span>—<span dir=\"rtl\">א׳ אימא</span> (abbr. <span dir=\"rtl\">אב&quot;א</span>) if you choose, I may say … or if you prefer (another solution) I may say … <span class=\"citation\">Yoma 28ᵇ</span>; a. fr.</div>","alt":[]},"1132":{"h":"אֵיבֶר","r":"A01132","html":"<div class=\"sense\"><i>, </i> pl. <span dir=\"rtl\">אֵיבָרִים</span>, <span dir=\"rtl\">אֵיבָרִין</span>, v. <a href=\"#\" data-headword=\"אֵבֶר\">אֵבֶר</a>.</div>","alt":[]},"1133":{"h":"אֵיבָרָא","r":"A01133","html":"<div class=\"sense\">(= <a href=\"#\" data-headword=\"אֵיבֶר\">foreg.</a>) </div><div class=\"sense\"><b>1)</b> <i>limb</i>. <span class=\"citation\">Targ. Job. II, 4</span> (Ms. <a href=\"#\" data-headword=\"אִיבְרָא\">אֶיבְרָא</a>). <span class=\"citation\">Yoma 25ᵇ</span>.—Trnsf. <i>arm, wing, pinion</i>. <span class=\"citation\">Sabb. 90ᵇ</span> <span dir=\"rtl\">א׳ דשמאלא</span> left arm.—Pl. <span dir=\"rtl\">אֵיבָרִין</span>, <span dir=\"rtl\">אֵיבָרַיָּא</span>. <span class=\"citation\">Targ. Lev. I, 8</span>, a. e. (<i>pieces</i>). <span class=\"citation\">Targ. Ezek. XVII, 3</span>; <span class=\"citation\">Deut. XXXII, 11</span> (wings).</div><div class=\"sense\"><b>—2)</b> <i>membrum genitale</i>. <span class=\"citation\">Targ. Y. Gen. XIV, 2</span>; <span class=\"citation\">I</span> <span class=\"citation\">ibid. XLIX, 24</span>.—[<span class=\"citation\">B. Mets. 84ᵃ</span>, v. <a href=\"#\" data-headword=\"*אִיבְרָיָה\">אִיבְרָיָה</a>.]</div>","alt":["אֵבְ׳"]},"1134":{"h":"אִיבְרָא","r":"A01134","html":"<div class=\"sense\"> (אבר <i>to be strong</i>) <i>indeed, to be sure</i>. <span class=\"citation\">Ḥull. 59ᵇ</span> <span dir=\"rtl\">א׳ חזינא ליה</span> indeed, I should like to see him. <span class=\"citation\">Git. 56ᵇ</span> top <span dir=\"rtl\">א׳ מלכא את</span> indeed, thou art a sovereign.</div>","alt":[]},"1135":{"h":"*אִיבְרָיָאתָא","r":"A01135","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"*אִיבְרָיָה\">next w.</a>) <i>enough for a meal in the household</i>. <span class=\"citation\">Erub. 82ᵇ</span> תרתי רִיפָתָא א׳ Ms. M. (ed. <a href=\"#\" data-headword=\"אִיכַּרְיָיתָא\">איכרייתא</a>, Asheri, ed. Ven. <span dir=\"rtl\">כברייתא</span>, v. Rabb. D. S. a. l. note) two large loaves of the household (or of mourners’ meals). [Rashi, expl. our w. as loaves of <i>drivers of oxen</i>, appears to have had before him the vers. of Ms. M. and to derive our w. from <a href=\"#\" data-headword=\"בָּרָא I\">ברא</a>, v. <a href=\"#\" data-headword=\"בַּר\">בַּר</a> I a. <a href=\"#\" data-headword=\"אֲפַר\">אֲפַר</a>.]</div>","alt":[]},"1136":{"h":"*אִיבְרָיָה","r":"A01136","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"ברי\">ברי</a>, v. <a href=\"#\" data-headword=\"הוֹבְרָיָא\">הוֹבְרָיָיא</a>) <i>a meal</i>. <span class=\"citation\">B. Mets. 84ᵃ</span> <span dir=\"rtl\">א׳ דר׳ וכ׳</span> one meal of R. Ismael &amp;c. (v. Rabb. D. S. to <a href=\"#\" data-headword=\"*אִיבְרָיָאתָא\">איבריאתא</a>, <span class=\"citation\">Erub. 82ᵇ</span>, note </div><div class=\"sense\"><b>1)</b> ; cmp. Pesik. B’shall. p. 90ᵇ sq., a. <span class=\"citation\">Ber. 44ᵃ</span>). [Some read <a href=\"#\" data-headword=\"*אִיבְרָיָה\">אֵיבָרֵיה</a> v. <a href=\"#\" data-headword=\"אֵיבָרָא\">אֵיבָרָא</a> 2).]</div>","alt":[]},"1137":{"h":"איבריו","r":"A01137","html":"<div class=\"sense\"> <span class=\"citation\">Y. M. Kat. III, 82ᵇ</span> bot. read <span dir=\"rtl\">אִיכָּרָיו</span>; v. <a href=\"#\" data-headword=\"אִיכָּר\">אִיכָּר</a>. [V. however, <a href=\"#\" data-headword=\"*אִיבְרָיָאתָא\">אִיבְרָיָאתָא</a> end.]</div>","alt":[]},"1138":{"h":"איברייא","r":"A01138","html":"<div class=\"sense\"> Y. M. Kat. III, end, 83ᵈ, v. <a href=\"#\" data-headword=\"הוֹבְרָיָא\">הוֹבְרָיָּא</a></div>","alt":[]},"1139":{"h":"אֵיגֶד","r":"A01139","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֵגֶד\">אֵגֶד</a></div>","alt":[]},"1140":{"h":"אֵיגוֹר","r":"A01140","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֵגוֹר\">אֵגוֹר</a> a. <a href=\"#\" data-headword=\"אֱגוֹרָא I\"><a href=\"#\" data-headword=\"אֱגוֹרָא I\">אֲגוֹרָא</a>.</a></div>","alt":["אֵיגוֹרָא"]},"1141":{"h":"אִיגּוּרָא","r":"A01141","html":"<div class=\"sense\">= <a href=\"#\" data-headword=\"אִיגָרָא\">אִיגָרָא</a>. <span class=\"citation\">Targ. Zeph. I, 5</span> (pl.) <a href=\"#\" data-headword=\"אִיגּוּרָא\">אִיגּוּריָּא</a> (ed. Vien. <span dir=\"rtl\">אֱגוֹ׳</span>).</div>","alt":[]},"1142":{"h":"אֵיגוֹרִי","r":"A01142","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֵגוֹרִי\">אֵגוֹרִי</a></div>","alt":[]},"1143":{"h":"אִיגִיאָה","r":"A01143","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (αἰγεία, sub. δορά) <i>goat-skin</i>. <span class=\"citation\">Gen. R. s. 20</span>, end.</div>","alt":[]},"1144":{"h":"איגְלָא","r":"A01144","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אִגְלָא\">אִגְלָא</a></div>","alt":[]},"1145":{"h":"אִיגָר","r":"A01145","html":"<div class=\"sense\"> (אגר II) [<i>vaulted</i>] <i>roof</i>. <span class=\"citation\">Arakh. 32ᵃ</span>; <span class=\"citation\">Meg. 5ᵇ</span> <span dir=\"rtl\">שור א׳</span> a city line formed by joining roofs, opp. <a href=\"#\" data-headword=\"חוֹמָה\">חוֹמָה</a>.—</div>","alt":[]},"1146":{"h":"אִיגָרָא","r":"A01146","html":"<div class=\"sense\">(also <span dir=\"rtl\">אִיגּ׳</span> with Dagesh) const. <a href=\"#\" data-headword=\"אִיגָר\">אִיגַר</a> same. <span class=\"citation\">Targ. Prov. XXI, 9</span>; a. fr.—Ruth. R. to I, 17 (Par. 3) <span dir=\"rtl\">איגר פלטין</span> roof of the palace. <span class=\"citation\">Git. 85ᵇ</span> (Rashi <span dir=\"rtl\">איגרת</span>, corr. acc.), v. <a href=\"#\" data-headword=\"אִגֶּרֶת\">אִגֶּרֶת</a>.—Pl. <span dir=\"rtl\">אִיגָרַיָּא</span>, <span dir=\"rtl\">אִיגָרַיָּיא</span>; <a href=\"#\" data-headword=\"גְּרִי\">אִיגָרֵי</a>. <span class=\"citation\">Targ. II Kings XIX, 26</span>; a. e.—<span class=\"citation\">Y. Pes. VII, 35ᵇ</span> (<span class=\"citation\">Cant. R. to II, 14</span> <a href=\"#\" data-headword=\"*אַבְרְיָיאָה\">אברייאה</a>, corr. acc.); v. <a href=\"#\" data-headword=\"זֵיתָא I\"><span dir=\"rtl\">זֵיתָא</span> I</a>. Lam. R. introd. (R. Yoḥ. 1) <span dir=\"rtl\">ולא׳ סלקין</span> and they ascend the roofs. <span class=\"citation\">Pes. 111ᵇ</span> <span dir=\"rtl\">דבי א׳</span> those (demons) dwelling on roofs.</div>","alt":["אִיגְרָא","אִגָרָא"]},"1147":{"h":"אִיגְּרָא","r":"A01147","html":"<div class=\"sense\"><i>letter</i>, v. <a href=\"#\" data-headword=\"אִיגַּרְתָּא\">אִיגַּרְתָּא</a>.</div>","alt":[]},"1148":{"h":"איגראנאמון","r":"A01148","html":"<div class=\"sense\">= <a href=\"#\" data-headword=\"אַגְרוֹנִימוֹס\">אַגְרוֹנִימוֹס</a> q. v.</div>","alt":[]},"1149":{"h":"אִיגֶּרֶת","r":"A01149","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִגֶּרֶת\">אִגֶּרֶת</a></div>","alt":[]},"1150":{"h":"אִיגַּרְתָּא","r":"A01150","html":"<div class=\"sense\"> f. <a href=\"#\" data-headword=\"אִיגְּרָא\">אִיגְּרָא</a> m. (= h. <a href=\"#\" data-headword=\"אִגֶּרֶת\">אִגֶּרֶת</a>) <i>letter</i> &amp;c. <span class=\"citation\">Targ. II Kings V, 5</span>; a. fr.—Y. Ned. X, end, 42ᵇ, a. e. <span dir=\"rtl\">א׳ דאיקר</span> letter of honor, recommendation. <span class=\"citation\">Sabb. 115ᵃ</span>; a. fr.—<span class=\"citation\">B. Mets. 83ᵇ</span>; <span class=\"citation\">Snh. 82ᵃ</span>; <span class=\"citation\">96ᵃ</span> (prov.) <span dir=\"rtl\">קריינא דא׳ איהו ליהוי פרוונקא</span> let him who composed the letter be himself its carrier.—Pl. (of <a href=\"#\" data-headword=\"אִיגְּרָא\">אִיגְּרָא</a>) <span dir=\"rtl\">אִיגְּרִין</span>. <span class=\"citation\">Targ. Y. II, Num. XXII, 7</span> <a href=\"#\" data-headword=\"אִיגַּרְתָּא\">אִגְּ׳</a>.—<span class=\"citation\">Targ. Is. XXXIX, 1</span>.—<span dir=\"rtl\">אִיגָּרָן</span>, <span dir=\"rtl\">אִיגָּרָאן</span>, <a href=\"#\" data-headword=\"אִיגַּרְתָּא\">אִיגָּרָתָא</a>, <span dir=\"rtl\">אִיגָּרָאתָא</span>. <span class=\"citation\">Targ. I Kings XXI, 9</span>; a. fr.—Y. Keth. II, 26ᵇ bot. Y. Ned. VI, 40ᵃ bot. Y. Snh. I, 19ᵃ top.</div>","alt":["אִגַּ׳"]},"1151":{"h":"אֵיד","r":"A01151","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>turn, due day</i>, whence </div><div class=\"sense\"><b>1)</b> <i>evil fate, reverses</i>. <span class=\"citation\">Gen. R. s. 13</span>, v. <a href=\"#\" data-headword=\"אֵד\">אֵד</a>.</div><div class=\"sense\"><b>—2)</b> <i>anniversary, idolatrous festival</i>. <span class=\"citation\">Ab. Zar. 7ᵇ</span> <span dir=\"rtl\">יום אֵידָם</span> the very day of their festival.—Pl. <span dir=\"rtl\">אֵידִים</span>. <span class=\"citation\">Ib. I, 2</span>, a. fr. <span dir=\"rtl\">(<span dir=\"rtl\">של נכרים</span>) <span dir=\"rtl\">אֵידֵיהֶן</span></span>. <span class=\"citation\">Ib. 2ᵃ</span>; Y. Erub. V, beg. 22ᵃ (controversy as to spelling with <a href=\"#\" data-headword=\"א׳\">א׳</a> or with <a href=\"#\" data-headword=\"ע\">ע</a>). [As to cacophemistic designation, cmp. <a href=\"#\" data-headword=\"אֲבֵידָן\">אבידן</a></div>","alt":[]},"1152":{"h":"אֵידָא I","r":"A01152","html":"<div class=\"sense\"><span class=\"citation\">Targ. Esth. I, 3</span>. <span class=\"citation\">Targ. Prov. VII, 20</span>.</div>","alt":["עֵידָא","עֵדָא"]},"1153":{"h":"אֵידָא II","r":"A01153","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֵידֵין\">אֵידֵין</a> a. <a href=\"#\" data-headword=\"הֵידָא\"><a href=\"#\" data-headword=\"הֵידָא\">הֵידָא</a>.</a></div>","alt":[]},"1154":{"h":"אִידָא I","r":"A01154","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"יַד\">ידא</a>; v. <a href=\"#\" data-headword=\"אִ־\">אִ־</a>) <i>hand</i> (only in Targ. Y.). <span class=\"citation\">Targ. Y. Deut. IX, 26</span>; a. fr.—Pl. <span dir=\"rtl\">אִידַיָּא</span>, <span dir=\"rtl\">אַיְדַיָּא</span>, <a href=\"#\" data-headword=\"אִידֵּי\">אִידֵי</a>. <span class=\"citation\">Targ. Ps. XXIV, 4</span>; a. fr.</div>","alt":["אַיְדָא"]},"1155":{"h":"אִידָא II","r":"A01155","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <span dir=\"rtl\">אִי דָא</span>, v. <a href=\"#\" data-headword=\"אוּ\">אוּ</a> a. <a href=\"#\" data-headword=\"דָּא I\"><a href=\"#\" data-headword=\"דָּא I\">דָּא</a>)</a><i>this, the same</i>. <span class=\"citation\">Y. Erub. III, 21ᵇ</span> bot. <span dir=\"rtl\">הדא אמרה אי א׳ אי א׳</span> this proves this is this, this is that, i.e. it is the same. [<span class=\"citation\">Ib.</span> <span dir=\"rtl\">היא הדא היא הדא</span>.]</div>","alt":[]},"1156":{"h":"אִידָּא","r":"A01156","html":"<div class=\"sense\"><i>wool</i>, v. <a href=\"#\" data-headword=\"אוּדְדָא\">אוּדְדָא</a>, a. <a href=\"#\" data-headword=\"אִירָא\">אִירָא</a>.</div>","alt":[]},"1157":{"h":"אִידוֹר","r":"A01157","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ὕδωρ) <i>water</i>. <span class=\"citation\">Succ. 35ᵃ</span>; v. <a href=\"#\" data-headword=\"הִידוֹר\">הִידוֹר</a>.</div>","alt":[]},"1158":{"h":"אִידוּתָא","r":"A01158","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אַדְווּתָא\">אַדְווּתָא</a></div>","alt":[]},"1159":{"h":"אִידֵּי","r":"A01159","html":"<div class=\"sense\"> pl. of <a href=\"#\" data-headword=\"אִידֵּךְ\">אִידֵּךְ</a>.</div>","alt":[]},"1160":{"h":"אִידִי","r":"A01160","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Idi, Idith</i>, an Amora. <span class=\"citation\">Y. Yoma VII, beg. 44ᵃ</span>. <span class=\"citation\">Snh. 38ᵇ</span>; a. e.</div>","alt":["אִידִית"]},"1161":{"h":"אֵידֵין","r":"A01161","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>who now? what now? which now?</i> (<i>quisnam, quidnam</i>). <span class=\"citation\">Targ. I Sam. VI, 20</span>. <span class=\"citation\">Targ. Jer. II, 10</span>; a. fr.—<span class=\"citation\">Tam. 32ᵃ</span> <span dir=\"rtl\">א׳ מתקרי חכים</span> who is to be called wise? <span class=\"citation\">Lam. R. to I, 1</span> (חד מאת׳ 4) <span dir=\"rtl\">אחמי לי אידא וכ׳</span> show me now which of these is from a white goat &amp;c. <span class=\"citation\">Y. Pes. II, 28ᶜ</span> top <span dir=\"rtl\">ואיידא אמר דא</span> what (passage) now says this (is this derived from)? <span class=\"citation\">Y. Sot. V, 20ᶜ</span> bot. <span dir=\"rtl\">ואיידי חובתא עבדית</span> and what is the sin I have committed? <span class=\"citation\">Lam. R. to III, 7</span> <span dir=\"rtl\">באידנא אסטרטיא וכ׳</span> by which road did you come? </div><div class=\"sense\"><b>2)</b>  (ellipt.) <i>what do you want?</i> <span class=\"citation\">Y. B. Kam. V, beg. 4ᵈ</span>, v. <a href=\"#\" data-headword=\"הֵידָא\">הֵידָא</a>.</div>","alt":["אֵידְנָא","אַיְידָא אֵידָא","(אַיְידִי)"]},"1162":{"h":"אִידְיָנִי","r":"A01162","html":"<div class=\"sense\">, v. <span dir=\"rtl\">אוּדְ׳</span></div>","alt":[]},"1163":{"h":"אִידִית","r":"A01163","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִידִי\">אִידִי</a></div>","alt":[]},"1164":{"h":"אִידֵּךְ","r":"A01164","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> a. fem. (= <a href=\"#\" data-headword=\"דֵּךְ\">דֵּךְ</a>, with <a href=\"#\" data-headword=\"אִי IV\">אִי</a> prosth.) <i>this, that</i>, freq. <i>the other, another</i>. <span class=\"citation\">Yeb. 62ᵃ</span>; a. fr. <span dir=\"rtl\">תניא א׳</span> another (author or Boraitha) teaches. <span class=\"citation\">Ib. 22ᵇ</span> <span dir=\"rtl\">בא׳ קרא</span> in another verse. <span class=\"citation\">B. Mets. 98ᵇ</span> <span dir=\"rtl\">וא׳ לא ידענא</span> and as to the other (cow), I don’t know; a. fr.—Pl. <a href=\"#\" data-headword=\"אִידֵּי\">אִידֵּי</a>.—<span dir=\"rtl\">א׳ וא׳</span> these and those, i.e. <i>both</i>. <span class=\"citation\">Yeb. 8ᵃ</span>; a. fr.</div>","alt":[]},"1165":{"h":"אִידְכָּרוּ","r":"A01165","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אִדְכָּרוּ\">אִדְכָּרוּ</a></div>","alt":[]},"1166":{"h":"*אִידָּן","r":"A01166","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">אדד</span>, v. <a href=\"#\" data-headword=\"אוּדְרָא\">אוּדְרָא</a>) <i>low-cotton</i>, &amp;c., esp. <i>bast twisted for a wick</i>. <span class=\"citation\">Sabb. II, 1</span>, expl. in Babli (20ᵇ) <span dir=\"rtl\">אחוינא</span>, v. <a href=\"#\" data-headword=\"אַחְוָונָא\">אַחְוָונָא</a> 3), in Y. (4ᶜ) <span dir=\"rtl\">עידניתא</span>.</div>","alt":[]},"1167":{"h":"אֵידְנָא","r":"A01167","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אֵידֵין\">אֵידֵין</a></div>","alt":[]},"1168":{"h":"אִידָּנָא","r":"A01168","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <a href=\"#\" data-headword=\"עִידָּן\">עִידָּן</a>, <a href=\"#\" data-headword=\"עִידָּן ²\">עִירָּנָא</a>; <a href=\"#\" data-headword=\"אוּד\">אוד</a>, <span dir=\"rtl\">עוד</span>) <i>time</i>.—הָאִידְּנָא <i>this time, now, to-day</i>. <span class=\"citation\">Targ. Y. Deut. I, 6</span> (usu. with <a href=\"#\" data-headword=\"ע\">ע</a>).—<span class=\"citation\">Yeb. 62ᵃ</span> <span dir=\"rtl\">לילא דהא׳</span> this night. <span class=\"citation\">Yoma 19ᵇ</span> <span dir=\"rtl\">הא׳ יומא וכ׳</span> to-day is the Day of Atone. <span class=\"citation\">Ber. 4ᵃ</span> <span dir=\"rtl\">כי הא׳</span> at this very time (hour). <span class=\"citation\">Kidd. 71ᵇ</span> <span dir=\"rtl\">והא׳ דאיכא רמאי</span> but now-a-days when there are deceivers; a. fr.</div>","alt":["אִידְּנָא"]},"1169":{"h":"אִידַּר","r":"A01169","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אִדַּר\">אִדַּר</a></div>","alt":["אִידְּרָא"]},"1170":{"h":"*אידרוטירון","r":"A01170","html":"<div class=\"sense\">, read</div>","alt":[]},"1171":{"h":"*אִידְרוֹמִילוֹן","r":"A01171","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ὑδρόμηλον) <i>a cider of quince jelly</i>. Y. Shebi. III, beg. 37ᵇ</div>","alt":[]},"1172":{"h":"אִידְּרוֹן","r":"A01172","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"אֵדֶר I\">אדר</a>; Assyr. <i>idrânu</i>, v. Fred. Del. Hebr. Lang. p. 24; cmp. <a href=\"#\" data-headword=\"חֶדֶר\">חֵדֶר</a>) <i>an enclosure, chamber</i>, esp. <i>dark alcove, bed-room</i>. <span class=\"citation\">Targ. Job XXXVII, 9</span>. <span class=\"citation\">Meg. 26ᵇ</span> <span dir=\"rtl\">איד׳ דהוה וכ׳</span> a room where the corpse was placed before burial. <span class=\"citation\">B. Bath. 7ᵃ</span> <span dir=\"rtl\">השתא משוית לי איד׳</span> ed. (Ms. M. <span dir=\"rtl\">והשתא אינד׳</span>) now thou makest my (formerly open) compartment a lightless alcove. <span class=\"citation\">Ḥull. 52ᵇ</span>; a. e.—<span class=\"citation\">Men. 33ᵇ</span> (fem.) <span dir=\"rtl\">א׳ מעלייתא</span> a fine room. <span class=\"citation\">B. Kam. 85ᵇ</span>, v. <a href=\"#\" data-headword=\"הַרְזֵק\">הַרְזֵק</a>. <span class=\"citation\">Taan. 25ᵃ</span> <span dir=\"rtl\">עיילא לאינ׳</span> she went up to the bed-room.</div>","alt":["אִידְּרוֹנָא","אִינְדְּרוֹנָא","אִנְדְּרוֹנָא"]},"1173":{"h":"אִידְּרוֹנָה","r":"A01173","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"אִידְּרוֹן\">preced.</a></div>","alt":[]},"1174":{"h":"אִידְּרִי","r":"A01174","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"דְּרֵי II\"><span dir=\"rtl\">דְּרִי</span> II</a></div>","alt":[]},"1175":{"h":"אִידְרְעָא = אֶדְרְעָא","r":"A01175","html":"","alt":[]},"1176":{"h":"*אידרתו","r":"A01176","html":"<div class=\"sense\">, <span class=\"citation\">Koh. R. to IV, 7</span> <span dir=\"rtl\">זו אידרתו של מלאך המות</span> (Var. in Y’dê Mosheh a. l. <span dir=\"rtl\">של א&quot;ה</span>), a corruption of a mutilated clause, part of which is to be found in <span class=\"citation\">Deut. R. s. 2</span> where <span class=\"citation\">Prov. XXIV, 21</span> is reprehended and Solomon is made to emend it with <span class=\"citation\">Koh. IV, 8</span> <span dir=\"rtl\">יש אחד ואין שני</span>. The passage restored would probably read: <span dir=\"rtl\">זו ירא את ר׳ בני ומלך עם וג׳</span>. <span dir=\"rtl\">אמר ר׳ אחא כעס הקב&quot;ה … חזר ופירש את הדבר יש אחד ואין שני וכ׳</span>.</div>","alt":[]},"1177":{"h":"*אידתיקרימא","r":"A01177","html":"<div class=\"sense\"> <span class=\"citation\">Y. Dem. V, 24ᵈ</span>, a corruption; prob. <span dir=\"rtl\">אִינוֹקְפֵילַיָּא</span> m. pl. (οἰνοκάπηλοι) <i>keepers of wine-shops</i>, opp. <span dir=\"rtl\">שפייא</span>; q. v.</div>","alt":[]},"1178":{"h":"אַיָּה","r":"A01178","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ayah</i>. <span class=\"citation\">Git. 35ᵃ</span> א׳ מרי A. Mari, surname of one Aḥa b. Hidya.</div>","alt":[]},"1179":{"h":"אִיהָא","r":"A01179","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אִיהוּ\">next w.</a> a. <a href=\"#\" data-headword=\"הָא I\">הָא</a>) <i>that, the same</i>. <span class=\"citation\">Targ. Ruth I, 16</span>.</div>","alt":[]},"1180":{"h":"אִיהוּ","r":"A01180","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, <a href=\"#\" data-headword=\"אִיהִי I\">אִיהִי</a> f. (= <a href=\"#\" data-headword=\"הוּ\">הוּ</a>, <a href=\"#\" data-headword=\"הוּא ²\">הִי</a>, v. <a href=\"#\" data-headword=\"אִ־\">אִ־</a>) <i>he, himself; she, herself</i>. <span class=\"citation\">Targ. Y. Lev. V, 3</span>. <span class=\"citation\">Targ. Esth. I, 1</span>; a. v. fr.—<span class=\"citation\">Gen. R. s. 49</span> <span dir=\"rtl\">יסב א׳ וכ׳</span> let himself take ashes; a. fr.—Pl. <a href=\"#\" data-headword=\"אִינְהוּ\">אִינְהוּ</a> m., <a href=\"#\" data-headword=\"אִינְהוּ\">אִינְהִי</a> f.; <a href=\"#\" data-headword=\"נִיהוּ\">נִיהוּ</a>, <a href=\"#\" data-headword=\"נִינְהוּ\">נִינְהוּ</a>; <a href=\"#\" data-headword=\"אִינָךְ\">אִינָךְ</a>, <a href=\"#\" data-headword=\"אִינוּן\">אִינוּן</a> m., <a href=\"#\" data-headword=\"אִינִין\">אִינִין</a> f. (contr. <a href=\"#\" data-headword=\"אִנּוּן\">אִנּוּן</a>, <a href=\"#\" data-headword=\"אָנִין\">אִנִּין</a>); very freq.—Y. Bicc. II, end, 65ᵇ <span dir=\"rtl\">דינון מרין</span> = <span dir=\"rtl\">דאינון אמרין</span>. <span class=\"citation\">Y. Meg. I, 71ᵃ</span> top <span dir=\"rtl\">אילין אינין</span> are there only these (differences between the Sabbath and Festivals)?</div>","alt":["אִיהוּא"]},"1181":{"h":"אִיהִי I","r":"A01181","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"אִיהוּ\">foreg.</a></div>","alt":[]},"1182":{"h":"*אִיהִי II","r":"A01182","html":"<div class=\"sense\">, <span dir=\"rtl\">א׳ דַקִּירָא</span> (<a href=\"#\" data-headword=\"הַאי\">האי</a>) pr. n. pl. <i>Ihi Dakkira</i>, <i>Is</i>, a city on the W. banks of the Euphrates, and upon a little river of the same name; (v. Rapap. Er. Mill. p. 33, a. Sm. Class. Dict. s. v. Is). <span class=\"citation\">Kidd. 72ᵃ</span> <span dir=\"rtl\">א׳ ד׳</span> (Ar. <a href=\"#\" data-headword=\"הַאי\">האי</a>). <span class=\"citation\">B. Bath. 24ᵃ</span> Ms. R. <span dir=\"rtl\">א׳ דקי׳</span> (ed. <span dir=\"rtl\">האי דקרא</span>, v. Rabb. D. S. a. l.). <span class=\"citation\">Ber. 59ᵇ</span> (v. Rabb. D. a. l.).</div>","alt":[]},"1183":{"h":"אַיּוֹ","r":"A01183","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ayo</i>, a scholar. <span class=\"citation\">Bets. 37ᵇ</span>; a. fr.</div>","alt":[]},"1184":{"h":"אִיֹּוב","r":"A01184","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Job</i>, the personage after whom the Biblical book (<span dir=\"rtl\">ספר א׳</span>) <i>the Book of Job</i> is named. <span class=\"citation\">B. Bath. 14ᵇ</span>; <span class=\"citation\">15ᵃ</span> sq. <span class=\"citation\">Y. Sot. V, end, 20ᶜ</span>ᵈ. <span class=\"citation\">Nidd. 52ᵃ</span>; <span class=\"citation\">52ᵇ</span>; a. fr.</div>","alt":[]},"1185":{"h":"איוונטיאות","r":"A01185","html":"<div class=\"sense\"> <span class=\"citation\">Yalk. Ex. 376</span>, read <span dir=\"rtl\">אוותנטאות</span>, v. <a href=\"#\" data-headword=\"אַוְותֶּנְטִי\">אַוְותֶּנְטִי</a></div>","alt":[]},"1186":{"h":"אִיוְיָא","r":"A01186","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִוְיָא I\">אִוְיָא</a></div>","alt":[]},"1187":{"h":"איול","r":"A01187","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אַיִל\">אַיִל</a> 2).</div>","alt":["אייול"]},"1188":{"h":"אִיזָּא","r":"A01188","html":"<div class=\"sense\"><i>, </i> pl. <span dir=\"rtl\">אִיזַיָּא</span> m. (<span dir=\"rtl\">אזז</span>, cmp. <a href=\"#\" data-headword=\"גְּזִיזָא\">גזיזא</a>, <a href=\"#\" data-headword=\"חָזִיז\">חזיז</a>, <span dir=\"rtl\">אזד</span>) <i>prickly twigs</i>. <span class=\"citation\">Y. Maas. Sh. IV, 55ᵇ</span> bot. (to one who dreamt that people ran before him—meaning power) <span dir=\"rtl\">דאת מייתי א׳ וכ׳</span> thou wilt carry prickly twigs and everybody will run away from thee. [V. Lam. R. quot. s. v. <a href=\"#\" data-headword=\"גְּבַב\">גְּבַב</a>.]</div>","alt":[]},"1189":{"h":"אֵיזֹבְיָוָן","r":"A01189","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֵזוֹב\">אֵזוֹב</a></div>","alt":[]},"1190":{"h":"אִיזְגַּד","r":"A01190","html":"<div class=\"sense\"> (Targ. Y. <a href=\"#\" data-headword=\"עִזְגַּד\">עִזְגַּד</a>, <a href=\"#\" data-headword=\"עִזְגַּד\">עַזְגַּד</a>) m. (contr. of <span dir=\"rtl\">גזגזדא</span>, <a href=\"#\" data-headword=\"ג\">ג</a> softened into <a href=\"#\" data-headword=\"א\">א</a> or <a href=\"#\" data-headword=\"ע\">ע</a>, cmp. <span dir=\"rtl\">אזד</span>, <a href=\"#\" data-headword=\"*אַדְרַזְדָּא\">אדרזדא</a>; also <span dir=\"rtl\">מזדנדז</span> = <span dir=\"rtl\">מזדעזע</span>, s. v. <span dir=\"rtl\">זעזע</span>; Massorah <span dir=\"rtl\">אִיסְגַּד־</span>, <span dir=\"rtl\">אִסְגַּד־</span>, Ispe. of <span dir=\"rtl\">גזז</span>; Berl. Targ. O. II, pp. 63, 68; cmp. Mand. <span dir=\"rtl\">אשגאנדא</span>, Nöld. Mand. Gr. lithog. table; v. <a href=\"#\" data-headword=\"גּוּז\">גּוּז</a>, <span dir=\"rtl\">גזז</span>) <i>runner</i>. <span class=\"citation\">Targ. Y. Gen. XLIX, 21</span> <span dir=\"rtl\">ע׳ קליל</span> a light runner; a. e. In gen. <i>messenger. </i> Pl. <span dir=\"rtl\">אִיזְגַּדִּין</span>, <a href=\"#\" data-headword=\"אִיזְגַּד\">אִיזְגַּדַיָּא</a>, <a href=\"#\" data-headword=\"עִזְקָא ²\">עִזְ׳</a>, <a href=\"#\" data-headword=\"עֻזְיָא\">עַזְ</a>, <a href=\"#\" data-headword=\"*אִסְטַבְלָא\">אִיסְ׳</a>. <span class=\"citation\">Targ. Is. XVIII, 2</span>; a. v. fr.</div>","alt":["אִיזְגַּדָּא"]},"1191":{"h":"אִיזְגְּדַר","r":"A01191","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (for <span dir=\"rtl\">איזדגרד</span>) <i>Yesdigerd, Yezdjird</i>, a Persian King. <span class=\"citation\">Zeb. 19ᵃ</span> top. <span class=\"citation\">Keth. 61ᵃ</span> bot. <span dir=\"rtl\">אזגוד</span> (corr. acc.).</div>","alt":[]},"1192":{"h":"*אִיזְגָּרָא","r":"A01192","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, pl. <span dir=\"rtl\">אִיזְגָּרִין</span> (<a href=\"#\" data-headword=\"גָּרַר I\">גרר</a>, v. <a href=\"#\" data-headword=\"אֵגוֹר\">אֵגוֹר</a>; prefix <a href=\"#\" data-headword=\"*אִזְתַּוְודָּא\">איז׳</a>, cmp. <a href=\"#\" data-headword=\"אִיזְמֵיל\">אִיזְמֵל</a> a. <a href=\"#\" data-headword=\"אִיזְגַּד\">אִיזְגַּד</a>) <i>mounds</i>. <span class=\"citation\">Gen. R. s. 74</span> <span dir=\"rtl\">בחקל דאית ביה א׳ וכ׳</span> in a field in which there are mounds (behind which people may hide) talk no secrets. [Muss. incorr. <a href=\"#\" data-headword=\"ד\">ד</a> for <a href=\"#\" data-headword=\"ר\">ר</a>.]</div>","alt":[]},"1193":{"h":"אִיזְדקַר","r":"A01193","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"זְקַר\">זְקַר</a></div>","alt":[]},"1194":{"h":"אֵיזֶה","r":"A01194","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, <a href=\"#\" data-headword=\"אֵיזוּ\">אֵיזוּ</a> f. (b. h. <i>who? what? which?</i> <span class=\"citation\">Ab. IV, 1</span> <span dir=\"rtl\">איזהו חכם</span> who is wise?; a. v. fr.—<span dir=\"rtl\">באיזה צד</span> in what manner, v. <a href=\"#\" data-headword=\"כֵּיצַד\">כֵּיצַד</a>. [Chald. <a href=\"#\" data-headword=\"אֵידֵין\">אֵידֵין</a>, <a href=\"#\" data-headword=\"אָדָא II\">אֵידָא</a>.]</div>","alt":["אֵיזֶהוּ","אֵזֶ׳"]},"1195":{"h":"אֵיזוּ","r":"A01195","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֵיזֶה\">foreg.</a>, a. <a href=\"#\" data-headword=\"אֵיזִי\">אֵיזִי</a>.</div>","alt":[]},"1196":{"h":"אֵיזוֹב","r":"A01196","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֵיזֶה\">אֵז׳</a></div>","alt":["אֵיזוֹבָא"]},"1197":{"h":"אֵיזִי","r":"A01197","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"אֵיזֶה\">אֵיזֶה</a> = b. h. <span dir=\"rtl\">אֵיפוֹא</span>, <span dir=\"rtl\">אֵפֹה</span>, <a href=\"#\" data-headword=\"אפו\">אֵפוֹ</a>) <i>now, then, pray</i>. <span class=\"citation\">Yoma 30ᵇ</span> <span dir=\"rtl\">אודו לי א׳</span> (miss. in Mss., Ms. M. 2 <span dir=\"rtl\">זי</span>) admit then at least. <span class=\"citation\">B. Mets. 70ᵃ</span> <span dir=\"rtl\">אימא לי איזו</span> tell me now; a. e. V. <a href=\"#\" data-headword=\"הֵידֵין\">הֵידֵין</a>.</div>","alt":["אֵיזוּ"]},"1198":{"h":"אִיזְלָא","r":"A01198","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (אֲזַל II) <i>web, net</i>, &amp;c. <span class=\"citation\">Ḥull. 51ᵇ</span> <span dir=\"rtl\">אי׳ ומקרבי קיטרי</span> a net in which the knots are close. <span class=\"citation\">Erub. 28ᵇ</span> אוזלתא דאיכרי Ms. M. (ed. <a href=\"#\" data-headword=\"אוּזִילְתָּא\">אוזילתא</a>, Ar. <span dir=\"rtl\">איזולתא</span>) the twist (of bunches) of the farmer.—Pl. <span dir=\"rtl\">אִיזְלֵי</span>. <span class=\"citation\">M. Kat. 11ᵃ</span>. <span class=\"citation\">Git. 60ᵇ</span> <span dir=\"rtl\">אוּזְלֵי</span>; v. <a href=\"#\" data-headword=\"אוֹהֲרָא\">אוֹהֲרָא</a>.—<span class=\"citation\">Erub. 8ᵃ</span> <span dir=\"rtl\">פסק ליה לסורא באו׳</span> (ed. Sonc. <a href=\"#\" data-headword=\"אִסְקְרִיטִין\">אי׳</a>) he separated the court-yards of Sura with nets (<i>hurdles, matting</i>).</div>","alt":["אוּזְלָא","אוּזַלְתָּא"]},"1199":{"h":"אִיזְמָא","r":"A01199","html":"<div class=\"sense\"> m., v. <a href=\"#\" data-headword=\"הִיזְמָא\">הִיזְמָא</a>. <span class=\"citation\">Tosef. Kil. I, 11</span> ed. Zuck. (ed. corrupt <a href=\"#\" data-headword=\"אזמאזמא\">אזמאזמא</a>).</div>","alt":[]}};
